export default "= None,\\n        user_id: str | None = None,\\n        timing: bool = False,\\n    ) -> FlowResult:\\n        \\\"\\\"\\\"Execute a flow asynchronously and return a :class:`FlowResult`.\\\"\\\"\\\"\\n        raw = await _run_async(\\n            **self._build_run_kwargs(\\n                flow,\\n                input_value,\\n                tweaks=tweaks,\\n                global_variables=global_variables,\\n                env_file=env_file,\\n                timeout=timeout,\\n                check_variables=check_variables,\\n                session_id=session_id,\\n                user_id=user_id,\\n                timing=timing,\\n            )\\n        )\\n        return _build_result(raw)\\n\\n\\n# ---------------------------------------------------------------------------\\n# Remote runners (requires langflow-sdk)\\n# ---------------------------------------------------------------------------\\n\\n\\nclass RemoteFlowRunner(_BaseRemoteFlowRunner):\\n    \\\"\\\"\\\"Sync callable that runs flows against a live Langflow instance.\\n\\n    Returned by :func:`flow_runner` when ``--langflow-env`` or\\n    ``--langflow-url`` is passed to pytest.  Call it like a function::\\n\\n        def test_greeting(flow_runner):\\n            result = flow_runner(\\\"greeting-endpoint\\\", \\\"Hello!\\\")\\n            assert result.first_text_output() is not None\\n\\n    The first argument is a flow endpoint name or UUID (not a local file\\n    path).  Keyword arguments that only apply to local execution (e.g.\\n    ``env_file``, ``global_variables``) are accepted but silently ignored\\n    so that test code is portable between local and remote modes.\\n    \\\"\\\"\\\"\\n\\n    def __call__(\\n        self,\\n        flow_id_or_endpoint: str,\\n        input_value: str = \\\"\\\",\\n        *,\\n        input_type: str = \\\"chat\\\",\\n        output_type: str = \\\"chat\\\",\\n        tweaks: dict[str, Any] | None = None,\\n        **_kwargs: Any,\\n    ) -> FlowResult:\\n        \\\"\\\"\\\"Run *flow_id_or_endpoint* against the remote instance.\\\"\\\"\\\"\\n        request = self._build_run_request(\\n            input_value=input_value,\\n            input_type=input_type,\\n            output_type=output_type,\\n            tweaks=tweaks,\\n        )\\n\\n        try:\\n            response = self._client.run_flow(flow_id_or_endpoint, request)\\n        except Exception as exc:  # noqa: BLE001\\n            return _build_remote_error_result(exc)\\n\\n        return _build_result_from_sdk_response(response)\\n\\n\\nclass AsyncRemoteFlowRunner(_BaseRemoteFlowRunner):\\n    \\\"\\\"\\\"Async callable that runs flows against a live Langflow instance.\\n\\n    Returned by :func:`async_flow_runner` when ``--langflow-env`` or\\n    ``--langflow-url`` is passed to pytest.  Use with ``await``::\\n\\n        async def test_greeting(async_flow_runner):\\n            result = await async_flow_runner(\\\"greeting-endpoint\\\", \\\"Hello!\\\")\\n            assert result.first_text_output() is not None\\n    \\\"\\\"\\\"\\n\\n    async def __call__(\\n        self,\\n        flow_id_or_endpoint: str,\\n        input_value: str = \\\"\\\",\\n        *,\\n        input_type: str = \\\"chat\\\",\\n        output_type: str = \\\"chat\\\",\\n        tweaks: dict[str, Any] | None = None,\\n        **_kwargs: Any,\\n    ) -> FlowResult:\\n        \\\"\\\"\\\"Run *flow_id_or_endpoint* asynchronously against the remote instance.\\\"\\\"\\\"\\n        request = self._build_run_request(\\n            input_value=input_value,\\n            input_type=input_type,\\n            output_type=output_type,\\n            tweaks=tweaks,\\n        )\\n\\n        try:\\n            response = await self._client.run_flow(flow_id_or_endpoint, request)\\n        except Exception as exc:  # noqa: BLE001\\n            return _build_remote_error_result(exc)\\n\\n        return _build_result_from_sdk_response(response)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/tests/unit/components/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/tests/unit/components/agentics/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/tests/unit/components/agentics/test_amap_duplicate_columns.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"67f50fb8e9dbbaa4bc5592aced74a647a4ab80f3325379be66943e7c906f2196\",\"content\":\"\\\"\\\"\\\"Test for aMap bug: duplicate columns when Keep Source Columns is enabled on re-run.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom agentics import AG\\nfrom agentics.core.atype import create_pydantic_model\\nfrom lfx.components.agentics.helpers.schema_builder import build_schema_fields\\n\\n\\nclass TestAMapDuplicateColumns:\\n    \\\"\\\"\\\"Tests for the duplicate column bug when source already contains output schema columns.\\\"\\\"\\\"\\n\\n    def test_should_merge_without_error_when_source_has_overlapping_columns(self):\\n        \\\"\\\"\\\"Reproduces the exact bug: merge_states fails with 'got multiple values for keyword argument'.\\n\\n        When the source DataFrame already contains columns matching the output schema.\\n        \\\"\\\"\\\"\\n        # Arrange \u2014 simulate a table that was already processed by aMap\\n        # (source already contains 'full_name' and 'age_group' from a previous run)\\n        source_fields = build_schema_fields(\\n            [\\n                (\\\"customer_id\\\", \\\"Customer ID\\\", \\\"str\\\", False),\\n                (\\\"email\\\", \\\"Email address\\\", \\\"str\\\", False),\\n                (\\\"full_name\\\", \\\"Full name\\\", \\\"str\\\", False),\\n                (\\\"age_group\\\", \\\"Age group\\\", \\\"str\\\", False),\\n            ]\\n        )\\n        source_atype = create_pydantic_model(source_fields, name=\\\"Source\\\")\\n        source = AG(\\n            atype=source_atype,\\n            states=[\\n                source_atype(customer_id=\\\"1\\\", email=\\\"a@test.com\\\", full_name=\\\"Alice Smith\\\", age_group=\\\"adult\\\"),\\n                source_atype(customer_id=\\\"2\\\", email=\\\"b@test.com\\\", full_name=\\\"Bob Jones\\\", age_group=\\\"senior\\\"),\\n            ],\\n        )\\n\\n        # Output schema has overlapping columns (full_name, age_group)\\n        output_fields = build_schema_fields(\\n            [\\n                (\\\"full_name\\\", \\\"Full name\\\", \\\"str\\\", False),\\n                (\\\"age_group\\\", \\\"Age group\\\", \\\"str\\\", False),\\n            ]\\n        )\\n        output_atype = create_pydantic_model(output_fields, name=\\\"Target\\\")\\n        output = AG(\\n            atype=output_atype,\\n            states=[\\n                output_atype(full_name=\\\"Alice Updated\\\", age_group=\\\"young_adult\\\"),\\n                output_atype(full_name=\\\"Bob Updated\\\", age_group=\\\"elderly\\\"),\\n            ],\\n        )\\n\\n        # Act & Assert \u2014 this should NOT raise TypeError about duplicate keyword arguments\\n        result = source.merge_states(output)\\n\\n        # The merge should produce valid results\\n        result_df = result.to_dataframe()\\n        assert len(result_df) > 0  # noqa: S101\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/type_extraction.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"de03c897d00c03c52ab8d1bb13f3a1e3ff6793904695456e07deea8d2baee738\",\"content\":\"\\\"\\\"\\\"Type extraction utilities copied from langflow for lfx package.\\\"\\\"\\\"\\n\\nimport re\\nfrom collections.abc import Sequence as SequenceABC\\nfrom itertools import chain\\nfrom types import GenericAlias, UnionType\\nfrom typing import Any, Union, get_args, get_origin\\n\\n\\ndef extract_inner_type_from_generic_alias(return_type: GenericAlias) -> Any:\\n    \\\"\\\"\\\"Extracts the inner type from a type hint that is a list or a Optional.\\\"\\\"\\\"\\n    if get_origin(return_type) in {list, SequenceABC}:\\n        return list(get_args(return_type))\\n    return return_type\\n\\n\\ndef extract_inner_type(return_type: str) -> str:\\n    \\\"\\\"\\\"Extracts the inner type from a type hint that is a list.\\\"\\\"\\\"\\n    if match := re.match(r\\\"list\\\\[(.*)\\\\]\\\", return_type, re.IGNORECASE):\\n        return match[1]\\n    return return_type\\n\\n\\ndef extract_union_types(return_type: str) -> list[str]:\\n    \\\"\\\"\\\"Extracts the inner type from a type hint that is a list.\\\"\\\"\\\"\\n    # If the return type is a Union, then we need to parse it\\n    return_type = return_type.replace(\\\"Union\\\", \\\"\\\").replace(\\\"[\\\", \\\"\\\").replace(\\\"]\\\", \\\"\\\")\\n    return_types = return_type.split(\\\",\\\")\\n    return [item.strip() for item in return_types]\\n\\n\\ndef extract_uniont_types_from_generic_alias(return_type: GenericAlias) -> list:\\n    \\\"\\\"\\\"Extracts the inner type from a type hint that is a Union.\\\"\\\"\\\"\\n    if isinstance(return_type, list):\\n        return [\\n            _inner_arg\\n            for _type in return_type\\n            for _inner_arg in get_args(_type)\\n            if _inner_arg not in {Any, type(None), type(Any)}\\n        ]\\n\\n    return list(get_args(return_type))\\n\\n\\ndef post_process_type(type_):\\n    \\\"\\\"\\\"Process the return type of a function.\\n\\n    Args:\\n        type_ (Any): The return type of the function.\\n\\n    Returns:\\n        Union[List[Any], Any]: The processed return type.\\n\\n    \\\"\\\"\\\"\\n    if get_origin(type_) in {list, SequenceABC}:\\n        type_ = extract_inner_type_from_generic_alias(type_)\\n\\n    # If the return type is not a Union, then we just return it as a list\\n    inner_type = type_[0] if isinstance(type_, list) else type_\\n    if get_origin(inner_type) not in {Union, UnionType}:\\n        return type_ if isinstance(type_, list) else [type_]\\n    # If the return type is a Union, then we need to parse it\\n    type_ = extract_union_types_from_generic_alias(type_)\\n    type_ = set(chain.from_iterable([post_process_type(t) for t in type_]))\\n    return list(type_)\\n\\n\\ndef extract_union_types_from_generic_alias(return_type: GenericAlias) -> list:\\n    \\\"\\\"\\\"Extracts the inner type from a type hint that is a Union.\\\"\\\"\\\"\\n    if isinstance(return_type, list):\\n        return [\\n            _inner_arg\\n            for _type in return_type\\n            for _inner_arg in get_args(_type)\\n            if _inner_arg not in {Any, type(None), type(Any)}\\n        ]\\n\\n    return list(get_args(return_type))\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/type_extraction/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"f242948ee75b3879181d510e035e230f803ef545251b5963d6bce72ae5a83e4d\",\"content\":\"\\\"\\\"\\\"Type extraction module for lfx package.\\\"\\\"\\\"\\n\\nfrom lfx.type_extraction.type_extraction import (\\n    extract_inner_type,\\n    extract_inner_type_from_generic_alias,\\n    extract_union_types,\\n    extract_union_types_from_generic_alias,\\n    extract_uniont_types_from_generic_alias,\\n    post_process_type,\\n)\\n\\n__all__ = [\\n    \\\"extract_inner_type\\\",\\n    \\\"extract_inner_type_from_generic_alias\\\",\\n    \\\"extract_union_types\\\",\\n    \\\"extract_union_types_from_generic_alias\\\",\\n    \\\"extract_uniont_types_from_generic_alias\\\",\\n    \\\"post_process_type\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/type_extraction/type_extraction.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"0783fe7807d40fd8b436aa21767b605373412d4ff48c3735f0bdfa950b1886b6\",\"content\":\"import re\\nfrom collections.abc import Sequence as SequenceABC\\nfrom itertools import chain\\nfrom types import GenericAlias, UnionType\\nfrom typing import Any, Union, get_args, get_origin\\n\\n\\ndef extract_inner_type_from_generic_alias(return_type: GenericAlias) -> Any:\\n    \\\"\\\"\\\"Extracts the inner type from a type hint that is a list or a Optional.\\\"\\\"\\\"\\n    if get_origin(return_type) in {list, SequenceABC}:\\n        return list(get_args(return_type))\\n    return return_type\\n\\n\\ndef extract_inner_type(return_type: str) -> str:\\n    \\\"\\\"\\\"Extracts the inner type from a type hint that is a list.\\\"\\\"\\\"\\n    if match := re.match(r\\\"list\\\\[(.*)\\\\]\\\", return_type, re.IGNORECASE):\\n        return match[1]\\n    return return_type\\n\\n\\ndef extract_union_types(return_type: str) -> list[str]:\\n    \\\"\\\"\\\"Extracts the inner type from a type hint that is a list.\\\"\\\"\\\"\\n    # If the return type is a Union, then we need to parse it\\n    return_type = return_type.replace(\\\"Union\\\", \\\"\\\").replace(\\\"[\\\", \\\"\\\").replace(\\\"]\\\", \\\"\\\")\\n    return_types = return_type.split(\\\",\\\")\\n    return [item.strip() for item in return_types]\\n\\n\\ndef extract_uniont_types_from_generic_alias(return_type: GenericAlias) -> list:\\n    \\\"\\\"\\\"Extracts the inner type from a type hint that is a Union.\\\"\\\"\\\"\\n    if isinstance(return_type, list):\\n        return [\\n            _inner_arg\\n            for _type in return_type\\n            for _inner_arg in get_args(_type)\\n            if _inner_arg not in {Any, type(None), type(Any)}\\n        ]\\n    return list(get_args(return_type))\\n\\n\\ndef post_process_type(type_):\\n    \\\"\\\"\\\"Process the return type of a function.\\n\\n    Args:\\n        type_ (Any): The return type of the function.\\n\\n    Returns:\\n        Union[List[Any], Any]: The processed return type.\\n    \\\"\\\"\\\"\\n    if get_origin(type_) in {list, SequenceABC}:\\n        type_ = extract_inner_type_from_generic_alias(type_)\\n\\n    # If the return type is not a Union, then we just return it as a list\\n    inner_type = type_[0] if isinstance(type_, list) else type_\\n    if get_origin(inner_type) not in {Union, UnionType}:\\n        return type_ if isinstance(type_, list) else [type_]\\n    # If the return type is a Union, then we need to parse it\\n    type_ = extract_union_types_from_generic_alias(type_)\\n    type_ = set(chain.from_iterable([post_process_type(t) for t in type_]))\\n    return list(type_)\\n\\n\\ndef extract_union_types_from_generic_alias(return_type: GenericAlias) -> list:\\n    \\\"\\\"\\\"Extracts the inner type from a type hint that is a Union.\\\"\\\"\\\"\\n    if isinstance(return_type, list):\\n        return [\\n            _inner_arg\\n            for _type in return_type\\n            for _inner_arg in get_args(_type)\\n            if _inner_arg not in {Any, type(None), type(Any)}\\n        ]\\n    return list(get_args(return_type))\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/upgrade/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"7f8c95852ec1fa71d6fedbd48b7873af8643484c2a45046e9021ffba789e7031\",\"content\":\"\\\"\\\"\\\"LFX flow upgrade utilities.\\\"\\\"\\\"\\n\\nfrom lfx.upgrade.applier import apply_safe_upgrades\\nfrom lfx.upgrade.checker import CompatibilityReport, NodeStatus, check_flow_compatibility\\n\\n__all__ = [\\\"CompatibilityReport\\\", \\\"NodeStatus\\\", \\\"apply_safe_upgrades\\\", \\\"check_flow_compatibility\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/upgrade/applier.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"c646c0f9d8a07269a977055dd61633d03ed12cd99022ce95e774165f5cbf6743\",\"content\":\"\\\"\\\"\\\"Apply safe upgrades to a flow dict.\\n\\nReturns a deep copy of the flow with safe-upgradeable node codes replaced by the\\ncurrent registry code and any template fields the saved flow predates introduced\\nwith their registry defaults. Breaking and blocked nodes are left unchanged.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport copy\\nfrom typing import TYPE_CHECKING, Any\\n\\nif TYPE_CHECKING:\\n    from collections.abc import Mapping\\n\\nfrom lfx.upgrade.checker import CompatibilityReport, build_registry_lookup, new_template_field_keys\\n\\n\\ndef apply_safe_upgrades(\\n    flow_data: dict,\\n    all_types_dict: Mapping[str, Any],\\n    report: CompatibilityReport,\\n    *,\\n    return_count: bool = False,\\n    registry: dict[str, dict] | None = None,\\n) -> dict | tuple[dict, int]:\\n    \\\"\\\"\\\"Return a deep copy of flow_data with safe node codes updated.\\n\\n    Args:\\n        flow_data: Parsed flow JSON with a ``nodes`` list.\\n        all_types_dict: Component registry (same shape as ``check_flow_compatibility``).\\n        report: Pre-computed CompatibilityReport from ``check_flow_compatibility``.\\n        return_count: If True, return a (flow, count) tuple where count is the\\n                      number of nodes that were updated.\\n        registry: Optional pre-built lookup from ``build_registry_lookup``. Pass this to avoid\\n                  rebuilding it when the caller already built it for ``check_flow_compatibility``.\\n\\n    Returns:\\n        Updated flow dict (deep copy), or (flow, count) if return_count=True.\\n    \\\"\\\"\\\"\\n    safe_ids = {n.node_id for n in report.nodes if n.status == \\\"outdated_safe\\\"}\\n    if not safe_ids:\\n        updated = copy.deepcopy(flow_data)\\n        return (updated, 0) if return_count else updated\\n\\n    if registry is None:\\n        registry = build_registry_lookup(all_types_dict)\\n    updated = copy.deepcopy(flow_data)\\n    count = _apply_to_nodes(updated.get(\\\"nodes\\\", []), safe_ids, registry)\\n\\n    return (updated, count) if return_count else updated\\n\\n\\ndef _apply_to_nodes(nodes: list[dict], safe_ids: set[str], registry: dict[str, dict]) -> int:\\n    \\\"\\\"\\\"Walk top-level nodes and (one level of) nested flow nodes, applying safe upgrades.\\n\\n    Mirrors check_flow_compatibility's recursion into ``node.data.node.flow.data.nodes``\\n    so safe-upgradeable nodes inside grouped components are written, not silently skipped.\\n    \\\"\\\"\\\"\\n    count = 0\\n    for node in nodes:\\n        node_id = node.get(\\\"data\\\", {}).get(\\\"id\\\") or node.get(\\\"id\\\")\\n        if node_id in safe_ids:\\n            component_type = node.get(\\\"data\\\", {}).get(\\\"type\\\", \\\"\\\")\\n            entry = registry.get(component_type)\\n            if entry:\\n                registry_template = entry.get(\\\"template\\\", {})\\n                registry_code_field = registry_template.get(\\\"code\\\")\\n                new_code = registry_code_field.get(\\\"value\\\") if isinstance(registry_code_field, dict) else None\\n                if new_code is not None:\\n                    flow_template = node[\\\"data\\\"][\\\"node\\\"][\\\"template\\\"]\\n                    flow_template[\\\"code\\\"][\\\"value\\\"] = new_code\\n                    # The checker calls a node safe when the registry grew fields the saved\\n                    # flow predates; the re-stamped code reads those fields, so introduce\\n                    # each one exactly as the registry declares it \u2014 the state a freshly\\n                    # added component would carry. Deep-copied so later edits to the\\n                    # upgraded flow cannot reach back into the shared registry lookup.\\n                    for key in new_template_field_keys(registry_template, flow_template):\\n                        flow_template[key] = copy.deepcopy(registry_template[key])\\n                    count += 1\\n        nested = node.get(\\\"data\\\", {}).get(\\\"node\\\", {}).get(\\\"flow\\\", {}).get(\\\"data\\\", {}).get(\\\"nodes\\\")\\n        if nested:\\n            count += _apply_to_nodes(nested, safe_ids, registry)\\n    return count\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/upgrade/checker.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"8c1835e0ed5e81980d7aee867bc62e2547ce21520de9d9182ac772841d41e3d8\",\"content\":\"\\\"\\\"\\\"Compatibility checker: Python port of check-code-validity.ts.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom collections.abc import Mapping\\nfrom dataclasses import dataclass, field\\nfrom typing import Any, Literal\\n\\nCOMPONENTS_TO_IGNORE_UPDATE: frozenset[str] = frozenset({\\\"CustomComponent\\\"})\\nTRANSIENT_TEMPLATE_KEYS: frozenset[str] = frozenset({\\\"is_refresh\\\", \\\"tools_metadata\\\"})\\n\\n# Synthetic output name a component receives when it is switched to tool mode. Must match\\n# lfx.base.tools.constants.TOOL_OUTPUT_NAME, duplicated as a literal for the same reason\\n# lfx.graph.flow_builder.connect does it: to keep this module free of lfx.base imports.\\nTOOL_OUTPUT_NAME = \\\"component_as_tool\\\"\\n\\nNodeStatusLiteral = Literal[\\\"ok\\\", \\\"outdated_safe\\\", \\\"outdated_breaking\\\", \\\"blocked\\\"]\\n\\n\\n@dataclass\\nclass NodeStatus:\\n    node_id: str\\n    component_type: str\\n    display_name: str\\n    status: NodeStatusLiteral\\n\\n\\n@dataclass\\nclass CompatibilityReport:\\n    nodes: list[NodeStatus] = field(default_factory=list)\\n\\n    @property\\n    def has_blocked(self) -> bool:\\n        return any(n.status == \\\"blocked\\\" for n in self.nodes)\\n\\n    @property\\n    def has_breaking(self) -> bool:\\n        return any(n.status == \\\"outdated_breaking\\\" for n in self.nodes)\\n\\n    @property\\n    def has_safe_updates(self) -> bool:\\n        return any(n.status == \\\"outdated_safe\\\" for n in self.nodes)\\n\\n    @property\\n    def is_clean(self) -> bool:\\n        return not self.nodes or all(n.status == \\\"ok\\\" for n in self.nodes)\\n\\n\\ndef build_registry_lookup(all_types_dict: Mapping[str, Any]) -> dict[str, dict]:\\n    \\\"\\\"\\\"Flatten all_types_dict into {component_type: component_data}, including legacy aliases.\\n\\n    Uses flatten_components_with_aliases so that renamed components (e.g. Prompt \u2192\\n    Prompt Template, parser \u2192 ParserComponent) are reachable under their old type key\\n    and are not incorrectly classified as blocked.\\n    \\\"\\\"\\\"\\n    from lfx.utils.component_aliases import flatten_components_with_aliases\\n\\n    return {k: dict(v) for k, v in flatten_components_with_aliases(all_types_dict).items() if isinstance(v, Mapping)}\\n\\n\\ndef _outputs_are_compatible(registry_outputs: list[dict], flow_outputs: list[dict]) -> bool:\\n    \\\"\\\"\\\"Return True if the saved flow's outputs are still valid against the registry's outputs.\\n\\n    Only *breaking* differences count:\\n      - a changed output **name set** (a removed/renamed output breaks downstream edges),\\n      - a changed ``method`` or ``allows_loop``,\\n      - **narrowed** output types: the registry dropped a type the saved flow emitted.\\n\\n    A cosmetic ``display_name`` change (e.g. a typo fix in the registry) and **widened**\\n    types (the registry now emits additional types) are not breaking and must not be flagged,\\n    otherwise ``--upgrade-flow=safe`` would needlessly abort on a string edit.\\n    \\\"\\\"\\\"\\n    flow_map = {o[\\\"name\\\"]: o for o in flow_outputs}\\n    registry_names = {o[\\\"name\\\"] for o in registry_outputs}\\n    if registry_names != set(flow_map):\\n        return False\\n    for reg in registry_outputs:\\n        flow_output = flow_map.get(reg[\\\"name\\\"])\\n        if flow_output is None:\\n            return False\\n        flow_types = set(flow_output.get(\\\"types\\\") or [])\\n        registry_types = set(reg.get(\\\"types\\\") or [])\\n        if (\\n            not flow_types.issubset(registry_types)  # narrowing breaks edges; widening is safe\\n            or reg.get(\\\"method\\\") != flow_output.get(\\\"method\\\")\\n            or reg.get(\\\"allows_loop\\\") != flow_output.get(\\\"allows_loop\\\")\\n        ):\\n            return False\\n    return True\\n\\n\\ndef _structural_template_keys(template: Mapping[str, Any]) -> set[str]:\\n    \\\"\\\"\\\"Return component fields while excluding frontend-only runtime metadata.\\\"\\\"\\\"\\n    return {key for key in template if not key.startswith(\\\"_\\\") and key not in TRANSIENT_TEMPLATE_KEYS}\\n\\n\\ndef new_template_field_keys(registry_template: Mapping[str, Any], flow_template: Mapping[str, Any]) -> set[str]:\\n    \\\"\\\"\\\"Return registry template fields the saved flow predates.\\n\\n    These are the fields ``apply_safe_upgrades`` introduces (with their registry-declared\\n    state) when it re-stamps a safe node's code, so the checker's definition of a safe\\n    upgrade and the applier's write stay in lockstep.\\n    \\\"\\\"\\\"\\n    return _structural_template_keys(registry_template) - _structural_template_keys(flow_template)\\n\\n\\ndef _template_keys_compatible(registry_template: dict, flow_template: dict) -> bool:\\n    \\\"\\\"\\\"Return True unless the registry grew a field a safe upgrade cannot fill.\\n\\n    Template key sets are compared directionally, not for equality:\\n\\n    - A field only the *flow* has is one the registry dropped. Its stale value is not read\\n      once the code is re-stamped, and ``apply_safe_upgrades`` leaves it in place, so an\\n      edge into it keeps its target handle.\\n    - A field only the *registry* has is one the saved flow predates \u2014 the evolution the\\n      contributing docs recommend as non-breaking. ``apply_safe_upgrades`` introduces it\\n      exactly as the registry declares it, so it only breaks when that declared state is\\n      unusable: a *required* field with nothing to fill it, which would turn a flow that\\n      ran into one that fails asking for input.\\n    \\\"\\\"\\\"\\n    for key in new_template_field_keys(registry_template, flow_template):\\n        field = registry_template.get(key)\\n        if isinstance(field, Mapping) and field.get(\\\"required\\\") and field.get(\\\"value\\\") in (None, \\\"\\\"):\\n            return False\\n    return True\\n\\n\\ndef _input_types_contained(registry_template: dict, flow_template: dict) -> bool:\\n    \\\"\\\"\\\"Return True if no input field *narrowed* its accepted ``input_types``.\\n\\n    Narrowing (the registry no longer accepts a type the saved flow's edges feed into) is\\n    breaking. Widening (the registry accepting *more* types than before) is safe and must\\n    not be flagged.\\n    \\\"\\\"\\\"\\n    for key, registry_field in registry_template.items():\\n        if not isinstance(registry_field, Mapping):\\n            continue\\n        registry_types = registry_field.get(\\\"input_types\\\")\\n        if not registry_types:\\n            continue\\n        flow_field = flow_template.get(key)\\n        if not flow_field:\\n            # A field the saved flow predates has no saved edges feeding it, and\\n            # apply_safe_upgrades introduces it with the registry's declared input_types,\\n            # so there is nothing to narrow.\\n            continue\\n        flow_types = flow_field.get(\\\"input_types\\\") or []\\n        # Every type the saved flow relied on must still be accepted by the registry.\\n        if not all(t in registry_types for t in flow_types):\\n            return False\\n    return True\\n\\n\\ndef _node_is_in_tool_mode(flow_outputs: list[dict]) -> bool:\\n    \\\"\\\"\\\"Return True when the saved node's outputs are the synthesized toolset output.\\n\\n    Switching a component to tool mode replaces its authored outputs with a single\\n    ``component_as_tool`` entry, so those outputs describe a runtime projection rather than\\n    anything the registry declares.\\n\\n    Requires *exactly* one output. A malformed node carrying the name more than once is not\\n    something tool mode produces, so it keeps going through the authored-output comparison.\\n    \\\"\\\"\\\"\\n    return len(flow_outputs) == 1 and flow_outputs[0].get(\\\"name\\\") == TOOL_OUTPUT_NAME\\n\\n\\ndef _registry_supports_tool_mode(registry_entry: Mapping[str, Any]) -> bool:\\n    \\\"\\\"\\\"Return True when the current component can still be switched to tool mode.\\n\\n    Mirrors the input side of ``Component._handle_tool_mode``, which is what actually creates\\n    the ``component_as_tool`` output: a component supports tool mode when at least one input\\n    declares ``tool_mode``.\\n\\n    Two signals are deliberately not used. The ``tool_mode`` flag on *outputs* marks which\\n    outputs a toolset exposes rather than the component's capability (124 of the 127 bundled\\n    components set it, ``ChatInput`` included). And ``add_tool_output``, the other half of the\\n    runtime rule, is read by neither this checker nor its frontend mirror in\\n    ``check-code-validity.ts``, so components that rely on it alone keep being reported\\n    ``outdated_breaking``; the flag is serialized into the index now, so consuming it here is a\\n    follow-up that has to land on both sides at once. Both omissions err the same way: a node is\\n    only called safe when re-stamping is known to preserve its toolset output.\\n    \\\"\\\"\\\"\\n    template = registry_entry.get(\\\"template\\\") or {}\\n    return any(isinstance(field_data, Mapping) and field_data.get(\\\"tool_mode\\\") for field_data in template.values())\\n\\n\\ndef has_breaking_change(registry_entry: Mapping[str, Any], node_info: Mapping[str, Any]) -> bool:\\n    \\\"\\\"\\\"Return True when re-stamping this node with the registry's code would break it.\\n\\n    Public because the restricted-mode build path reports the same condition: there a saved\\n    node's code is replaced by this server's copy for the same component type, so a node the\\n    checker calls breaking is one whose saved configuration cannot drive the component that\\n    actually runs. See ``describe_restricted_component_mismatch``.\\n    \\\"\\\"\\\"\\n    registry_outputs = registry_entry.get(\\\"outputs\\\") or []\\n    flow_outputs = node_info.get(\\\"outputs\\\") or []\\n    if _node_is_in_tool_mode(flow_outputs):\\n        # A tool-mode node's saved outputs are the toolset projection, so they never match the\\n        # registry's declared outputs and comparing the two always reports a breaking change.\\n        # What matters for such a node is whether the component still supports tool mode. A\\n        # removed or renamed output cannot disconnect its edges, because its only output is\\n        # the toolset.\\n        if not _registry_supports_tool_mode(registry_entry):\\n            return True\\n    elif registry_outputs and not _outputs_are_compatible(registry_outputs, flow_outputs):\\n        return True\\n    registry_template = registry_entry.get(\\\"template\\\") or {}\\n    flow_template = node_info.get(\\\"template\\\") or {}\\n    if registry_template and not _template_keys_compatible(registry_template, flow_template):\\n        return True\\n    return bool(registry_template) and not _input_types_contained(registry_template, flow_template)\\n\\n\\ndef _classify_node(node: dict, registry: dict[str, dict]) -> NodeStatus | None:\\n    data = node.get(\\\"data\\\", {})\\n    node_info = data.get(\\\"node\\\", {})\\n    component_type = data.get(\\\"type\\\", \\\"\\\")\\n    node_id = data.get(\\\"id\\\") or node.get(\\\"id\\\", \\\"unknown\\\")\\n    display_name = node_info.get(\\\"display_name\\\") or component_type\\n\\n    node_template = node_info.get(\\\"template\\\", {})\\n    code_field = node_template.get(\\\"code\\\")\\n    node_code = code_field.get(\\\"value\\\") if isinstance(code_field, dict) else None\\n    if not node_code:\\n        return None\\n\\n    if component_type in COMPONENTS_TO_IGNORE_UPDATE:\\n        return NodeStatus(node_id=node_id, component_type=component_type, display_name=display_name, status=\\\"ok\\\")\\n\\n    registry_entry = registry.get(component_type)\\n    if registry_entry is None:\\n        return NodeStatus(node_id=node_id, component_type=component_type, display_name=display_name, status=\\\"blocked\\\")\\n\\n    registry_template = registry_entry.get(\\\"template\\\", {})\\n    registry_code_field = registry_template.get(\\\"code\\\")\\n    registry_code = registry_code_field.get(\\\"value\\\") if isinstance(registry_code_field, dict) else None\\n\\n    if registry_code is None or node_code == registry_code:\\n        return NodeStatus(node_id=node_id, component_type=component_type, display_name=display_name, status=\\\"ok\\\")\\n\\n    if has_breaking_change(registry_entry, node_info):\\n        return NodeStatus(\\n            node_id=node_id, component_type=component_type, display_name=display_name, status=\\\"outdated_breaking\\\"\\n        )\\n\\n    return NodeStatus(node_id=node_id, component_type=component_type, display_name=display_name, status=\\\"outdated_safe\\\")\\n\\n\\ndef _classify_nodes_recursive(nodes: list[dict], registry: dict[str, dict], statuses: list[NodeStatus]) -> None:\\n    \\\"\\\"\\\"Classify every node, recursing fully into nested grouped-component flows.\\n\\n    Grouped components can nest arbitrarily deep (a group inside a group); each level lives\\n    under ``node.data.node.flow.data.nodes``. Walking only the first level would silently skip\\n    grandchildren, so we recurse all the way down, keeping the checker symmetric with the\\n    applier, which also recurses fully.\\n    \\\"\\\"\\\"\\n    for node in nodes:\\n        status = _classify_node(node, registry)\\n        if status is not None:\\n            statuses.append(status)\\n        nested = node.get(\\\"data\\\", {}).get(\\\"node\\\", {}).get(\\\"flow\\\", {}).get(\\\"data\\\", {}).get(\\\"nodes\\\")\\n        if nested:\\n            _classify_nodes_recursive(nested, registry, statuses)\\n\\n\\ndef check_flow_compatibility(\\n    flow_data: dict,\\n    all_types_dict: Mapping[str, Any],\\n    *,\\n    registry: dict[str, dict] | None = None,\\n) -> CompatibilityReport:\\n    \\\"\\\"\\\"Check all nodes in flow_data against the component registry.\\n\\n    Args:\\n        flow_data: Parsed flow JSON with a ``nodes`` list.\\n        all_types_dict: Component registry (categories -> components).\\n        registry: Optional pre-built lookup from ``build_registry_lookup``. Pass this to avoid\\n            rebuilding the lookup when the caller also runs ``apply_safe_upgrades`` on the same\\n            registry.\\n    \\\"\\\"\\\"\\n    if registry is None:\\n        registry = build_registry_lookup(all_types_dict)\\n    statuses: list[NodeStatus] = []\\n    _classify_nodes_recursive(flow_data.get(\\\"nodes\\\", []), registry, statuses)\\n    return CompatibilityReport(nodes=statuses)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/upgrade/cli_gate.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"7dd35c0f59b66e2549f5fef3e6d85a875bde5ddacd1e7752c8ae6432f0b0d188\",\"content\":\"\\\"\\\"\\\"Shared ``--upgrade-flow`` gate for the ``run`` and ``serve`` CLI paths.\\n\\nBoth ``lfx run`` and ``lfx serve`` accept ``--upgrade-flow`` with identical semantics:\\n\\n  - ``check``: refuse to run if any component is outdated or blocked.\\n  - ``safe``:  auto-apply safe upgrades, but abort on breaking or blocked components.\\n\\nThis module is the single source of truth for that behavior so the two entry points can\\nnever diverge. Callers translate :class:`UpgradeFlowError` into their own error channel\\n(``RunError`` for ``run_flow``; ``typer.Exit`` for ``serve_command``).\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom enum import Enum\\nfrom typing import TYPE_CHECKING, Any\\n\\nfrom lfx.upgrade.applier import apply_safe_upgrades\\nfrom lfx.upgrade.checker import build_registry_lookup, check_flow_compatibility\\n\\nif TYPE_CHECKING:\\n    from collections.abc import Mapping\\n\\n\\nclass UpgradeFlowMode(str, Enum):\\n    \\\"\\\"\\\"Accepted values for ``--upgrade-flow``.\\n\\n    Subclasses ``str`` so existing string comparisons and call sites that pass the literal\\n    ``\\\"check\\\"`` / ``\\\"safe\\\"`` continue to work unchanged.\\n    \\\"\\\"\\\"\\n\\n    CHECK = \\\"check\\\"\\n    SAFE = \\\"safe\\\"\\n\\n\\nclass UpgradeFlowError(Exception):\\n    \\\"\\\"\\\"Raised when the ``--upgrade-flow`` gate aborts (incompatible/blocked/breaking/unknown).\\\"\\\"\\\"\\n\\n\\ndef _load_bundled_registry() -> dict[str, Any]:\\n    \\\"\\\"\\\"Load the bundled component index as a flat ``all_types_dict``.\\n\\n    This is the same source ``lfx upgrade`` reads, and the only registry that is reliably\\n    populated when the gate runs: ``component_cache.all_types_dict`` is filled lazily *after*\\n    services start, so at gate time it is empty and would classify every node as ``blocked``.\\n\\n    Raises:\\n        UpgradeFlowError: if the bundled registry is empty or missing. Checking against an\\n            empty registry would silently mark *every* node ``blocked`` \u2014 a broken-install\\n            failure masquerading as a flow problem. Fail loudly instead. ``UpgradeFlowError``\\n            (rather than ``typer.Exit``) keeps the gate's error channel uniform so each caller\\n            translates it into its own (``RunError`` for ``run``; ``typer.Exit`` for ``serve``).\\n    \\\"\\\"\\\"\\n    from lfx.interface.components import _read_component_index\\n\\n    blob = _read_component_index(None)\\n    if not blob or \\\"entries\\\" not in blob:\\n        msg = (\\n            \\\"the bundled component registry is empty or missing, so --upgrade-flow \\\"\\n            \\\"compatibility cannot be checked. Try reinstalling lfx \\\"\\n            \\\"(e.g. `pip install --force-reinstall lfx`).\\\"\\n        )\\n        raise UpgradeFlowError(msg)\\n    all_types: dict[str, Any] = {}\\n    for category, components in blob[\\\"entries\\\"]:\\n        all_types.setdefault(category, {}).update(components)\\n    return all_types\\n\\n\\ndef apply_upgrade_gate(\\n    flow_dict: dict,\\n    all_types_dict: Mapping[str, Any] | None = None,\\n    mode: str = UpgradeFlowMode.CHECK,\\n) -> tuple[dict, int]:\\n    \\\"\\\"\\\"Run the ``--upgrade-flow`` gate against ``flow_dict``.\\n\\n    Returns ``(flow_dict, applied_count)`` where ``flow_dict`` is the upgraded graph in ``safe``\\n    mode (or the input unchanged in ``check`` mode / when nothing was applied), and\\n    ``applied_count`` is the number of safe upgrades written.\\n\\n    Args:\\n        flow_dict: The inner flow graph (``{\\\"nodes\\\": [...], \\\"edges\\\": [...]}``) to check.\\n        all_types_dict: The component registry to check against. When ``None`` (the default the\\n            ``run``/``serve`` call sites use), the bundled component index is loaded \u2014 the same\\n            source ``lfx upgrade`` reads. Tests pass an explicit registry to control classification.\\n        mode: ``\\\"check\\\"`` or ``\\\"safe\\\"`` (accepts the :class:`UpgradeFlowMode` enum too).\\n\\n    Raises:\\n        UpgradeFlowError: if ``check`` finds anything not ``ok``, if ``safe`` hits a breaking\\n            or blocked component, if the bundled registry is unavailable, or if ``mode`` is not\\n            a recognized value.\\n    \\\"\\\"\\\"\\n    # Validate the mode before any registry work so a typo fails fast and cheaply.\\n    if mode not in (UpgradeFlowMode.CHECK, UpgradeFlowMode.SAFE):\\n        msg = f\\\"Unknown --upgrade-flow value '{mode}'. Use 'safe' or 'check'.\\\"\\n        raise UpgradeFlowError(msg)\\n\\n    if all_types_dict is None:\\n        all_types_dict = _load_bundled_registry()\\n\\n    # Build the registry lookup once and reuse it for the check (and the apply, in safe mode).\\n    registry = build_registry_lookup(all_types_dict)\\n    report = check_flow_compatibility(flow_dict, all_types_dict, registry=registry)\\n\\n    if mode == UpgradeFlowMode.CHECK:\\n        if not report.is_clean:\\n            names = \\\", \\\".join(f\\\"{n.display_name} ({n.status})\\\" for n in report.nodes if n.status != \\\"ok\\\")\\n            msg = f\\\"flow has incompatible components (--upgrade-flow=check): {names}\\\"\\n            raise UpgradeFlowError(msg)\\n        return flow_dict, 0\\n\\n    # mode is SAFE.\\n    if report.has_blocked or report.has_breaking:\\n        names = \\\", \\\".join(\\n            f\\\"{n.display_name} ({n.status})\\\" for n in report.nodes if n.status in (\\\"blocked\\\", \\\"outdated_breaking\\\")\\n        )\\n        msg = f\\\"flow has components that cannot be auto-upgraded: {names}\\\"\\n        raise UpgradeFlowError(msg)\\n    if report.has_safe_updates:\\n        return apply_safe_upgrades(flow_dict, all_types_dict, report, return_count=True, registry=registry)\\n    return flow_dict, 0\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/utils/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"5f998f27636e0b11748686da14306ae081aaa591689cf688a247a81521ee5f61\",\"content\":\"\\\"\\\"\\\"Utilities for lfx package.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING\\n\\nif TYPE_CHECKING:\\n    from lfx.utils.flow_requirements import (\\n        find_missing_dependencies,\\n        format_missing_dependencies_error,\\n        format_missing_module_error,\\n        generate_requirements_from_file,\\n        generate_requirements_from_flow,\\n        generate_requirements_txt,\\n    )\\n\\n__all__ = [\\n    \\\"find_missing_dependencies\\\",\\n    \\\"format_missing_dependencies_error\\\",\\n    \\\"format_missing_module_error\\\",\\n    \\\"generate_requirements_from_file\\\",\\n    \\\"generate_requirements_from_flow\\\",\\n    \\\"generate_requirements_txt\\\",\\n]\\n\\n\\ndef __getattr__(name: str):\\n    if name in __all__:\\n        from lfx.utils import flow_requirements\\n\\n        return getattr(flow_requirements, name)\\n    msg = f\\\"module {__name__!r} has no attribute {name!r}\\\"\\n    raise AttributeError(msg)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/utils/async_helpers.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"61597b77182c931ae6014817af8d82ef4c24dfc7295ad4503b5875d09a2b4830\",\"content\":\"import asyncio\\nfrom contextlib import asynccontextmanager\\n\\nif hasattr(asyncio, \\\"timeout\\\"):\\n\\n    @asynccontextmanager\\n    async def timeout_context(timeout_seconds):\\n        with asyncio.timeout(timeout_seconds) as ctx:\\n            yield ctx\\n\\nelse:\\n\\n    @asynccontextmanager\\n    async def timeout_context(timeout_seconds):\\n        try:\\n            yield await asyncio.wait_for(asyncio.Future(), timeout=timeout_seconds)\\n        except asyncio.TimeoutError as e:\\n            msg = f\\\"Operation timed out after {timeout_seconds} seconds\\\"\\n            raise TimeoutError(msg) from e\\n\\n\\ndef run_until_complete(coro):\\n    try:\\n        asyncio.get_running_loop()\\n    except RuntimeError:\\n        # If there's no event loop, create a new one and run the coroutine\\n        return asyncio.run(coro)\\n    # If there's already a running event loop, we can't call run_until_complete on it.\\n    # Instead, run the coroutine in a new thread with a new event loop. Propagate the\\n    # caller's contextvars context so request-scoped state (e.g. lfx serve request\\n    # variables and the no-env-fallback flag) stays visible inside the worker thread;\\n    # a bare ThreadPoolExecutor would otherwise reset every ContextVar to its default.\\n    import concurrent.futures\\n    import contextvars\\n\\n    ctx = contextvars.copy_context()\\n\\n    def run_in_new_loop():\\n        new_loop = asyncio.new_event_loop()\\n        asyncio.set_event_loop(new_loop)\\n        try:\\n            return new_loop.run_until_complete(coro)\\n        finally:\\n            new_loop.close()\\n\\n    with concurrent.futures.ThreadPoolExecutor() as executor:\\n        future = executor.submit(ctx.run, run_in_new_loop)\\n        return future.result()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/utils/component_aliases.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"2e69a3c335d4ce107f2b79ac2dcae662294d29c2d3d9a566e2b8e1112fea66c7\",\"content\":\"from __future__ import annotations\\n\\nimport re\\nfrom collections import defaultdict\\nfrom collections.abc import Iterable, Mapping\\nfrom dataclasses import dataclass\\nfrom types import MappingProxyType\\nfrom typing import Any\\n\\n# Explicit fallback aliases for rare cases that cannot be derived from\\n# component metadata. Most legacy names are inferred from `_type`,\\n# `name`, and `display_name`.\\nLEGACY_TYPE_ALIASES: dict[str, str] = {\\n    \\\"Prompt\\\": \\\"Prompt Template\\\",\\n    \\\"TavilyAISearch\\\": \\\"ext:tavily:TavilySearchComponent@official\\\",\\n    \\\"TavilySearchToolComponent\\\": \\\"ext:tavily:TavilySearchComponent@official\\\",\\n    \\\"parser\\\": \\\"ParserComponent\\\",\\n}\\n\\n# Extension components are keyed ``ext:<bundle>:<ClassName>@<slot>``.  Their\\n# decorated templates carry ``name=None`` and ``_type=\\\"Component\\\"``, so none\\n# of the metadata-derived aliases below yield the legacy class name; the key\\n# itself is the only source.  Flows saved before a provider moved out of the\\n# built-in palette reference the legacy keys (``TavilySearchComponent`` /\\n# ``TavilySearch``) -- without these aliases such nodes stop resolving a\\n# current template, so e.g. the starter-project updater leaves their embedded\\n# code stale and the UI reports them as permanently outdated.  Mirrors\\n# ``getTemplateAliases`` in the frontend's reactflowUtils.ts.\\n_EXT_KEY_RE = re.compile(r\\\"^ext:[^:]+:(?P<class_name>[^@]+)@.+$\\\")\\n\\n\\n@dataclass(frozen=True, slots=True)\\nclass ComponentIdentityIndex:\\n    \\\"\\\"\\\"Resolve component aliases against the current registry without guessing.\\n\\n    Registry keys are the canonical component identities for the running\\n    release. Aliases may point at one or more canonical keys; keeping every\\n    candidate prevents registry iteration order from silently choosing a\\n    component when an alias is ambiguous.\\n    \\\"\\\"\\\"\\n\\n    canonical_keys: frozenset[str]\\n    aliases: Mapping[str, frozenset[str]]\\n\\n    def resolve(self, identity: str) -> frozenset[str]:\\n        \\\"\\\"\\\"Return canonical candidates for ``identity``.\\n\\n        Exact canonical keys always win over aliases contributed by another\\n        component. Unknown strings resolve to themselves so existing exact,\\n        case-sensitive policy behavior is preserved for synthetic/custom\\n        component identities that are not in the registry.\\n        \\\"\\\"\\\"\\n        if identity in self.canonical_keys:\\n            return frozenset({identity})\\n        return self.aliases.get(identity, frozenset({identity}))\\n\\n    def resolve_many(self, identities: Iterable[str]) -> frozenset[str]:\\n        \\\"\\\"\\\"Return the union of canonical candidates for ``identities``.\\\"\\\"\\\"\\n        return frozenset(candidate for identity in identities for candidate in self.resolve(identity))\\n\\n\\ndef _component_alias_tiers(\\n    component_name: str,\\n    component_data: Mapping[str, Any] | None,\\n) -> tuple[list[str], list[str]]:\\n    \\\"\\\"\\\"Split a component's aliases into identity and display tiers.\\n\\n    Identity aliases derive from the component's own canonical name -- the\\n    registry key, explicit legacy mappings, the ext-key class name, and the\\n    ``name`` field.  Display aliases derive from human-facing labels\\n    (``display_name``, the template ``_type``) that can legitimately collide\\n    with another component's identity (e.g. the Composio ``AgentQL`` wrapper's\\n    ``display_name`` vs. the standalone ``AgentQL`` component's class name).\\n\\n    Keeping the two tiers separate lets ``flatten_components_with_aliases``\\n    register every identity alias before any display alias, so a component's\\n    own identity always beats another component's ``display_name`` for a shared\\n    key, regardless of registry iteration order.  (This does not disambiguate\\n    two components that contribute the *same identity* alias -- e.g. an\\n    ``XComponent`` and a bare ``X`` across two bundles -- which remain\\n    first-wins by iteration order; a real registry key, set directly, still\\n    beats any alias.)\\n    \\\"\\\"\\\"\\n    identity: list[str] = [component_name]\\n    identity.extend(old_name for old_name, new_name in LEGACY_TYPE_ALIASES.items() if new_name == component_name)\\n\\n    ext_match = _EXT_KEY_RE.match(component_name)\\n    if ext_match:\\n        bare_class_name = ext_match.group(\\\"class_name\\\")\\n        identity.append(bare_class_name)\\n        if bare_class_name.endswith(\\\"Component\\\"):\\n            identity.append(bare_class_name.removesuffix(\\\"Component\\\"))\\n\\n    display: list[str] = []\\n    if component_data:\\n        name_value = component_data.get(\\\"name\\\")\\n        if isinstance(name_value, str) and name_value:\\n            identity.append(name_value)\\n\\n        display_name_value = component_data.get(\\\"display_name\\\")\\n        if isinstance(display_name_value, str) and display_name_value:\\n            display.append(display_name_value)\\n\\n        template = component_data.get(\\\"template\\\")\\n        if isinstance(template, Mapping):\\n            component_class_name = template.get(\\\"_type\\\")\\n            if (\\n                isinstance(component_class_name, str)\\n                and component_class_name\\n                and component_class_name.endswith(\\\"Component\\\")\\n            ):\\n                display.append(component_class_name.removesuffix(\\\"Component\\\"))\\n\\n    return identity, display\\n\\n\\ndef get_component_type_aliases(\\n    component_name: str,\\n    component_data: Mapping[str, Any] | None,\\n) -> tuple[str, ...]:\\n    \\\"\\\"\\\"Return the known aliases for a component type.\\\"\\\"\\\"\\n    identity, display = _component_alias_tiers(component_name, component_data)\\n    deduped_aliases = dict.fromkeys(alias for alias in (*identity, *display) if alias)\\n    return tuple(deduped_aliases)\\n\\n\\ndef _component_identity_index_alias_tiers(\\n    component_name: str,\\n    component_data: Mapping[str, Any] | None,\\n) -> tuple[list[str], list[str]]:\\n    \\\"\\\"\\\"Return aliases used only by the canonical policy identity index.\\n\\n    Runtime component materialization exposes the Python class name while the\\n    registry may use a component's explicit ``name`` (for example,\\n    ``PromptComponent`` versus ``Prompt Template``). These class identities\\n    are intentionally index-only so the legacy starter-project flattening\\n    behavior remains unchanged.\\n    \\\"\\\"\\\"\\n    identity, display = _component_alias_tiers(component_name, component_data)\\n    if component_data:\\n        metadata = component_data.get(\\\"metadata\\\")\\n        if isinstance(metadata, Mapping):\\n            module_value = metadata.get(\\\"module\\\")\\n            if isinstance(module_value, str) and module_value:\\n                module_class_name = module_value.rsplit(\\\".\\\", maxsplit=1)[-1]\\n                if module_class_name:\\n                    identity.append(module_class_name)\\n                    if module_class_name.endswith(\\\"Component\\\"):\\n                        identity.append(module_class_name.removesuffix(\\\"Component\\\"))\\n\\n        template = component_data.get(\\\"template\\\")\\n        if isinstance(template, Mapping):\\n            template_class_name = template.get(\\\"_type\\\")\\n            if isinstance(template_class_name, str) and template_class_name and template_class_name != \\\"Component\\\":\\n                identity.append(template_class_name)\\n                if template_class_name.endswith(\\\"Component\\\"):\\n                    display.append(template_class_name.removesuffix(\\\"Component\\\"))\\n\\n    return (\\n        list(dict.fromkeys(alias for alias in identity if alias)),\\n        list(dict.fromkeys(alias for alias in display if alias)),\\n    )\\n\\n\\ndef build_component_identity_index(all_types_dict: Mapping[str, Any]) -> ComponentIdentityIndex:\\n    \\\"\\\"\\\"Build a collision-aware identity index from a categorized registry.\\n\\n    Canonical registry keys are collected before aliases so an alias can never\\n    shadow an exact key. Unlike :func:`flatten_components_with_aliases`, this\\n    index retains all canonical candidates for an ambiguous alias instead of\\n    selecting the first component encountered. The legacy flattening helper is\\n    intentionally unchanged because starter-project upgrades still depend on\\n    its value lookup behavior.\\n    \\\"\\\"\\\"\\n    entries: list[tuple[str, Mapping[str, Any] | None]] = []\\n    canonical_keys: set[str] = set()\\n\\n    for category_components in all_types_dict.values():\\n        if not isinstance(category_components, Mapping):\\n            continue\\n        for component_name, component_data in category_components.items():\\n            if not isinstance(component_name, str) or not component_name:\\n                continue\\n            canonical_keys.add(component_name)\\n            entries.append(\\n                (\\n                    component_name,\\n                    component_data if isinstance(component_data, Mapping) else None,\\n                )\\n            )\\n\\n    identity_candidates: defaultdict[str, set[str]] = defaultdict(set)\\n    display_candidates: defaultdict[str, set[str]] = defaultdict(set)\\n    for component_name, component_data in entries:\\n        identity, display = _component_identity_index_alias_tiers(component_name, component_data)\\n        for alias in identity:\\n            if alias and alias not in canonical_keys:\\n                identity_candidates[alias].add(component_name)\\n        for alias in display:\\n            if alias and alias not in canonical_keys:\\n                display_candidates[alias].add(component_name)\\n\\n    # Identity aliases outrank display labels, matching the legacy two-pass\\n    # precedence without its first-wins behavior. Collisions within the\\n    # winning tier retain every candidate.\\n    alias_candidates = {\\n        alias: identity_candidates.get(alias) or display_candidates[alias]\\n        for alias in identity_candidates.keys() | display_candidates.keys()\\n    }\\n\\n    frozen_aliases = MappingProxyType({alias: frozenset(candidates) for alias, candidates in alias_candidates.items()})\\n    return ComponentIdentityIndex(\\n        canonical_keys=frozenset(canonical_keys),\\n        aliases=frozen_aliases,\\n    )\\n\\n\\ndef flatten_components_with_aliases(\\n    all_types_dict: Mapping[str, Any],\\n) -> dict[str, Any]:\\n    \\\"\\\"\\\"Flatten a categorized component dict and append derived aliases.\\n\\n    Aliases are registered in two passes: identity aliases (a component's own\\n    canonical name) for every component first, then display aliases.  A\\n    component's own class name therefore beats another component's\\n    ``display_name`` for a shared key, no matter the registry iteration order\\n    (and a real registry key, set directly below, beats any alias).  This does\\n    NOT disambiguate two components that contribute the *same identity* alias --\\n    that collision remains first-wins by iteration order.\\n    \\\"\\\"\\\"\\n    flattened: dict[str, Any] = {}\\n    aliased_entries: list[tuple[list[str], list[str], Any]] = []\\n\\n    for category_components in all_types_dict.values():\\n        if not isinstance(category_components, Mapping):\\n            continue\\n        for component_name, component_data in category_components.items():\\n            flattened[component_name] = component_data\\n            if isinstance(component_data, Mapping):\\n                identity, display = _component_alias_tiers(component_name, component_data)\\n                aliased_entries.append((identity, display, component_data))\\n\\n    for identity, _display, component_value in aliased_entries:\\n        for alias in identity:\\n            if alias:\\n                flattened.setdefault(alias, component_value)\\n\\n    for _identity, display, component_value in aliased_entries:\\n        for alias in display:\\n            if alias:\\n                flattened.setdefault(alias, component_value)\\n\\n    return flattened\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/utils/component_utils.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"66adbf1ef5c677957a11132e958d2c968fa988acca89744aed008e59e4e796a3\",\"content\":\"from collections.abc import Callable\\nfrom typing import Any\\n\\nfrom lfx.schema.dotdict import dotdict\\n\\nDEFAULT_FIELDS = [\\\"code\\\", \\\"_type\\\"]\\n\\n\\ndef update_fields(build_config: dotdict, fields: dict[str, Any]) -> dotdict:\\n    \\\"\\\"\\\"Update specified fields in build_config with new values.\\\"\\\"\\\"\\n    for key, value in fields.items():\\n        if key in build_config:\\n            build_config[key] = value\\n    return build_config\\n\\n\\ndef add_fields(build_config: dotdict, fields: dict[str, Any]) -> dotdict:\\n    \\\"\\\"\\\"Add new fields to build_config.\\\"\\\"\\\"\\n    build_config.update(fields)\\n    return build_config\\n\\n\\ndef delete_fields(build_config: dotdict, fields: dict[str, Any] | list[str]) -> dotdict:\\n    \\\"\\\"\\\"Delete specified fields from build_config.\\\"\\\"\\\"\\n    if isinstance(fields, dict):\\n        fields = list(fields.keys())\\n\\n    for field in fields:\\n        build_config.pop(field, None)\\n    return build_config\\n\\n\\ndef get_fields(build_config: dotdict, fields: list[str] | None = None) -> dict[str, Any]:\\n    \\\"\\\"\\\"Get fields from build_config.If fields is None, return all fields.\\\"\\\"\\\"\\n    if fields is None:\\n        return dict(build_config)\\n\\n    result = {}\\n    for field in fields:\\n        if field in build_config:\\n            result[field] = build_config[field]\\n    return result\\n\\n\\ndef update_input_types(build_config: dotdict) -> dotdict:\\n    \\\"\\\"\\\"Update input types for all fields in build_config.\\\"\\\"\\\"\\n    for key, value in build_config.items():\\n        if isinstance(value, dict):\\n            if value.get(\\\"input_types\\\") is None:\\n                build_config[key][\\\"input_types\\\"] = []\\n        elif hasattr(value, \\\"input_types\\\") and value.input_types is None:\\n            value.input_types = []\\n    return build_config\\n\\n\\ndef set_field_display(build_config: dotdict, field: str, value: bool | None = None) -> dotdict:  # noqa: FBT001\\n    \\\"\\\"\\\"Set whether a field should be displayed in the UI.\\\"\\\"\\\"\\n    if field in build_config and isinstance(build_config[field], dict) and \\\"show\\\" in build_config[field]:\\n        build_config[field][\\\"show\\\"] = value\\n    return build_config\\n\\n\\ndef set_multiple_field_display(\\n    build_config: dotdict,\\n    *,\\n    fields: dict[str, bool] | None = None,\\n    value: bool | None = None,\\n    field_list: list[str] | None = None,\\n) -> dotdict:\\n    \\\"\\\"\\\"Set display property for multiple fields at once.\\\"\\\"\\\"\\n    if fields is not None:\\n        for field, visibility in fields.items():\\n            build_config = set_field_display(build_config, field, value=visibility)\\n    elif field_list is not None:\\n        for field in field_list:\\n            build_config = set_field_display(build_config, field, value=value)\\n    return build_config\\n\\n\\ndef set_field_advanced(build_config: dotdict, field: str, *, value: bool | None = None) -> dotdict:\\n    \\\"\\\"\\\"Set whether a field is considered 'advanced' in the UI.\\\"\\\"\\\"\\n    if value is None:\\n        value = False\\n    if field in build_config and isinstance(build_config[field], dict):\\n        build_config[field][\\\"advanced\\\"] = value\\n    return build_config\\n\\n\\ndef set_multiple_field_advanced(\\n    build_config: dotdict,\\n    *,\\n    fields: dict[str, bool] | None = None,\\n    value: bool | None = None,\\n    field_list: list[str] | None = None,\\n) -> dotdict:\\n    \\\"\\\"\\\"Set advanced property for multiple fields at once.\\\"\\\"\\\"\\n    if fields is not None:\\n        for field, advanced in fields.items():\\n            build_config = set_field_advanced(build_config, field, value=advanced)\\n    elif field_list is not None:\\n        for field in field_list:\\n            build_config = set_field_advanced(build_config, field, value=value)\\n    return build_config\\n\\n\\ndef merge_build_configs(base_config: dotdict, override_config: dotdict) -> dotdict:\\n    \\\"\\\"\\\"Merge two build configurations, with override_config taking precedence.\\\"\\\"\\\"\\n    result = dotdict(base_config.copy())\\n    for key, value in override_config.items():\\n        if key in result and isinstance(value, dict) and isinstance(result[key], dict):\\n            # Recursively merge nested dictionaries\\n            for sub_key, sub_value in value.items():\\n                result[key][sub_key] = sub_value\\n        else:\\n            result[key] = value\\n    return result\\n\\n\\ndef set_current_fields(\\n    build_config: dotdict,\\n    action_fields: dict[str, list[str]],\\n    *,\\n    selected_action: str | None = None,\\n    default_fields: list[str] = DEFAULT_FIELDS,\\n    func: Callable = set_field_display,\\n    default_value: bool | None = None,\\n) -> dotdict:\\n    \\\"\\\"\\\"Set the current fields for a selected action.\\\"\\\"\\\"\\n    # action_fields = {action1: [field1, field2], action2: [field3, field4]}\\n    # we need to show action of one field and disable the rest\\n    if default_value is None:\\n        default_value = False\\n\\n    def _call_func(build_config: dotdict, field: str, *, value: bool) -> dotdict:\\n        \\\"\\\"\\\"Helper to call the function with appropriate signature.\\\"\\\"\\\"\\n        if func == set_field_advanced:\\n            return func(build_config, field, value=value)\\n        return func(build_config, field, value)\\n\\n    if selected_action in action_fields:\\n        for field in action_fields[selected_action]:\\n            build_config = _call_func(build_config, field, value=not default_value)\\n        for key, value in action_fields.items():\\n            if key != selected_action:\\n                for field in value:\\n                    build_config = _call_func(build_config, field, value=default_value)\\n    if selected_action is None:\\n        for value in action_fields.values():\\n            for field in value:\\n                build_config = _call_func(build_config, field, value=default_value)\\n    if default_fields is not None:\\n        for field in default_fields:\\n            build_config = _call_func(build_config, field, value=not default_value)\\n    return build_config\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/utils/concurrency.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"1f0593b2930ed12df15893cbec0f6281551969c14a1f94bc91c903bb8546c17d\",\"content\":\"import re\\nimport threading\\nfrom contextlib import contextmanager\\nfrom pathlib import Path\\n\\nfrom filelock import FileLock\\nfrom platformdirs import user_cache_dir\\n\\n\\nclass KeyedMemoryLockManager:\\n    \\\"\\\"\\\"A manager for acquiring and releasing memory locks based on a key.\\\"\\\"\\\"\\n\\n    def __init__(self) -> None:\\n        self.locks: dict[str, threading.Lock] = {}\\n        self.global_lock = threading.Lock()\\n\\n    def _get_lock(self, key: str):\\n        with self.global_lock:\\n            if key not in self.locks:\\n                self.locks[key] = threading.Lock()\\n            return self.locks[key]\\n\\n    @contextmanager\\n    def lock(self, key: str):\\n        lock = self._get_lock(key)\\n        lock.acquire()\\n        try:\\n            yield\\n        finally:\\n            lock.release()\\n\\n\\nclass KeyedWorkerLockManager:\\n    \\\"\\\"\\\"A manager for acquiring locks between workers based on a key.\\\"\\\"\\\"\\n\\n    def __init__(self) -> None:\\n        self.locks_dir = Path(user_cache_dir(\\\"langflow\\\", ensure_exists=True)) / \\\"worker_locks\\\"\\n\\n    @staticmethod\\n    def _validate_key(key: str) -> bool:\\n        \\\"\\\"\\\"Validate that the string only contains alphanumeric characters and underscores.\\n\\n        Parameters:\\n        s (str): The string to validate.\\n\\n        Returns:\\n        bool: True if the string is valid, False otherwise.\\n        \\\"\\\"\\\"\\n        pattern = re.compile(r\\\"^\\\\w+$\\\")\\n        return bool(pattern.match(key))\\n\\n    @contextmanager\\n    def lock(self, key: str):\\n        if not self._validate_key(key):\\n            msg = f\\\"Invalid key: {key}\\\"\\n            raise ValueError(msg)\\n\\n        lock = FileLock(self.locks_dir / key)\\n        with lock:\\n            yield\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/utils/connection_string_parser.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"aeb91c0e13bc8307bb8a13e6b97ac463536addc7feba5276063e0991252b2f02\",\"content\":\"\\\"\\\"\\\"Connection string parser utilities for lfx package.\\\"\\\"\\\"\\n\\nfrom urllib.parse import quote\\n\\n\\ndef transform_connection_string(connection_string) -> str:\\n    \\\"\\\"\\\"Transform connection string by encoding the password part.\\\"\\\"\\\"\\n    auth_part, db_url_name = connection_string.rsplit(\\\"@\\\", 1)\\n    protocol_user, password_string = auth_part.rsplit(\\\":\\\", 1)\\n    if password_string.startswith(\\\"//\\\") and \\\"://\\\" not in protocol_user:\\n        # \\\"scheme://user@host\\\" carries no password; the only ':' is the scheme separator.\\n        return connection_string\\n    encoded_password = quote(password_string, safe=\\\"\\\")\\n    return f\\\"{protocol_user}:{encoded_password}@{db_url_name}\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/utils/constants.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"82ec89b2c43e29d281e89585d67303a32b08959331826aac2aba7ebb1c99bd25\",\"content\":\"from typing import Any\\n\\nOPENAI_MODELS = [\\n    \\\"text-davinci-003\\\",\\n    \\\"text-davinci-002\\\",\\n    \\\"text-curie-001\\\",\\n    \\\"text-babbage-001\\\",\\n    \\\"text-ada-001\\\",\\n]\\nCHAT_OPENAI_MODELS = [\\n    \\\"gpt-4o\\\",\\n    \\\"gpt-4o-mini\\\",\\n    \\\"gpt-4-turbo-preview\\\",\\n    \\\"gpt-4-0125-preview\\\",\\n    \\\"gpt-4-1106-preview\\\",\\n    \\\"gpt-4-vision-preview\\\",\\n    \\\"gpt-3.5-turbo-0125\\\",\\n    \\\"gpt-3.5-turbo-1106\\\",\\n]\\n\\nREASONING_OPENAI_MODELS = [\\n    \\\"o1\\\",\\n    \\\"o1-mini\\\",\\n    \\\"o1-pro\\\",\\n    \\\"o3-mini\\\",\\n    \\\"o3\\\",\\n    \\\"o3-pro\\\",\\n    \\\"o4-mini\\\",\\n    \\\"o4-mini-high\\\",\\n]\\n\\nANTHROPIC_MODELS = [\\n    # largest model, ideal for a wide range of more complex tasks.\\n    \\\"claude-v1\\\",\\n    # An enhanced version of claude-v1 with a 100,000 token (roughly 75,000 word) context window.\\n    \\\"claude-v1-100k\\\",\\n    # A smaller model with far lower latency, sampling at roughly 40 words/sec!\\n    \\\"claude-instant-v1\\\",\\n    # Like claude-instant-v1 with a 100,000 token context window but retains its performance.\\n    \\\"claude-instant-v1-100k\\\",\\n    # Specific sub-versions of the above models:\\n    # Vs claude-v1.2: better instruction-following, code, and non-English dialogue and writing.\\n    \\\"claude-v1.3\\\",\\n    # An enhanced version of claude-v1.3 with a 100,000 token (roughly 75,000 word) context window.\\n    \\\"claude-v1.3-100k\\\",\\n    # Vs claude-v1.1: small adv in general helpfulness, instruction following, coding, and other tasks.\\n    \\\"claude-v1.2\\\",\\n    # An earlier version of claude-v1.\\n    \\\"claude-v1.0\\\",\\n    # Latest version of claude-instant-v1. Better than claude-instant-v1.0 at most tasks.\\n    \\\"claude-instant-v1.1\\\",\\n    # Version of claude-instant-v1.1 with a 100K token context window.\\n    \\\"claude-instant-v1.1-100k\\\",\\n    # An earlier version of claude-instant-v1.\\n    \\\"claude-instant-v1.0\\\",\\n]\\n\\nDEFAULT_PYTHON_FUNCTION = \\\"\\\"\\\"\\ndef python_function(text: str) -> str:\\n    \\\\\\\"\\\\\\\"\\\\\\\"This is a default python function that returns the input text\\\\\\\"\\\\\\\"\\\\\\\"\\n    return text\\n\\\"\\\"\\\"\\n\\n\\nPYTHON_BASIC_TYPES = [str, bool, int, float, tuple, list, dict, set]\\nDIRECT_TYPES = [\\n    \\\"str\\\",\\n    \\\"bool\\\",\\n    \\\"dict\\\",\\n    \\\"int\\\",\\n    \\\"float\\\",\\n    \\\"Any\\\",\\n    \\\"prompt\\\",\\n    \\\"mustache\\\",\\n    \\\"code\\\",\\n    \\\"NestedDict\\\",\\n    \\\"table\\\",\\n    \\\"slider\\\",\\n    \\\"tab\\\",\\n    \\\"sortableList\\\",\\n    \\\"actionPicker\\\",\\n    \\\"duration\\\",\\n    \\\"auth\\\",\\n    \\\"connect\\\",\\n    \\\"query\\\",\\n    \\\"tools\\\",\\n    \\\"mcp\\\",\\n    \\\"model\\\",\\n    \\\"data_display\\\",\\n]\\n\\n\\nLOADERS_INFO: list[dict[str, Any]] = [\\n    {\\n        \\\"loader\\\": \\\"AirbyteJSONLoader\\\",\\n        \\\"name\\\": \\\"Airbyte JSON (.jsonl)\\\",\\n        \\\"import\\\": \\\"langchain_community.document_loaders.AirbyteJSONLoader\\\",\\n        \\\"defaultFor\\\": [\\\"jsonl\\\"],\\n        \\\"allowdTypes\\\": [\\\"jsonl\\\"],\\n    },\\n    {\\n        \\\"loader\\\": \\\"JSONLoader\\\",\\n        \\\"name\\\": \\\"JSON (.json)\\\",\\n        \\\"import\\\": \\\"langchain_community.document_loaders.JSONLoader\\\",\\n        \\\"defaultFor\\\": [\\\"json\\\"],\\n        \\\"allowdTypes\\\": [\\\"json\\\"],\\n    },\\n    {\\n        \\\"loader\\\": \\\"BSHTMLLoader\\\",\\n        \\\"name\\\": \\\"BeautifulSoup4 HTML (.html, .htm)\\\",\\n        \\\"import\\\": \\\"langchain_community.document_loaders.BSHTMLLoader\\\",\\n        \\\"allowdTypes\\\": [\\\"html\\\", \\\"htm\\\"],\\n    },\\n    {\\n        \\\"loader\\\": \\\"CSVLoader\\\",\\n        \\\"name\\\": \\\"CSV (.csv)\\\",\\n        \\\"import\\\": \\\"langchain_community.document_loaders.CSVLoader\\\",\\n        \\\"defaultFor\\\": [\\\"csv\\\"],\\n        \\\"allowdTypes\\\": [\\\"csv\\\"],\\n    },\\n    {\\n        \\\"loader\\\": \\\"CoNLLULoader\\\",\\n        \\\"name\\\": \\\"CoNLL-U (.conllu)\\\",\\n        \\\"import\\\": \\\"langchain_community.document_loaders.CoNLLULoader\\\",\\n        \\\"defaultFor\\\": [\\\"conllu\\\"],\\n        \\\"allowdTypes\\\": [\\\"conllu\\\"],\\n    },\\n    {\\n        \\\"loader\\\": \\\"EverNoteLoader\\\",\\n        \\\"name\\\": \\\"EverNote (.enex)\\\",\\n        \\\"import\\\": \\\"langchain_community.document_loaders.EverNoteLoader\\\",\\n        \\\"defaultFor\\\": [\\\"enex\\\"],\\n        \\\"allowdTypes\\\": [\\\"enex\\\"],\\n    },\\n    {\\n        \\\"loader\\\": \\\"FacebookChatLoader\\\",\\n        \\\"name\\\": \\\"Facebook Chat (.json)\\\",\\n        \\\"import\\\": \\\"langchain_community.document_loaders.FacebookChatLoader\\\",\\n        \\\"allowdTypes\\\": [\\\"json\\\"],\\n    },\\n    {\\n        \\\"loader\\\": \\\"OutlookMessageLoader\\\",\\n        \\\"name\\\": \\\"Outlook Message (.msg)\\\",\\n        \\\"import\\\": \\\"langchain_community.document_loaders.OutlookMessageLoader\\\",\\n        \\\"defaultFor\\\": [\\\"msg\\\"],\\n        \\\"allowdTypes\\\": [\\\"msg\\\"],\\n    },\\n    {\\n        \\\"loader\\\": \\\"PyPDFLoader\\\",\\n        \\\"name\\\": \\\"PyPDF (.pdf)\\\",\\n        \\\"import\\\": \\\"langchain_community.document_loaders.PyPDFLoader\\\",\\n        \\\"defaultFor\\\": [\\\"pdf\\\"],\\n        \\\"allowdTypes\\\": [\\\"pdf\\\"],\\n    },\\n    {\\n        \\\"loader\\\": \\\"STRLoader\\\",\\n        \\\"name\\\": \\\"Subtitle (.str)\\\",\\n        \\\"import\\\": \\\"langchain_community.document_loaders.STRLoader\\\",\\n        \\\"defaultFor\\\": [\\\"str\\\"],\\n        \\\"allowdTypes\\\": [\\\"str\\\"],\\n    },\\n    {\\n        \\\"loader\\\": \\\"TextLoader\\\",\\n        \\\"name\\\": \\\"Text (.txt)\\\",\\n        \\\"import\\\": \\\"langchain_community.document_loaders.TextLoader\\\",\\n        \\\"defaultFor\\\": [\\\"txt\\\"],\\n        \\\"allowdTypes\\\": [\\\"txt\\\"],\\n    },\\n    {\\n        \\\"loader\\\": \\\"UnstructuredEmailLoader\\\",\\n        \\\"name\\\": \\\"Unstructured Email (.eml)\\\",\\n        \\\"import\\\": \\\"langchain_community.document_loaders.UnstructuredEmailLoader\\\",\\n        \\\"defaultFor\\\": [\\\"eml\\\"],\\n        \\\"allowdTypes\\\": [\\\"eml\\\"],\\n    },\\n    {\\n        \\\"loader\\\": \\\"UnstructuredHTMLLoader\\\",\\n        \\\"name\\\": \\\"Unstructured HTML (.html, .htm)\\\",\\n        \\\"import\\\": \\\"langchain_community.document_loaders.UnstructuredHTMLLoader\\\",\\n        \\\"defaultFor\\\": [\\\"html\\\", \\\"htm\\\"],\\n        \\\"allowdTypes\\\": [\\\"html\\\", \\\"htm\\\"],\\n    },\\n    {\\n        \\\"loader\\\": \\\"UnstructuredMarkdownLoader\\\",\\n        \\\"name\\\": \\\"Unstructured Markdown (.md)\\\",\\n        \\\"import\\\": \\\"langchain_community.document_loaders.UnstructuredMarkdownLoader\\\",\\n        \\\"defaultFor\\\": [\\\"md\\\", \\\"mdx\\\"],\\n        \\\"allowdTypes\\\": [\\\"md\\\", \\\"mdx\\\"],\\n    },\\n    {\\n        \\\"loader\\\": \\\"UnstructuredPowerPointLoader\\\",\\n        \\\"name\\\": \\\"Unstructured PowerPoint (.pptx)\\\",\\n        \\\"import\\\": \\\"langchain_community.document_loaders.UnstructuredPowerPointLoader\\\",\\n        \\\"defaultFor\\\": [\\\"pptx\\\"],\\n        \\\"allowdTypes\\\": [\\\"pptx\\\"],\\n    },\\n    {\\n        \\\"loader\\\": \\\"UnstructuredWordLoader\\\",\\n        \\\"name\\\": \\\"Unstructured Word (.docx)\\\",\\n        \\\"import\\\": \\\"langchain_community.document_loaders.UnstructuredWordLoader\\\",\\n        \\\"defaultFor\\\": [\\\"docx\\\"],\\n        \\\"allowdTypes\\\": [\\\"docx\\\"],\\n    },\\n]\\n\\n\\nMESSAGE_SENDER_AI = \\\"Machine\\\"\\nMESSAGE_SENDER_USER = \\\"User\\\"\\nMESSAGE_SENDER_NAME_AI = \\\"AI\\\"\\nMESSAGE_SENDER_NAME_USER = \\\"User\\\"\\nEXTENSION_TO_CONTENT_TYPE = {\\n    \\\"json\\\": \\\"application/json\\\",\\n    \\\"txt\\\": \\\"text/plain\\\",\\n    \\\"csv\\\": \\\"text/csv\\\",\\n    \\\"html\\\": \\\"text/html\\\",\\n    \\\"pdf\\\": \\\"application/pdf\\\",\\n    \\\"png\\\": \\\"image/png\\\",\\n    \\\"jpg\\\": \\\"image/jpeg\\\",\\n    \\\"jpeg\\\": \\\"image/jpeg\\\",\\n    \\\"gif\\\": \\\"image/gif\\\",\\n    \\\"svg\\\": \\\"image/svg+xml\\\",\\n    \\\"mp3\\\": \\\"audio/mpeg\\\",\\n    \\\"wav\\\": \\\"audio/wav\\\",\\n    \\\"mp4\\\": \\\"video/mp4\\\",\\n    \\\"webm\\\": \\\"video/webm\\\",\\n    \\\"zip\\\": \\\"application/zip\\\",\\n    \\\"tar\\\": \\\"application/x-tar\\\",\\n    \\\"gz\\\": \\\"application/gzip\\\",\\n    \\\"doc\\\": \\\"application/msword\\\",\\n    \\\"docx\\\": \\\"application/vnd.openxmlformats-officedocument.wordprocessingml.document\\\",\\n    \\\"xls\\\": \\\"application/vnd.ms-excel\\\",\\n    \\\"xlsx\\\": \\\"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet\\\",\\n    \\\"ppt\\\": \\\"application/vnd.ms-powerpoint\\\",\\n    \\\"pptx\\\": \\\"application/vnd.openxmlformats-officedocument.presentationml.presentation\\\",\\n    \\\"xml\\\": \\\"application/xml\\\",\\n    \\\"yaml\\\": \\\"application/x-yaml\\\",\\n    \\\"yml\\\": \\\"application/x-yaml\\\",\\n}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/utils/data_structure.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"c54dc935aff88dc18e55afdcb5f3318889848fa74a4103c4ff366c4c0cb2d93e\",\"content\":\"import json\\nfrom collections import Counter\\nfrom typing import Any\\n\\nfrom lfx.schema.data import Data\\n\\n\\ndef infer_list_type(items: list, max_samples: int = 5) -> str:\\n    \\\"\\\"\\\"Infer the type of a list by sampling its items.\\n\\n    Handles mixed types and provides more detailed type information.\\n    \\\"\\\"\\\"\\n    if not items:\\n        return \\\"list(unknown)\\\"\\n\\n    # Sample items (use all if less than max_samples)\\n    samples = items[:max_samples]\\n    types = [get_type_str(item) for item in samples]\\n\\n    # Count type occurrences\\n    type_counter = Counter(types)\\n\\n    if len(type_counter) == 1:\\n        # Single type\\n        return f\\\"list({types[0]})\\\"\\n    # Mixed types - show all found types\\n    type_str = \\\"|\\\".join(sorted(type_counter.keys()))\\n    return f\\\"list({type_str})\\\"\\n\\n\\ndef get_type_str(value: Any) -> str:\\n    \\\"\\\"\\\"Get a detailed string representation of the type of a value.\\n\\n    Handles special cases and provides more specific type information.\\n    \\\"\\\"\\\"\\n    if value is None:\\n        return \\\"null\\\"\\n    if isinstance(value, bool):\\n        return \\\"bool\\\"\\n    if isinstance(value, int):\\n        return \\\"int\\\"\\n    if isinstance(value, float):\\n        return \\\"float\\\"\\n    if isinstance(value, str):\\n        # Check if string is actually a date/datetime\\n        if any(date_pattern in value.lower() for date_pattern in [\\\"date\\\", \\\"time\\\", \\\"yyyy\\\", \\\"mm/dd\\\", \\\"dd/mm\\\", \\\"yyyy-mm\\\"]):\\n            return \\\"str(possible_date)\\\"\\n        # Check if it's a JSON string\\n        try:\\n            json.loads(value)\\n            return \\\"str(json)\\\"\\n        except (json.JSONDecodeError, TypeError):\\n            pass\\n        else:\\n            return \\\"str\\\"\\n    if isinstance(value, list | tuple | set):\\n        return infer_list_type(list(value))\\n    if isinstance(value, dict):\\n        return \\\"dict\\\"\\n    # Handle custom objects\\n    return type(value).__name__\\n\\n\\ndef analyze_value(\\n    value: Any,\\n    max_depth: int = 10,\\n    current_depth: int = 0,\\n    path: str = \\\"\\\",\\n    *,\\n    size_hints: bool = True,\\n    include_samples: bool = True,\\n) -> str | dict:\\n    \\\"\\\"\\\"Analyze a value and return its structure with additional metadata.\\n\\n    Args:\\n        value: The value to analyze\\n        max_depth: Maximum recursion depth\\n        current_depth: Current recursion depth\\n        path: Current path in the structure\\n        size_hints: Whether to include size information for collections\\n        include_samples: Whether to include sample structure for lists\\n    \\\"\\\"\\\"\\n    if current_depth >= max_depth:\\n        return f\\\"max_depth_reached(depth={max_depth})\\\"\\n\\n    try:\\n        if isinstance(value, list | tuple | set):\\n            length = len(value)\\n            if length == 0:\\n                return \\\"list(unknown)\\\"\\n\\n            type_info = infer_list_type(list(value))\\n            size_info = f\\\"[size={length}]\\\" if size_hints else \\\"\\\"\\n\\n            # For lists of complex objects, include a sample of the structure\\n            if (\\n                include_samples\\n                and length > 0\\n                and isinstance(value, list | tuple)\\n                and isinstance(value[0], dict | list)\\n                and current_depth < max_depth - 1\\n            ):\\n                sample = analyze_value(\\n                    value[0],\\n                    max_depth,\\n                    current_depth + 1,\\n                    f\\\"{path}[0]\\\",\\n                    size_hints=size_hints,\\n                    include_samples=include_samples,\\n                )\\n                return f\\\"{type_info}{size_info}, sample: {json.dumps(sample)}\\\"\\n\\n            return f\\\"{type_info}{size_info}\\\"\\n\\n        if isinstance(value, dict):\\n            result = {}\\n            for k, v in value.items():\\n                new_path = f\\\"{path}.{k}\\\" if path else k\\n                try:\\n                    result[k] = analyze_value(\\n                        v,\\n                        max_depth,\\n                        current_depth + 1,\\n                        new_path,\\n                        size_hints=size_hints,\\n                        include_samples=include_samples,\\n                    )\\n                except Exception as e:  # noqa: BLE001\\n                    result[k] = f\\\"error({e!s})\\\"\\n            return result\\n\\n        return get_type_str(value)\\n\\n    except Exception as e:  # noqa: BLE001\\n        return f\\\"error({e!s})\\\"\\n\\n\\ndef get_data_structure(\\n    data_obj: Data | dict,\\n    max_depth: int = 10,\\n    max_sample_size: int = 3,\\n    *,\\n    size_hints: bool = True,\\n    include_sample_values: bool = False,\\n    include_sample_structure: bool = True,\\n) -> dict:\\n    \\\"\\\"\\\"Convert a Data object or dictionary into a detailed schema representation.\\n\\n    Args:\\n        data_obj: The Data object or dictionary to analyze\\n        max_depth: Maximum depth for nested structures\\n        size_hints: Include size information for collections\\n        include_sample_values: Whether to include sample values in the output\\n        include_sample_structure: Whether to include sample structure for lists\\n        max_sample_size: Maximum number of sample values to include\\n\\n    Returns:\\n        dict: A dictionary containing:\\n            - structure: The structure of the data\\n            - samples: (optional) Sample values from the data\\n\\n    Example:\\n        >>> data = {\\n        ...     \\\"name\\\": \\\"John\\\",\\n        ...     \\\"scores\\\": [1, 2, 3, 4, 5],\\n        ...     \\\"details\\\": {\\n        ...         \\\"age\\\": 30,\\n        ...         \\\"cities\\\": [\\\"NY\\\", \\\"LA\\\", \\\"SF\\\", \\\"CHI\\\"],\\n        ...         \\\"metadata\\\": {\\n        ...             \\\"created\\\": \\\"2023-01-01\\\",\\n        ...             \\\"tags\\\": [\\\"user\\\", \\\"admin\\\", 123]\\n        ...         }\\n        ...     }\\n        ... }\\n        >>> result = get_data_structure(data)\\n        {\\n            \\\"structure\\\": {\\n                \\\"name\\\": \\\"str\\\",\\n                \\\"scores\\\": \\\"list(int)[size=5]\\\",\\n                \\\"details\\\": {\\n                    \\\"age\\\": \\\"int\\\",\\n                    \\\"cities\\\": \\\"list(str)[size=4]\\\",\\n                    \\\"metadata\\\": {\\n                        \\\"created\\\": \\\"str(possible_date)\\\",\\n                        \\\"tags\\\": \\\"list(str|int)[size=3]\\\"\\n                    }\\n                }\\n            }\\n        }\\n    \\\"\\\"\\\"\\n    # Handle both Data objects and dictionaries\\n    data = data_obj.data if isinstance(data_obj, Data) else data_obj\\n\\n    result = {\\n        \\\"structure\\\": analyze_value(\\n            data, max_depth=max_depth, size_hints=size_hints, include_samples=include_sample_structure\\n        )\\n    }\\n\\n    if include_sample_values:\\n        result[\\\"samples\\\"] = get_sample_values(data, max_items=max_sample_size)\\n\\n    return result\\n\\n\\ndef get_sample_values(data: Any, max_items: int = 3) -> Any:\\n    \\\"\\\"\\\"Get sample values from a data structure, handling nested structures.\\\"\\\"\\\"\\n    if isinstance(data, list | tuple | set):\\n        return [get_sample_values(item) for item in list(data)[:max_items]]\\n    if isinstance(data, dict):\\n        return {k: get_sample_values(v, max_items) for k, v in data.items()}\\n    return data\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/utils/env_var_security.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"72780c59607e5a5dd4d72a711ddfe9bd2fee1da372297833381de172b39c1300\",\"content\":\"\\\"\\\"\\\"Guard the global-variable \u2192 environment-variable fallback.\\n\\nWhen a flow field is marked *load from DB* and the named global variable is not found,\\nthe loader can fall back to ``os.getenv(<name the flow author typed>)`` (controlled by\\n``LANGFLOW_FALLBACK_TO_ENV_VAR``, default ``True``). The looked-up name comes straight\\nfrom the flow definition, so in a multi-tenant deployment any authenticated tenant can\\nname a *server* environment variable and have its value injected into their flow output \u2014\\ne.g. set a field's value to ``LANGFLOW_SECRET_KEY`` or ``LANGFLOW_DATABASE_URL`` and read\\nback the master encryption key (which decrypts every tenant's stored credentials) or the\\ndatabase URL.\\n\\nThis module blocks that fallback for server-reserved / sensitive variable names. It does\\nNOT touch values that come from the database (a tenant's own stored global variables); it\\nonly constrains which process-environment names the fallback is allowed to read.\\n\\nThis is a denylist, not an allowlist, so it stays compatible with the documented\\nsingle-user behavior (arbitrary env vars usable as global variables) while neutralizing\\nthe catastrophic leaks. Operators who want a strict allowlist should instead disable the\\nfallback entirely with ``LANGFLOW_FALLBACK_TO_ENV_VAR=false`` and provision values as\\ndatabase-backed global variables.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\n# Variable-name prefixes that belong to the application/runtime itself. Langflow and lfx\\n# read all of their own configuration (secret key, database URL, auth secrets, superuser\\n# password, ...) from variables under these prefixes via a settings ``env_prefix``. None of\\n# them are ever meant to be surfaced as a flow value, and several are crown-jewel secrets.\\n_RESERVED_ENV_PREFIXES: tuple[str, ...] = (\\n    \\\"LANGFLOW_\\\",\\n    \\\"LFX_\\\",\\n)\\n\\n# Exact names that carry infrastructure secrets but do not use a reserved prefix. These are\\n# never legitimate flow values (unlike LLM provider API keys, which intentionally remain\\n# resolvable). Covers the database, cache, cloud-IAM, token-signing, OAuth/SSO, mail-relay, and\\n# VCS credentials an operator is most likely to have in a multi-tenant deployment's environment.\\n_RESERVED_ENV_NAMES: frozenset[str] = frozenset(\\n    {\\n        # Application / database\\n        \\\"DATABASE_URL\\\",\\n        \\\"SECRET_KEY\\\",\\n        \\\"POSTGRES_PASSWORD\\\",\\n        \\\"PGVECTOR_CONNECTION_STRING\\\",\\n        \\\"PGPASSWORD\\\",\\n        \\\"MYSQL_PWD\\\",\\n        \\\"MYSQL_ROOT_PASSWORD\\\",\\n        \\\"REDIS_URL\\\",\\n        \\\"REDIS_PASSWORD\\\",\\n        \\\"MONGODB_URI\\\",\\n        \\\"MONGO_URL\\\",\\n        # Cloud IAM\\n        \\\"AWS_SECRET_ACCESS_KEY\\\",\\n        \\\"AWS_ACCESS_KEY_ID\\\",\\n        \\\"AWS_SESSION_TOKEN\\\",\\n        \\\"GOOGLE_APPLICATION_CREDENTIALS\\\",\\n        \\\"GCP_SA_KEY\\\",\\n        \\\"AZURE_CLIENT_SECRET\\\",\\n        # Auth / token-signing secrets (forging these compromises every tenant's session)\\n        \\\"JWT_SECRET\\\",\\n        \\\"JWT_SECRET_KEY\\\",\\n        \\\"SESSION_SECRET\\\",\\n        \\\"SIGNING_KEY\\\",\\n        \\\"ENCRYPTION_KEY\\\",\\n        # OAuth / SSO client secrets (server-side app credentials, never a flow value)\\n        \\\"CLIENT_SECRET\\\",\\n        \\\"OAUTH_CLIENT_SECRET\\\",\\n        \\\"GOOGLE_CLIENT_SECRET\\\",\\n        \\\"GITHUB_CLIENT_SECRET\\\",\\n        \\\"MICROSOFT_CLIENT_SECRET\\\",\\n        # Mail relay credentials\\n        \\\"SMTP_PASSWORD\\\",\\n        \\\"SMTP_PASS\\\",\\n        \\\"EMAIL_HOST_PASSWORD\\\",\\n        # Source control / CI\\n        \\\"GITHUB_TOKEN\\\",\\n        \\\"GH_TOKEN\\\",\\n        \\\"GITLAB_TOKEN\\\",\\n    }\\n)\\n\\n\\ndef is_protected_env_var(name: str) -> bool:\\n    \\\"\\\"\\\"Return True if ``name`` must never be resolved via the env-var fallback.\\n\\n    Matching is case-insensitive so that, e.g., ``langflow_secret_key`` cannot slip\\n    through. An empty or non-string name is treated as protected (fail closed).\\n    \\\"\\\"\\\"\\n    if not name or not isinstance(name, str):\\n        return True\\n\\n    upper = name.upper()\\n    if upper in _RESERVED_ENV_NAMES:\\n        return True\\n    return any(upper.startswith(prefix) for prefix in _RESERVED_ENV_PREFIXES)\\n\\n\\ndef safe_getenv(name: str) -> str | None:\\n    \\\"\\\"\\\"``os.getenv(name)`` that refuses server-reserved / sensitive variable names.\\n\\n    Returns ``None`` for a protected name (as if the variable were unset) so callers can\\n    treat it identically to a missing variable without leaking whether it exists.\\n    \\\"\\\"\\\"\\n    import os\\n\\n    if is_protected_env_var(name):\\n        return None\\n    return os.getenv(name)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/utils/exceptions.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"c4b90f172e4280c8b0f10c997395178148e604d63d31d2785d7cda60055c6af4\",\"content\":\"def format_syntax_error_message(exc: SyntaxError) -> str:\\n    \\\"\\\"\\\"Format a SyntaxError message for returning to the frontend.\\\"\\\"\\\"\\n    if exc.text is None:\\n        return f\\\"Syntax error in code. Error on line {exc.lineno}\\\"\\n    return f\\\"Syntax error in code. Error on line {exc.lineno}: {exc.text.strip()}\\\"\\n\\n\\ndef get_causing_exception(exc: BaseException) -> BaseException:\\n    \\\"\\\"\\\"Get the causing exception from an exception.\\n\\n    Walks the ``__cause__`` chain to the root cause, with one stop condition: a\\n    bundle-shim ``ModuleNotFoundError`` carries a curated \\\"components moved to\\n    ...\\\" message and is itself raised ``from`` the raw ``No module named '<x>'``\\n    import error it wraps. Stop at that curated error so its actionable message\\n    wins instead of unwrapping past it to the bare cause underneath.\\n    \\\"\\\"\\\"\\n    if _is_curated_module_not_found(exc):\\n        return exc\\n    if getattr(exc, \\\"__cause__\\\", None):\\n        return get_causing_exception(exc.__cause__)\\n    return exc\\n\\n\\ndef _is_curated_module_not_found(exc: BaseException) -> bool:\\n    \\\"\\\"\\\"True for a ModuleNotFoundError carrying a curated (non-raw) message.\\n\\n    The interpreter's own import errors read ``No module named '<x>'``; anything\\n    else is a hand-written message (e.g. a bundle shim's \\\"components moved to\\n    ...\\\") that we should surface verbatim rather than rewrite.\\n    \\\"\\\"\\\"\\n    return isinstance(exc, ModuleNotFoundError) and not str(exc).startswith(\\\"No module named\\\")\\n\\n\\ndef module_not_found_hint(exc: BaseException) -> str | None:\\n    \\\"\\\"\\\"Return actionable install guidance for a ModuleNotFoundError, else None.\\n\\n    Components import their provider SDK lazily, so a flow loaded on an\\n    engine-only ``lfx`` (no bundles) fails deep in the vertex build with a bare\\n    ``No module named '...'``. The ``lfx run`` CLI catches this with a\\n    dependency preflight, but the server run path does not, so this maps the\\n    missing module to its package and hands the same guidance to the UI/API.\\n\\n    A graduated bundle shim already raises a curated \\\"components moved to ...\\\"\\n    ModuleNotFoundError (its ``str()`` does not start with \\\"No module named\\\").\\n    That message is more actionable than anything we could regenerate from the\\n    raw cause it wraps, so it is surfaced verbatim. Only plain\\n    ``No module named '<x>'`` errors are rewritten into ``pip install`` guidance.\\n    \\\"\\\"\\\"\\n    if not isinstance(exc, ModuleNotFoundError):\\n        return None\\n    if _is_curated_module_not_found(exc):\\n        return str(exc)\\n    if not exc.name:\\n        return None\\n    from lfx.utils.flow_requirements import format_missing_module_error\\n\\n    return format_missing_module_error(exc.name)\\n\\n\\ndef format_exception_message(exc: Exception) -> str:\\n    \\\"\\\"\\\"Format an exception message for returning to the frontend.\\\"\\\"\\\"\\n    # We need to check if the __cause__ is a SyntaxError\\n    # If it is, we need to return the message of the SyntaxError\\n    causing_exception = get_causing_exception(exc)\\n    if isinstance(causing_exception, SyntaxError):\\n        return format_syntax_error_message(causing_exception)\\n    hint = module_not_found_hint(causing_exception)\\n    if hint is not None:\\n        return hint\\n    return str(exc)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/utils/file_path_security.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"8c406d494d72f500f94f378f3320f898cc06b2f1549cb22947c53706c0749718\",\"content\":\"\\\"\\\"\\\"Containment enforcement for tenant-supplied local file paths.\\n\\nThe built-in file-reading components (File, Directory, JSON/CSV-to-Data) accept a filesystem\\npath from a tenant-controlled input field. Without restriction a tenant can read arbitrary\\nserver files (``/etc/passwd``, the SQLite DB, secrets) or other tenants' uploads.\\n\\nWhen ``LANGFLOW_RESTRICT_LOCAL_FILE_ACCESS`` is enabled, resolved local file paths must stay\\nwithin the authenticated user's or executing flow's storage subdirectory under\\n``settings.config_dir``. The check is a no-op when the setting is disabled (OSS default), so\\nsingle-tenant deployments keep the existing \\\"read any local file by absolute path\\\" behavior.\\n\\nReserved-secret denial: the storage data directory IS ``config_dir``, which also holds the\\nserver-managed secret files as siblings of the per-flow upload subdirectories \u2014 the Fernet\\nmaster key (``secret_key``), the JWT signing keys (``private_key.pem`` / ``public_key.pem``),\\nand the SQLite DB when ``save_db_in_config_dir`` is set. Per-scope containment already rejects\\nthose paths, and exact-file denial is retained as defense in depth because reading ``secret_key``\\nwould disclose every tenant's stored credentials.\\n\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport contextlib\\nfrom pathlib import Path\\nfrom typing import TYPE_CHECKING\\n\\nfrom lfx.logging import logger\\nfrom lfx.services.deps import get_settings_service\\n\\nif TYPE_CHECKING:\\n    from collections.abc import Iterable\\n\\n\\nclass LocalFileAccessError(ValueError):\\n    \\\"\\\"\\\"Raised when a resolved path escapes the allowed storage root under restriction.\\\"\\\"\\\"\\n\\n\\nclass StorageNamespaceError(LocalFileAccessError):\\n    \\\"\\\"\\\"Raised when a storage key addresses a namespace the executing graph does not own.\\n\\n    Subclasses :class:`LocalFileAccessError` so existing handlers that treat a containment\\n    failure as a caller error (e.g. the 400 mapping in the build API) cover this denial too.\\n    \\\"\\\"\\\"\\n\\n\\n# Server-managed secret/key file names that live directly under config_dir (see auth.py:\\n# ``secret_key``, ``private_key.pem``, ``public_key.pem``). Matched only at their exact\\n# config_dir location, never by basename \u2014 a tenant upload happens to be named \\\"secret_key\\\"\\n# inside a flow subdir is a different path and stays readable.\\n_RESERVED_SECRET_FILENAMES = frozenset({\\\"secret_key\\\", \\\"private_key.pem\\\", \\\"public_key.pem\\\"})\\n\\n\\ndef is_local_file_access_restricted() -> bool:\\n    \\\"\\\"\\\"Return True if local file access is restricted to the storage directory.\\\"\\\"\\\"\\n    try:\\n        return bool(get_settings_service().settings.restrict_local_file_access)\\n    except Exception:  # noqa: BLE001 - settings service may be unavailable; fail open to default\\n        logger.warning(\\n            \\\"Could not read restrict_local_file_access setting; treating local file restriction \\\"\\n            \\\"as DISABLED (fail-open to default). Local-file containment is not being enforced.\\\"\\n        )\\n        return False\\n\\n\\ndef _reserved_secret_paths(data_dir: Path) -> set[Path]:\\n    \\\"\\\"\\\"Resolved paths of server-managed secret/key/DB files under the storage dir.\\n\\n    Reading any of these would compromise the deployment (the Fernet master key decrypts every\\n    tenant's credentials; the ``*.pem`` keys allow auth-token forgery; the SQLite DB holds all\\n    rows), so they are denied even though they resolve inside the containment boundary.\\n    \\\"\\\"\\\"\\n    reserved = {(data_dir / name).resolve() for name in _RESERVED_SECRET_FILENAMES}\\n\\n    # Add the SQLite DB file when it lives under config_dir (``save_db_in_config_dir``).\\n    # database_url is assembled as ``sqlite:///<absolute path>`` (see settings/base.py); the\\n    # async ``sqlite+aiosqlite:///`` form is also covered by the ``sqlite`` prefix.\\n    try:\\n        db_url = get_settings_service().settings.database_url or \\\"\\\"\\n    except Exception:  # noqa: BLE001 - settings may be unavailable; nothing to add\\n        db_url = \\\"\\\"\\n    if db_url.startswith(\\\"sqlite\\\") and \\\":///\\\" in db_url:\\n        # Drop any ``?query`` so a custom LANGFLOW_DATABASE_URL still resolves to the file.\\n        db_path_str = db_url.split(\\\":///\\\", 1)[1].split(\\\"?\\\", 1)[0]\\n        if db_path_str:\\n            with contextlib.suppress(OSError):\\n                db_path = Path(db_path_str).resolve()\\n                reserved.add(db_path)\\n                # WAL/SHM/journal sidecars hold un-checkpointed DB pages (the same row data),\\n                # so they must be denied alongside the main DB file.\\n                for suffix in (\\\"-wal\\\", \\\"-shm\\\", \\\"-journal\\\"):\\n                    reserved.add(Path(str(db_path) + suffix))\\n    return reserved\\n\\n\\ndef component_authenticated_user_scope(component: object) -> str | None:\\n    \\\"\\\"\\\"Return the authenticated user's storage scope without requiring component properties.\\\"\\\"\\\"\\n    graph = getattr(getattr(component, \\\"_vertex\\\", None), \\\"graph\\\", None)\\n    candidate = getattr(component, \\\"_user_id\\\", None) or getattr(graph, \\\"user_id\\\", None)\\n    if candidate is None:\\n        return None\\n    scope = str(candidate).strip()\\n    return scope or None\\n\\n\\ndef component_file_access_scopes(component: object) -> tuple[str, ...]:\\n    \\\"\\\"\\\"Return authenticated user, execution-flow, and trusted source-flow storage scopes.\\n\\n    Components are instantiated without a graph while metadata is built. Reading ``user_id`` or\\n    ``flow_id`` properties in that state raises, so this helper inspects their backing graph safely.\\n    \\\"\\\"\\\"\\n    graph = getattr(getattr(component, \\\"_vertex\\\", None), \\\"graph\\\", None)\\n    candidates = (\\n        component_authenticated_user_scope(component),\\n        getattr(graph, \\\"flow_id\\\", None),\\n        getattr(graph, \\\"source_flow_id\\\", None),\\n    )\\n    scopes: list[str] = []\\n    for candidate in candidates:\\n        if candidate is not None:\\n            scope = str(candidate).strip()\\n            if scope and scope not in scopes:\\n                scopes.append(scope)\\n    return tuple(scopes)\\n\\n\\ndef enforce_storage_key_scope(path: str, scope_ids: Iterable[object] | None) -> tuple[str, str]:\\n    \\\"\\\"\\\"Split a ``\\\"<namespace>/<file_name>\\\"`` storage key and verify the caller may address it.\\n\\n    Storage keys are the internal addressing scheme for uploaded files: ``<namespace>`` is the\\n    uploading user's id (``/api/v2/files``) or a flow id (legacy per-flow uploads), and it selects\\n    a per-principal directory under ``config_dir`` (local storage) or object prefix (S3). The value\\n    arrives from a tenant-controlled component input field, so an unvalidated namespace lets one\\n    tenant address another tenant's uploads \u2014 the *shape* of the path ends up deciding access.\\n\\n    Unlike :func:`enforce_local_file_access` this check is NOT gated on\\n    ``LANGFLOW_RESTRICT_LOCAL_FILE_ACCESS``. Reading a local *server* file by absolute path is a\\n    documented single-tenant feature that the flag exists to turn off; addressing another\\n    principal's storage namespace is never legitimate, so it is rejected unconditionally. This\\n    mirrors the namespace check already applied to unauthenticated public builds by\\n    ``langflow.api.utils.flow_utils.validate_public_files``.\\n\\n    Args:\\n        path: The caller-supplied storage key.\\n        scope_ids: Storage namespaces the executing graph owns. An empty/None value means there is\\n            no tenant boundary to enforce (standalone ``lfx run``, scripted graphs), and the key is\\n            accepted; served executions always carry at least the caller's user id or the flow id.\\n\\n    Returns:\\n        tuple[str, str]: The validated ``(namespace, file_name)`` pair.\\n\\n    Raises:\\n        StorageNamespaceError: If the key is malformed, the file name carries path separators or\\n            traversal sequences, or the namespace is outside the given scopes.\\n    \\\"\\\"\\\"\\n    namespace, separator, file_name = str(path).partition(\\\"/\\\")\\n    if not separator or not namespace or not file_name:\\n        msg = f\\\"Invalid storage path '{path}'. Expected '<namespace>/<file_name>'.\\\"\\n        raise StorageNamespaceError(msg)\\n\\n    # Stored file names are single path segments (the storage backends reject separators on\\n    # write), so anything else here is an attempt to climb out of the namespace directory \u2014\\n    # e.g. \\\"<own_id>/../<victim_id>/secret.txt\\\" would otherwise pass the scope check below.\\n    if \\\"..\\\" in file_name or any(char in file_name for char in (\\\"/\\\", \\\"\\\\\\\\\\\", \\\"\\\\x00\\\")):\\n        msg = \\\"Invalid storage file name: contains path separators or traversal sequences.\\\"\\n        raise StorageNamespaceError(msg)\\n\\n    if isinstance(scope_ids, (str, bytes)):\\n        scope_ids = (scope_ids,)\\n    scopes = {str(scope).strip().casefold() for scope in scope_ids or ()}\\n    scopes.discard(\\\"\\\")\\n    if not scopes:\\n        return namespace, file_name\\n\\n    if namespace.casefold() not in scopes:\\n        msg = (\\n            \\\"Access to a storage namespace outside the authenticated user's or executing flow's scope is not permitted.\\\"\\n        )\\n        raise StorageNamespaceError(msg)\\n    return namespace, file_name\\n\\n\\ndef validate_storage_key(component: object, path: str) -> tuple[str, str]:\\n    \\\"\\\"\\\"Component-facing wrapper around :func:`enforce_storage_key_scope`.\\n\\n    Resolves the executing graph's storage scopes from the component and applies the same\\n    namespace-ownership contract used at the vertex parameter boundary.\\n    \\\"\\\"\\\"\\n    return enforce_storage_key_scope(path, component_file_access_scopes(component))\\n\\n\\ndef _scope_roots(\\n    data_dir: Path,\\n    scope_ids: Iterable[object] | None,\\n    *,\\n    allow_storage_root: bool = False,\\n) -> tuple[Path, ...]:\\n    \\\"\\\"\\\"Build validated storage roots for the current authenticated user/flow.\\\"\\\"\\\"\\n    if isinstance(scope_ids, (str, bytes)):\\n        scope_ids = (scope_ids,)\\n    roots: list[Path] = []\\n    for raw_scope in scope_ids or ():\\n        scope = str(raw_scope).strip()\\n        if not scope or scope in {\\\".\\\", \\\"..\\\"} or any(char in scope for char in (\\\"/\\\", \\\"\\\\\\\\\\\", \\\"\\\\x00\\\")):\\n            msg = \\\"Invalid local-file access scope.\\\"\\n            raise LocalFileAccessError(msg)\\n        root = (data_dir / scope).resolve()\\n        if not root.is_relative_to(data_dir):\\n            msg = \\\"Invalid local-file access scope.\\\"\\n            raise LocalFileAccessError(msg)\\n        if root not in roots:\\n            roots.append(root)\\n\\n    if allow_storage_root and data_dir not in roots:\\n        roots.append(data_dir)\\n\\n    if not roots:\\n        msg = (\\n            \\\"Local-file access requires an authenticated user or flow scope \\\"\\n            \\\"when LANGFLOW_RESTRICT_LOCAL_FILE_ACCESS=true.\\\"\\n        )\\n        raise LocalFileAccessError(msg)\\n    return tuple(roots)\\n\\n\\ndef enforce_local_file_access(\\n    resolved_path: str | Path,\\n    *,\\n    scope_ids: Iterable[object] | None = None,\\n    allow_storage_root: bool = False,\\n) -> Path:\\n    \\\"\\\"\\\"Ensure a local path is inside the current user/flow storage scope when restricted.\\n\\n    Symlinks are resolved before the containment check so a symlink inside the storage dir\\n    cannot point outside it.\\n\\n    Args:\\n        resolved_path: A filesystem path. It is re-resolved here (``Path.resolve()``) so that\\n            symlinks are followed before the containment check; the caller need not pre-resolve it.\\n        scope_ids: Authenticated user id and/or executing flow id. At least one valid scope is\\n            required in restricted mode; paths under other storage subdirectories are denied.\\n        allow_storage_root: Widen the containment boundary to ``config_dir`` itself and stop\\n            requiring a scope. This is a defense-in-depth FLOOR, not tenant isolation: it keeps\\n            arbitrary server files (and the reserved secret/key/DB files) out of reach but does\\n            not separate one tenant's uploads from another's. Use it only from shared plumbing\\n            that cannot see a user/flow scope and whose paths were already scope-checked by the\\n            component that produced them; always prefer passing ``scope_ids``.\\n\\n    Returns:\\n        The resolved path as a ``Path`` object when allowed.\\n\\n    Raises:\\n        LocalFileAccessError: If the restriction is enabled and the path escapes the\\n            authenticated user's or executing flow's storage scope.\\n    \\\"\\\"\\\"\\n    path = Path(resolved_path)\\n    if not is_local_file_access_restricted():\\n        return path\\n\\n    data_dir = Path(get_settings_service().settings.config_dir).resolve()\\n    allowed_roots = _scope_roots(data_dir, scope_ids, allow_storage_root=allow_storage_root)\\n    try:\\n        candidate = path.resolve()\\n    except OSError as e:\\n        msg = f\\\"Could not resolve file path '{resolved_path}': {e}\\\"\\n        raise LocalFileAccessError(msg) from e\\n\\n    if not any(candidate == root or candidate.is_relative_to(root) for root in allowed_roots):\\n        msg = (\\n            \\\"Access to local file paths outside the authenticated user's storage scope is disabled \\\"\\n            \\\"(LANGFLOW_RESTRICT_LOCAL_FILE_ACCESS=true). Use an uploaded file instead.\\\"\\n        )\\n        raise LocalFileAccessError(msg)\\n\\n    # The storage dir is config_dir, which also holds server-managed secret/key/DB files as\\n    # siblings of the upload subdirs. Scope containment rejects them only when a scope narrows\\n    # the root below config_dir -- under ``allow_storage_root`` config_dir IS an allowed root,\\n    # so this exact-path denial is the control that keeps secret_key/private_key.pem/the SQLite\\n    # DB out of reach, not a redundant second line. Covered by\\n    # test_read_file_bytes_denies_reserved_secret_key.\\n    if candidate in _reserved_secret_paths(data_dir):\\n        msg = \\\"Access to this server-managed file is not permitted (LANGFLOW_RESTRICT_LOCAL_FILE_ACCESS=true).\\\"\\n        raise LocalFileAccessError(msg)\\n    return candidate\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/utils/helpers.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"d0b1346daae7569fbc639702a03473843cdeb2f5ea8224fb2173fabed4d2c861\",\"content\":\"\\\"\\\"\\\"Helper utility functions for lfx package.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport mimetypes\\nfrom typing import TYPE_CHECKING\\n\\nfrom lfx.utils.constants import EXTENSION_TO_CONTENT_TYPE\\n\\nif TYPE_CHECKING:\\n    from pathlib import Path\\n\\n\\ndef get_mime_type(file_path: str | Path) -> str:\\n    \\\"\\\"\\\"Get the MIME type of a file based on its extension.\\n\\n    Args:\\n        file_path: Path to the file\\n\\n    Returns:\\n        MIME type string (e.g., 'image/jpeg', 'image/png')\\n\\n    Raises:\\n        ValueError: If MIME type cannot be determined\\n    \\\"\\\"\\\"\\n    mime_type, _ = mimetypes.guess_type(str(file_path))\\n    if mime_type is None:\\n        msg = f\\\"Could not determine MIME type for: {file_path}\\\"\\n        raise ValueError(msg)\\n    return mime_type\\n\\n\\ndef build_content_type_from_extension(extension: str):\\n    return EXTENSION_TO_CONTENT_TYPE.get(extension.lower(), \\\"application/octet-stream\\\")\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/utils/image.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"09a306c290822b172efe95a63fb1595f067792bd7eca618a8cdf7606fff2af99\",\"content\":\"\\\"\\\"\\\"Image utility functions for lfx package.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport base64\\nfrom functools import lru_cache\\nfrom pathlib import Path\\n\\nfrom lfx.log import logger\\nfrom lfx.services.deps import get_storage_service\\nfrom lfx.utils.async_helpers import run_until_complete\\nfrom lfx.utils.helpers import get_mime_type\\n\\n\\ndef convert_image_to_base64(image_path: str | Path) -> str:\\n    \\\"\\\"\\\"Convert an image file to a base64 encoded string.\\n\\n    Handles both local files and S3 storage paths.\\n\\n    Args:\\n        image_path: Path to the image file (local or S3 path like \\\"flow_id/filename\\\")\\n\\n    Returns:\\n        Base64 encoded string of the image\\n\\n    Raises:\\n        FileNotFoundError: If the image file doesn't exist\\n    \\\"\\\"\\\"\\n    image_path = Path(image_path)\\n\\n    storage_service = get_storage_service()\\n    if storage_service:\\n        flow_id, file_name = storage_service.parse_file_path(str(image_path))\\n        try:\\n            file_content = run_until_complete(\\n                storage_service.get_file(flow_id=flow_id, file_name=file_name)  # type: ignore[call-arg]\\n            )\\n            return base64.b64encode(file_content).decode(\\\"utf-8\\\")\\n        except Exception as e:\\n            logger.error(f\\\"Error reading image file: {e}\\\")\\n            raise\\n\\n    # Fall back to local file access\\n    if not image_path.exists():\\n        msg = f\\\"Image file not found: {image_path}\\\"\\n        raise FileNotFoundError(msg)\\n\\n    with image_path.open(\\\"rb\\\") as image_file:\\n        return base64.b64encode(image_file.read()).decode(\\\"utf-8\\\")\\n\\n\\ndef create_data_url(image_path: str | Path, mime_type: str | None = None) -> str:\\n    \\\"\\\"\\\"Create a data URL from an image file.\\n\\n    Args:\\n        image_path: Path to the image file (local or S3 path like \\\"flow_id/filename\\\")\\n        mime_type: MIME type of the image. If None, will be auto-detected\\n\\n    Returns:\\n        Data URL string in format: data:mime/type;base64,{base64_data}\\n\\n    Raises:\\n        FileNotFoundError: If the image file doesn't exist\\n    \\\"\\\"\\\"\\n    image_path = Path(image_path)\\n\\n    if mime_type is None:\\n        mime_type = get_mime_type(image_path)\\n\\n    base64_data = convert_image_to_base64(image_path)\\n    return f\\\"data:{mime_type};base64,{base64_data}\\\"\\n\\n\\n@lru_cache(maxsize=50)\\ndef create_image_content_dict(\\n    image_path: str | Path,\\n    mime_type: str | None = None,\\n    model_name: str | None = None,  # noqa: ARG001\\n) -> dict:\\n    \\\"\\\"\\\"Create a content dictionary for multimodal inputs from an image file.\\n\\n    Args:\\n        image_path: Path to the image file (local or S3 path like \\\"flow_id/filename\\\")\\n        mime_type: MIME type of the image. If None, will be auto-detected\\n        model_name: Optional model parameter (kept for backward compatibility, no longer used)\\n\\n    Returns:\\n        Content dictionary with type and image_url fields\\n\\n    Raises:\\n        FileNotFoundError: If the image file doesn't exist\\n    \\\"\\\"\\\"\\n    data_url = create_data_url(image_path, mime_type)\\n\\n    # Standard format for OpenAI, Anthropic, Gemini, and most providers\\n    # Format: {\\\"type\\\": \\\"image_url\\\", \\\"image_url\\\": {\\\"url\\\": \\\"data:...\\\"}}\\n    return {\\\"type\\\": \\\"image_url\\\", \\\"image_url\\\": {\\\"url\\\": data_url}}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/utils/lazy_import.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"18b2837a5541b098c21d2fa1e5f4074cdcbdc859e0a39d13e78eb21d947ba2bb\",\"content\":\"\\\"\\\"\\\"Lazy attribute importing for component packages -- the STABLE public home.\\n\\n:func:`import_mod` powers the ``__getattr__``-based lazy ``__init__.py`` shape\\nused by ``lfx.components`` category packages AND by extracted bundle packages\\n(the ``lfx-bundles`` metapackage's provider folders and the graduated\\n``lfx-<provider>`` distributions).  Because separately-installed bundles import\\nit, this module is part of the BUNDLE_API surface: the symbol's name,\\nsignature, and semantics are contract-stable (see BUNDLE_API.md).\\n\\n``lfx.components._importing`` re-exports :func:`import_mod` for backward\\ncompatibility with in-tree callers and any external code that used the old\\ninternal path; new code -- and all bundle packages -- should import from here.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom importlib import import_module\\n\\n\\ndef import_mod(\\n    attr_name: str,\\n    module_name: str | None,\\n    package: str | None,\\n) -> object:\\n    \\\"\\\"\\\"Import an attribute from a module located in a package.\\n\\n    This utility function is used in custom __getattr__ methods within __init__.py\\n    files to dynamically import attributes.\\n\\n    Args:\\n        attr_name: The name of the attribute to import.\\n        module_name: The name of the module to import from. If None, the attribute\\n            is imported from the package itself.\\n        package: The name of the package where the module is located.\\n    \\\"\\\"\\\"\\n    if module_name == \\\"__module__\\\" or module_name is None:\\n        try:\\n            result = import_module(f\\\".{attr_name}\\\", package=package)\\n        except ModuleNotFoundError:\\n            msg = f\\\"module '{package!r}' has no attribute {attr_name!r}\\\"\\n            raise AttributeError(msg) from None\\n    else:\\n        try:\\n            module = import_module(f\\\".{module_name}\\\", package=package)\\n        except ModuleNotFoundError as e:\\n            # Check if this is a missing dependency or a missing module\\n            if \\\"No module named\\\" in str(e) and package in str(e):\\n                # This is likely a missing module file, not a dependency issue\\n                msg = f\\\"module '{package}.{module_name}' not found\\\"\\n                raise ImportError(msg) from None\\n            # This is likely a missing dependency, let the original error bubble up\\n            raise\\n        result = getattr(module, attr_name)\\n    return result\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/utils/lazy_load.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"503b578bc37b353f6bf85446c6c2d47c3b4653f5fccaab7e450aa0a5cf53a80c\",\"content\":\"class LazyLoadDictBase:\\n    def __init__(self) -> None:\\n        self._all_types_dict = None\\n\\n    @property\\n    def all_types_dict(self):\\n        if self._all_types_dict is None:\\n            self._all_types_dict = self._build_dict()\\n        return self._all_types_dict\\n\\n    def _build_dict(self):\\n        raise NotImplementedError\\n\\n    def get_type_dict(self):\\n        raise NotImplementedError\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/utils/mustache_security.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a766a03c0bd1c57f9608f63bea0896adcf0557195220d9de9be93756386e53b0\",\"content\":\"\\\"\\\"\\\"Security utilities for mustache template processing.\\\"\\\"\\\"\\n\\nimport re\\nfrom typing import Any\\n\\n# Regex pattern for simple variables only - same as frontend\\nSIMPLE_VARIABLE_PATTERN = re.compile(r\\\"\\\\{\\\\{([a-zA-Z_][a-zA-Z0-9_]*)\\\\}\\\\}\\\")\\n\\n# Patterns for complex mustache syntax that we want to block\\nDANGEROUS_PATTERNS = [\\n    re.compile(r\\\"\\\\{\\\\{\\\\{\\\"),  # Triple braces (unescaped HTML in Mustache)\\n    re.compile(r\\\"\\\\{\\\\{#\\\"),  # Conditionals/sections start\\n    re.compile(r\\\"\\\\{\\\\{/\\\"),  # Conditionals/sections end\\n    re.compile(r\\\"\\\\{\\\\{\\\\^\\\"),  # Inverted sections\\n    re.compile(r\\\"\\\\{\\\\{&\\\"),  # Unescaped variables\\n    re.compile(r\\\"\\\\{\\\\{>\\\"),  # Partials\\n    re.compile(r\\\"\\\\{\\\\{!\\\"),  # Comments\\n    re.compile(r\\\"\\\\{\\\\{\\\\.\\\"),  # Current context\\n]\\n\\n\\ndef _find_mustache_patterns(template: str) -> list[str]:\\n    \\\"\\\"\\\"Find all {{...}} patterns in a template using string search (no regex).\\\"\\\"\\\"\\n    patterns = []\\n    start = 0\\n    while True:\\n        idx = template.find(\\\"{{\\\", start)\\n        if idx == -1:\\n            break\\n        end = template.find(\\\"}}\\\", idx + 2)\\n        if end == -1:\\n            break\\n        patterns.append(template[idx : end + 2])\\n        start = end + 2\\n    return patterns\\n\\n\\ndef validate_mustache_template(template: str) -> None:\\n    \\\"\\\"\\\"Validate that a mustache template only contains simple variable substitutions.\\n\\n    Raises ValueError if complex mustache syntax is detected.\\n    \\\"\\\"\\\"\\n    if not template:\\n        return\\n\\n    # Check for dangerous patterns\\n    for pattern in DANGEROUS_PATTERNS:\\n        if pattern.search(template):\\n            msg = (\\n                \\\"Complex mustache syntax is not allowed. Only simple variable substitution \\\"\\n                \\\"like {{variable}} is permitted.\\\"\\n            )\\n            raise ValueError(msg)\\n\\n    # Check that all {{ }} patterns are simple variables\\n    all_mustache_patterns = _find_mustache_patterns(template)\\n    for pattern in all_mustache_patterns:\\n        if not SIMPLE_VARIABLE_PATTERN.match(pattern):\\n            msg = f\\\"Invalid mustache variable: {pattern}. Only simple variable names like {{{{variable}}}} are allowed.\\\"\\n            raise ValueError(msg)\\n\\n\\ndef safe_mustache_render(template: str, variables: dict[str, Any]) -> str:\\n    \\\"\\\"\\\"Safely render a mustache template with only simple variable substitution.\\n\\n    This function performs a single-pass replacement of all {{variable}} patterns.\\n    Variable values that themselves contain mustache-like patterns (e.g., \\\"{{other}}\\\")\\n    will NOT be processed - they are treated as literal strings. This prevents\\n    injection attacks where user-controlled values could introduce new template variables.\\n\\n    Args:\\n        template: The mustache template string\\n        variables: Dictionary of variables to substitute\\n\\n    Returns:\\n        The rendered template\\n\\n    Raises:\\n        ValueError: If template contains complex mustache syntax\\n    \\\"\\\"\\\"\\n    # Validate template first\\n    validate_mustache_template(template)\\n\\n    # Simple replacement - find all simple variables and replace them\\n    def replace_variable(match):\\n        var_name = match.group(1)\\n\\n        # Get the variable value directly (no dot notation support)\\n        value = variables.get(var_name, \\\"\\\")\\n\\n        # Convert to string\\n        return str(value) if value is not None else \\\"\\\"\\n\\n    # Replace all simple variables\\n    return SIMPLE_VARIABLE_PATTERN.sub(replace_variable, template)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/utils/python_repl_security.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"973f5739e01961a222cd2f45e35092027013e14498062a147eade300368ab9cf\",\"content\":\"\\\"\\\"\\\"Best-effort hardening for the Python Interpreter / Python REPL components.\\n\\nThese components execute user-supplied code via ``exec`` (through\\n``langchain_experimental``'s ``PythonREPL``). Historically the globals dict passed to\\n``exec`` contained only the allow-listed modules and never set ``__builtins__``;\\nCPython then auto-injects the *full* builtins module, so ``__import__``, ``open``,\\n``eval``, ``exec`` and the entire import machinery stayed reachable regardless of the\\n\\\"Global Imports\\\" allow-list. The allow-list looked like a sandbox but was silently\\nbypassable (e.g. ``__import__(\\\"subprocess\\\").check_output([\\\"id\\\"])``).\\n\\nThis module restricts that environment:\\n\\n* :func:`safe_builtins` returns a curated ``__builtins__`` mapping that keeps the common\\n  safe builtins (``print``, ``len``, ``range``, container/number types, exceptions, ...)\\n  but removes anything that can import modules, execute/compile code, read the\\n  filesystem, or reach interpreter internals (``__import__``, ``eval``, ``exec``,\\n  ``compile``, ``open``, ``input``, ``globals``/``locals``/``vars``,\\n  ``getattr``/``setattr``/``delattr``, ``breakpoint``, ...).\\n* :func:`validate_code_safety` rejects code that bypasses the allow-list with an inline\\n  ``import`` or reaches the classic builtin-free escape gadgets: dunder attribute access\\n  (``().__class__.__subclasses__()``) and frame/traceback introspection\\n  (``gen.gi_frame.f_back.f_globals``). It also rejects ``str.format`` /\\n  ``str.format_map`` and the lower-level formatter sinks (``string.Formatter`` traversal\\n  primitives, ``operator.attrgetter`` and ``operator.methodcaller``) because replacement\\n  fields / dotted paths / deferred method names are evaluated at runtime and can traverse\\n  attributes that are invisible to the AST, and it rejects literal replacement-field\\n  templates that reach into a dunder regardless of which formatter ultimately consumes\\n  them.\\n\\nThis is defense-in-depth, NOT a guaranteed sandbox \u2014 Python sandboxing is notoriously\\nhard and determined attackers may still find gadgets. The primary control for untrusted\\naccess is authentication: do not expose an instance with ``LANGFLOW_AUTO_LOGIN=true`` on\\nan untrusted network.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport ast\\nimport builtins\\nimport re\\n\\n# Builtins considered safe to expose to interpreter code. Deliberately excludes anything\\n# that can import modules, execute/compile code, touch the filesystem, or reach\\n# interpreter internals. Names absent here resolve to NameError inside the interpreter,\\n# which is what makes the \\\"Global Imports\\\" allow-list the only way to bring in modules.\\n_SAFE_BUILTIN_NAMES = frozenset(\\n    {\\n        \\\"abs\\\",\\n        \\\"aiter\\\",\\n        \\\"anext\\\",\\n        \\\"all\\\",\\n        \\\"any\\\",\\n        \\\"ascii\\\",\\n        \\\"bin\\\",\\n        \\\"bool\\\",\\n        \\\"bytearray\\\",\\n        \\\"bytes\\\",\\n        \\\"callable\\\",\\n        \\\"chr\\\",\\n        \\\"complex\\\",\\n        \\\"dict\\\",\\n        \\\"divmod\\\",\\n        \\\"enumerate\\\",\\n        \\\"filter\\\",\\n        \\\"float\\\",\\n        \\\"format\\\",\\n        \\\"frozenset\\\",\\n        \\\"hasattr\\\",\\n        \\\"hash\\\",\\n        \\\"hex\\\",\\n        \\\"int\\\",\\n        \\\"isinstance\\\",\\n        \\\"issubclass\\\",\\n        \\\"iter\\\",\\n        \\\"len\\\",\\n        \\\"list\\\",\\n        \\\"map\\\",\\n        \\\"max\\\",\\n        \\\"min\\\",\\n        \\\"next\\\",\\n        \\\"oct\\\",\\n        \\\"ord\\\",\\n        \\\"pow\\\",\\n        \\\"print\\\",\\n        \\\"range\\\",\\n        \\\"repr\\\",\\n        \\\"reversed\\\",\\n        \\\"round\\\",\\n        \\\"set\\\",\\n        \\\"slice\\\",\\n        \\\"sorted\\\",\\n        \\\"str\\\",\\n        \\\"sum\\\",\\n        \\\"tuple\\\",\\n        \\\"type\\\",\\n        \\\"zip\\\",\\n        # Exception hierarchy so try/except and explicit raises behave normally.\\n        \\\"ArithmeticError\\\",\\n        \\\"AssertionError\\\",\\n        \\\"AttributeError\\\",\\n        \\\"BaseException\\\",\\n        \\\"Exception\\\",\\n        \\\"FloatingPointError\\\",\\n        \\\"IndexError\\\",\\n        \\\"KeyError\\\",\\n        \\\"KeyboardInterrupt\\\",\\n        \\\"LookupError\\\",\\n        \\\"NameError\\\",\\n        \\\"NotImplementedError\\\",\\n        \\\"OverflowError\\\",\\n        \\\"RecursionError\\\",\\n        \\\"RuntimeError\\\",\\n        \\\"StopIteration\\\",\\n        \\\"TypeError\\\",\\n        \\\"UnicodeDecodeError\\\",\\n        \\\"UnicodeEncodeError\\\",\\n        \\\"ValueError\\\",\\n        \\\"ZeroDivisionError\\\",\\n    }\\n)\\n\\n# Attribute names that expose interpreter internals or sandbox-escape gadgets even\\n# without any dangerous builtin. Dunder attributes (``__class__``, ``__subclasses__``,\\n# ``__globals__``, ``__mro__``, ``__builtins__``, ...) are handled generically; this set\\n# covers the non-dunder frame / coroutine / traceback introspection attributes.\\n_BLOCKED_ATTRIBUTES = frozenset(\\n    {\\n        \\\"gi_frame\\\",\\n        \\\"gi_code\\\",\\n        \\\"cr_frame\\\",\\n        \\\"cr_code\\\",\\n        \\\"ag_frame\\\",\\n        \\\"ag_code\\\",\\n        \\\"f_globals\\\",\\n        \\\"f_locals\\\",\\n        \\\"f_builtins\\\",\\n        \\\"f_back\\\",\\n        \\\"f_code\\\",\\n        \\\"f_trace\\\",\\n        \\\"tb_frame\\\",\\n        \\\"tb_next\\\",\\n        \\\"func_globals\\\",\\n        \\\"func_code\\\",\\n        \\\"__dict__\\\",\\n        \\\"format\\\",\\n        \\\"format_map\\\",\\n        # ``str.format``/``format_map`` are not the only formatter sinks: the same\\n        # dunder-traversal lives in a *string* argument (invisible to the AST attribute\\n        # check) when fed through the lower-level ``string.Formatter`` primitives or\\n        # ``operator.attrgetter``. Block the method names so e.g.\\n        # ``string.Formatter().vformat(\\\"{0.__globals__[os]...}\\\", (f,), {})``,\\n        # ``Formatter().get_field(\\\"0.__globals__...\\\", (f,), {})`` and\\n        # ``operator.attrgetter(\\\"__globals__\\\")(f)`` are rejected as ast.Attribute.\\n        \\\"vformat\\\",\\n        \\\"get_field\\\",\\n        \\\"get_value\\\",\\n        \\\"format_field\\\",\\n        \\\"convert_field\\\",\\n        \\\"attrgetter\\\",\\n        # ``operator.methodcaller`` defers a method *name* (a runtime string) to call\\n        # time, so it reaches the same sinks invisibly to the AST: a runtime-assembled\\n        # template defeats the ``_FORMAT_FIELD_DUNDER_RE`` literal scan, and\\n        # ``methodcaller(\\\"format\\\", f)(tmpl)`` (== ``tmpl.format(f)``) /\\n        # ``methodcaller(\\\"format_map\\\", d)(tmpl)`` carry the dunder chain in ``tmpl``.\\n        # More generally ``methodcaller(\\\"__getattribute__\\\", \\\"__globals__\\\")(f)`` would\\n        # bypass the dunder-attribute check entirely, so block the factory by name.\\n        # (``operator.itemgetter`` is intentionally NOT blocked: it only performs\\n        # subscription, cannot do the attribute traversal needed to bootstrap an escape,\\n        # and is common in legitimate data code.)\\n        \\\"methodcaller\\\",\\n        \\\"mro\\\",  # int.mro() reaches the object hierarchy without a dunder attribute\\n    }\\n)\\n\\n# Matches a dunder reached inside a str.format()/Formatter replacement field, e.g.\\n# \\\"{0.__globals__}\\\" or \\\"{0[__builtins__]}\\\". Such traversals live inside a literal\\n# template string and are invisible to the AST attribute check below, so a literal\\n# dunder-bearing template is rejected regardless of which formatter consumes it.\\n_FORMAT_FIELD_DUNDER_RE = re.compile(r\\\"\\\\{[^{}]*__\\\")\\n\\n\\nclass CodeExecutionDisabledError(ValueError):\\n    \\\"\\\"\\\"Raised when code-execution components are disabled by policy.\\n\\n    Subclasses ``ValueError`` so existing ``except ValueError``/``except Exception``\\n    handlers around the interpreter components surface the message gracefully.\\n    \\\"\\\"\\\"\\n\\n\\ndef ensure_code_execution_enabled() -> None:\\n    \\\"\\\"\\\"Refuse to run Python code when either server code-execution policy disables it.\\n\\n    Registered code-execution components run user- or model-supplied Python. They honor\\n    both ``allow_custom_components`` and ``block_code_interpreter_components`` so a\\n    component cannot bypass either policy through direct or tool-mode execution.\\n\\n    Failure handling is deliberately asymmetric so the gate can never be\\n    silently bypassed:\\n\\n    * ``ImportError`` importing the services layer means there is no settings\\n      stack at all (e.g. a stripped-down lfx embedding). That context is local\\n      and trusted, so execution is allowed.\\n    * Any other exception from ``get_settings_service()`` propagates \u2014 a stack\\n      that exists but errors must not fail open.\\n    * A ``None`` settings service means the stack is registered but failed to\\n      initialise (``get_service`` swallows init errors into ``None``). Fail\\n      closed, matching ``validate_flow_for_current_settings``, rather than\\n      bypass the very control this gate enforces.\\n    \\\"\\\"\\\"\\n    try:\\n        from lfx.services.deps import get_settings_service\\n    except ImportError:\\n        # Services layer absent (e.g. stripped-down lfx embed) -> local/trusted, allow.\\n        return\\n    # Resolver failures, including ImportError from inside the settings stack, must\\n    # propagate rather than masquerade as an absent services layer and fail open.\\n    settings_service = get_settings_service()\\n    if settings_service is None:\\n        # Registered-but-failed settings stack (get_service swallows init errors into\\n        # None). Fail closed rather than bypass the gate (GHSA-8qpj-27x8-pwpq).\\n        msg = (\\n            \\\"Python code execution is disabled because the settings service could not \\\"\\n            \\\"be resolved. Check the server configuration and try again.\\\"\\n        )\\n        raise CodeExecutionDisabledError(msg)\\n    if not getattr(settings_service.settings, \\\"allow_custom_components\\\", True):\\n        msg = (\\n            \\\"Python code execution is disabled because allow_custom_components is False. \\\"\\n            \\\"Set LANGFLOW_ALLOW_CUSTOM_COMPONENTS=true to enable this component.\\\"\\n        )\\n        raise CodeExecutionDisabledError(msg)\\n    if getattr(settings_service.settings, \\\"block_code_interpreter_components\\\", False):\\n        msg = (\\n            \\\"Python code execution is disabled because block_code_interpreter_components is True. \\\"\\n            \\\"Set LANGFLOW_BLOCK_CODE_INTERPRETER_COMPONENTS=false to enable this component.\\\"\\n        )\\n        raise CodeExecutionDisabledError(msg)\\n\\n\\ndef safe_builtins() -> dict:\\n    \\\"\\\"\\\"Return a fresh curated ``__builtins__`` mapping for interpreter globals.\\n\\n    A new dict is returned on each call so callers cannot mutate shared state.\\n    \\\"\\\"\\\"\\n    return {name: getattr(builtins, name) for name in _SAFE_BUILTIN_NAMES if hasattr(builtins, name)}\\n\\n\\ndef _is_blocked_attribute(attr: str) -> bool:\\n    \\\"\\\"\\\"Return True if attribute access to ``attr`` should be rejected.\\\"\\\"\\\"\\n    # Dunder attributes are the classic escape gadgets; the explicit set covers\\n    # frame/traceback introspection attributes that are not dunders.\\n    return attr.startswith(\\\"__\\\") or attr in _BLOCKED_ATTRIBUTES\\n\\n\\ndef validate_code_safety(code: str) -> None:\\n    \\\"\\\"\\\"Reject code that bypasses the import allow-list or reaches escape gadgets.\\n\\n    This complements :func:`safe_builtins`: restricted builtins stop ``__import__`` /\\n    ``open`` / ``eval`` etc., while this AST check stops the builtin-free escapes\\n    (dunder attribute traversal, formatter traversal, and frame introspection) and\\n    inline imports.\\n\\n    Args:\\n        code: The Python source to be executed.\\n\\n    Raises:\\n        ValueError: If the code performs an inline import or accesses a blocked attribute.\\n        SyntaxError: If the code cannot be parsed (surfaced to the caller as-is).\\n    \\\"\\\"\\\"\\n    tree = ast.parse(code)\\n    for node in ast.walk(tree):\\n        if isinstance(node, (ast.Import, ast.ImportFrom)):\\n            msg = \\\"Imports are not allowed in the code; declare modules in the Global Imports field instead.\\\"\\n            raise ValueError(msg)  # noqa: TRY004 -- forbidden construct, not an argument type error\\n        if isinstance(node, ast.Attribute) and _is_blocked_attribute(node.attr):\\n            msg = f\\\"Access to attribute '{node.attr}' is not allowed.\\\"\\n            raise ValueError(msg)\\n        if (\\n            isinstance(node, ast.Constant)\\n            and isinstance(node.value, str)\\n            and _FORMAT_FIELD_DUNDER_RE.search(node.value)\\n        ):\\n            # Blocks \\\"{0.__globals__}\\\" style traversal that the AST attribute check cannot\\n            # see because the attribute chain lives inside a literal string. Catches the\\n            # template regardless of which formatter (str.format, Formatter.vformat, ...)\\n            # ultimately consumes it.\\n            msg = \\\"Access to dunder attributes via format strings is not allowed.\\\"\\n            raise ValueError(msg)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/utils/request_utils.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"03abe6c29afb7f7654c4783a4b3dbe05d514b3203083ce3eecdfc33683c2f3f4\",\"content\":\"from lfx.services.deps import get_settings_service\\n\\nDEFAULT_USER_AGENT = \\\"Langflow\\\"\\n\\n\\ndef get_user_agent():\\n    \\\"\\\"\\\"Get user agent with fallback.\\\"\\\"\\\"\\n    try:\\n        settings_service = get_settings_service()\\n        if (\\n            settings_service\\n            and hasattr(settings_service, \\\"settings\\\")\\n            and hasattr(settings_service.settings, \\\"user_agent\\\")\\n        ):\\n            return settings_service.settings.user_agent\\n    except (AttributeError, TypeError):\\n        pass\\n    return DEFAULT_USER_AGENT\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/utils/sandbox/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"66adf93f88b088454b6e100dd42945de69e92b977c2aab426f590a8983cf4e07\",\"content\":\"\\\"\\\"\\\"Optional hardware-isolated sandbox backend for user-authored code execution.\\n\\nIssue #12029: the Python Interpreter / Python REPL components execute\\nuser-supplied code with ``exec`` inside the server process. The Python-level\\nhardening in :mod:`lfx.utils.python_repl_security` is best-effort defense in\\ndepth, not a security boundary. This package adds an opt-in execution backend\\nthat routes that code into a dedicated microVM per execution, so a malicious\\npayload lands in a throwaway VM (read-only rootfs, no network by default)\\ninstead of the Langflow server process.\\n\\nOperator contract:\\n\\n* ``LANGFLOW_SANDBOX_BACKEND=none`` (default) \u2014 existing in-process behavior,\\n  nothing in this package activates and no backend package need be installed.\\n* Any other value names a registered backend. If that backend cannot be used\\n  (package not installed, no hardware hypervisor, missing credential)\\n  execution FAILS CLOSED with :class:`SandboxUnavailableError`; it never\\n  silently falls back to in-process ``exec``, because the operator explicitly\\n  asked for isolation.\\n\\nLayout:\\n\\n* :mod:`lfx.utils.sandbox.base` \u2014 result and error types, operator settings,\\n  code normalization, and the :class:`SandboxBackend` protocol.\\n* :mod:`lfx.utils.sandbox.registry` \u2014 name to implementation, one source of\\n  truth for which names are accepted.\\n* :mod:`lfx.utils.sandbox.exec_sandbox` \u2014 local QEMU microVMs via the\\n  `exec-sandbox <https://github.com/dualeai/exec-sandbox>`_ package.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport contextlib\\nimport os\\n\\nfrom lfx.utils.sandbox.base import (\\n    Capabilities,\\n    SandboxBackend,\\n    SandboxExecutionError,\\n    SandboxResult,\\n    SandboxUnavailableError,\\n    _compose_sandbox_code,\\n    _sandbox_settings,\\n    build_import_preamble,\\n    sanitize_code,\\n)\\nfrom lfx.utils.sandbox.registry import (\\n    SANDBOX_BACKEND_NONE,\\n    get_sandbox_backend,\\n    is_sandbox_enabled,\\n    known_sandbox_backends,\\n    live_sandbox_backends,\\n    register_sandbox_backend,\\n    reset_registry_after_fork,\\n    resolve_sandbox_backend,\\n)\\nfrom lfx.utils.sandbox.registry import seal_builtins as _seal_builtins\\n\\n# Imported for their registration side effect. An in-tree backend is a plain\\n# import here; an out-of-tree one arrives through the lfx.sandbox_backends\\n# entry point instead and needs no edit to this file.\\nfrom lfx.utils.sandbox import exec_sandbox as _exec_sandbox  # noqa: F401  isort:skip\\n\\n# Everything registered above is in-tree. Freezing the set here is what lets\\n# the registry refuse a plugin that tries to take one of those names.\\n_seal_builtins()\\n\\n__all__ = [\\n    \\\"SANDBOX_BACKEND_NONE\\\",\\n    \\\"Capabilities\\\",\\n    \\\"SandboxBackend\\\",\\n    \\\"SandboxExecutionError\\\",\\n    \\\"SandboxResult\\\",\\n    \\\"SandboxUnavailableError\\\",\\n    \\\"build_import_preamble\\\",\\n    \\\"get_sandbox_backend\\\",\\n    \\\"is_sandbox_enabled\\\",\\n    \\\"known_sandbox_backends\\\",\\n    \\\"register_sandbox_backend\\\",\\n    \\\"run_code_in_sandbox\\\",\\n    \\\"sanitize_code\\\",\\n    \\\"shutdown_sandbox\\\",\\n]\\n\\n\\ndef _reinit_backends_after_fork() -> None:\\n    \\\"\\\"\\\"after_in_child fork hook: give every live backend fresh sync state.\\n\\n    Resolves the instances at call time, so a backend registered later (or a\\n    test-injected one) is covered too. Runs in the child's single-threaded\\n    post-fork window; must never raise, because an exception here would\\n    surface inside unrelated fork calls.\\n    \\\"\\\"\\\"\\n    # First, before anything reads the registry. The registry's own mutex was\\n    # inherited from the parent and may be locked with no owner, so\\n    # live_sandbox_backends() below would block here forever -- and a blocked\\n    # child cannot be rescued by the suppress() around the loop.\\n    reset_registry_after_fork()\\n    for backend in live_sandbox_backends():\\n        with contextlib.suppress(Exception):\\n            backend.reset_after_fork()\\n\\n\\nif hasattr(os, \\\"register_at_fork\\\"):\\n    # POSIX only. Registered once at import for the process lifetime; the hook\\n    # re-resolves the live backends when it fires, so it never pins a stale\\n    # instance.\\n    os.register_at_fork(after_in_child=_reinit_backends_after_fork)\\n\\n\\ndef run_code_in_sandbox(\\n    code: str,\\n    *,\\n    global_imports: str | list[str] = \\\"\\\",\\n    env: dict[str, str] | None = None,\\n) -> SandboxResult:\\n    \\\"\\\"\\\"Execute ``code`` in the configured sandbox backend and return the outcome.\\n\\n    Synchronous by design: the code-execution components are synchronous and\\n    may be invoked from arbitrary threads/event loops, so any loop-affine work\\n    is the backend's problem, not the caller's.\\n\\n    Raises:\\n        SandboxUnavailableError: A sandbox backend is configured but unusable\\n            (fail closed \u2014 never falls back to in-process execution).\\n        SandboxExecutionError: The sandbox infrastructure failed mid-run.\\n        ValueError: ``global_imports`` contains an invalid module name.\\n    \\\"\\\"\\\"\\n    name = get_sandbox_backend()\\n    if name == SANDBOX_BACKEND_NONE:\\n        msg = \\\"run_code_in_sandbox called while no sandbox backend is configured\\\"\\n        raise SandboxExecutionError(msg)\\n    try:\\n        backend = resolve_sandbox_backend(name)\\n    except KeyError as exc:\\n        msg = (\\n            f\\\"Unknown sandbox backend {name!r}. Supported values for \\\"\\n            f\\\"LANGFLOW_SANDBOX_BACKEND: {', '.join(known_sandbox_backends())}.\\\"\\n        )\\n        raise SandboxUnavailableError(msg) from exc\\n\\n    if not code.strip():\\n        # Parity with the in-process interpreter, which returns an empty\\n        # result for blank code; exec-sandbox rejects empty code outright and\\n        # that rejection would otherwise surface as an infrastructure error.\\n        return SandboxResult(stdout=\\\"\\\", stderr=\\\"\\\", exit_code=0)\\n\\n    _assert_backend_honours_policy(backend)\\n    preamble = build_import_preamble(global_imports)\\n    full_code = _compose_sandbox_code(preamble, code)\\n    return backend.run(full_code, env=env)\\n\\n\\ndef _assert_backend_honours_policy(backend: SandboxBackend) -> None:\\n    \\\"\\\"\\\"Refuse when the backend cannot deliver the isolation the operator configured.\\n\\n    The backend DECLARES what it supports. This function DECIDES whether that\\n    is enough. Keeping the decision here rather than in each backend means a\\n    third-party backend cannot grant itself a policy exemption, and every\\n    branch fails closed.\\n    \\\"\\\"\\\"\\n    settings = _sandbox_settings()\\n    capabilities = backend.capabilities()\\n\\n    if capabilities.isolation != \\\"hardware-virtualized\\\":\\n        msg = (\\n            f\\\"Sandbox backend {backend.name!r} reports {capabilities.isolation!r} isolation, \\\"\\n            \\\"not a hardware-virtualized boundary. Sandbox mode disables the in-process Python \\\"\\n            \\\"defenses on the assumption of hardware isolation. Refusing to run the code.\\\"\\n        )\\n        raise SandboxUnavailableError(msg)\\n\\n    if not settings.allow_network and not capabilities.supports_deny_all_egress:\\n        msg = (\\n            f\\\"LANGFLOW_SANDBOX_ALLOW_NETWORK is false but sandbox backend {backend.name!r} \\\"\\n            \\\"cannot block all egress. Refusing to run the code.\\\"\\n        )\\n        raise SandboxUnavailableError(msg)\\n\\n    if settings.allowed_domains and not capabilities.supports_domain_allowlist:\\n        msg = (\\n            f\\\"LANGFLOW_SANDBOX_ALLOWED_DOMAINS is set but sandbox backend {backend.name!r} \\\"\\n            \\\"cannot restrict egress by domain. Refusing to run the code.\\\"\\n        )\\n        raise SandboxUnavailableError(msg)\\n\\n    if capabilities.max_timeout_seconds is not None and settings.timeout_seconds > capabilities.max_timeout_seconds:\\n        msg = (\\n            f\\\"LANGFLOW_SANDBOX_TIMEOUT_SECONDS is {settings.timeout_seconds} but sandbox backend \\\"\\n            f\\\"{backend.name!r} caps one execution at {capabilities.max_timeout_seconds}s. \\\"\\n            \\\"Refusing to run the code.\\\"\\n        )\\n        raise SandboxUnavailableError(msg)\\n\\n\\ndef shutdown_sandbox() -> None:\\n    \\\"\\\"\\\"Best-effort teardown of every live backend and its VMs.\\n\\n    Safe to call when the sandbox was never used. Wired into application\\n    shutdown in addition to each backend's own atexit hook, because a backend\\n    that relies on the host process reaping its guests (exec-sandbox only gets\\n    QEMU parent-death cleanup on QEMU 10.2+) could otherwise leave VMs running\\n    after an abrupt worker exit.\\n    \\\"\\\"\\\"\\n    for backend in live_sandbox_backends():\\n        with contextlib.suppress(Exception):\\n            backend.shutdown()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/utils/sandbox/base.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"3705297d833ff30ff40605c90a82fd16154f4cd0894767697dad74ed1668554d\",\"content\":\"\\\"\\\"\\\"Backend-independent primitives shared by every sandbox backend.\\n\\nNothing here knows which backend is configured. It holds the result and error\\ntypes the callers see, the operator settings a backend must honor, and the\\ncode normalization that has to be identical whichever backend runs the code.\\n\\nSplit out of the former single ``lfx/utils/sandbox.py`` module so a backend\\ncan be added without editing shared code. See :mod:`lfx.utils.sandbox.registry`.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport ast\\nimport re\\nfrom dataclasses import dataclass\\nfrom typing import Protocol, runtime_checkable\\n\\n# Mirrors langchain_experimental's PythonREPL.sanitize_input, which the\\n# in-process path applies before exec: strip a leading markdown fence /\\n# \\\"python\\\" language tag / backticks and trailing backticks-whitespace. The\\n# sandbox path must normalize identically or fenced LLM-generated code that\\n# runs in-process today would become a guest SyntaxError. Replicated here\\n# (two small regexes) so the sandbox path does not depend on\\n# langchain_experimental being installed.\\n_FENCE_PREFIX_RE = re.compile(r\\\"^(\\\\s|`)*(?i:python)?\\\\s*\\\")\\n_FENCE_SUFFIX_RE = re.compile(r\\\"(\\\\s|`)*$\\\")\\n\\n# The Python tokenizer's line-break set: \\\\n, \\\\r\\\\n, \\\\r. Deliberately narrower\\n# than str.splitlines(), which also breaks on U+2028/U+2029 etc. that Python\\n# source treats as ordinary characters inside string literals.\\n_SOURCE_NEWLINE_RE = re.compile(r\\\"\\\\r\\\\n|\\\\r|\\\\n\\\")\\n\\n\\ndef sanitize_code(code: str) -> str:\\n    \\\"\\\"\\\"Strip markdown fences/backticks the way PythonREPL.sanitize_input does.\\\"\\\"\\\"\\n    return _FENCE_SUFFIX_RE.sub(\\\"\\\", _FENCE_PREFIX_RE.sub(\\\"\\\", code))\\n\\n\\nclass SandboxExecutionError(RuntimeError):\\n    \\\"\\\"\\\"Raised when a sandboxed execution fails for infrastructure reasons.\\n\\n    Infrastructure failures (VM boot timeout, guest communication loss) are\\n    distinct from the user code failing \u2014 the latter is reported through\\n    :attr:`SandboxResult.exit_code` / :attr:`SandboxResult.stderr`, not an\\n    exception.\\n    \\\"\\\"\\\"\\n\\n\\nclass SandboxUnavailableError(SandboxExecutionError):\\n    \\\"\\\"\\\"Raised when a sandbox backend is configured but cannot be used.\\n\\n    Deliberately NOT caught by the components' fallback paths: a configured\\n    sandbox that cannot start must block execution (fail closed), not degrade\\n    to in-process ``exec``.\\n    \\\"\\\"\\\"\\n\\n\\n# exec-sandbox reports these outcomes through exit_code instead of raising:\\n# -1 is a wall-clock timeout, 137 is SIGKILL (usually the guest OOM killer).\\n_EXIT_CODE_TIMEOUT = -1\\n_EXIT_CODE_KILLED = 137\\n\\n\\n@dataclass(frozen=True)\\nclass SandboxResult:\\n    \\\"\\\"\\\"Outcome of one sandboxed execution.\\\"\\\"\\\"\\n\\n    stdout: str\\n    stderr: str\\n    exit_code: int\\n    execution_time_ms: int | None = None\\n\\n    @property\\n    def success(self) -> bool:\\n        \\\"\\\"\\\"Return True when the execution exited with code 0.\\\"\\\"\\\"\\n        return self.exit_code == 0\\n\\n    def error_message(self) -> str:\\n        \\\"\\\"\\\"A user-facing message for a failed execution (non-zero exit code).\\\"\\\"\\\"\\n        if self.exit_code == _EXIT_CODE_TIMEOUT:\\n            return \\\"Sandboxed execution timed out (see LANGFLOW_SANDBOX_TIMEOUT_SECONDS).\\\"\\n        if self.exit_code == _EXIT_CODE_KILLED:\\n            return (\\n                \\\"Sandboxed execution was killed (exit code 137), typically because it \\\"\\n                \\\"exceeded the VM memory limit (see LANGFLOW_SANDBOX_MEMORY_MB).\\\"\\n            )\\n        return self.stderr.strip() or f\\\"Sandboxed execution failed with exit code {self.exit_code}\\\"\\n\\n\\n@dataclass(frozen=True)\\nclass _SandboxSettings:\\n    \\\"\\\"\\\"Operator-tunable sandbox settings, with safe defaults for every field.\\\"\\\"\\\"\\n\\n    timeout_seconds: int = 30\\n    memory_mb: int = 192\\n    allow_network: bool = False\\n    allowed_domains: tuple[str, ...] = ()\\n    allow_software_emulation: bool = False\\n\\n\\ndef _sandbox_settings() -> _SandboxSettings:\\n    \\\"\\\"\\\"Read the sandbox tuning settings, defaulting when the settings stack is absent.\\\"\\\"\\\"\\n    defaults = _SandboxSettings()\\n    try:\\n        from lfx.services.deps import get_settings_service\\n\\n        settings_service = get_settings_service()\\n    except ImportError:\\n        return defaults\\n    if settings_service is None:\\n        return defaults\\n    settings = settings_service.settings\\n    return _SandboxSettings(\\n        timeout_seconds=getattr(settings, \\\"sandbox_timeout_seconds\\\", defaults.timeout_seconds),\\n        memory_mb=getattr(settings, \\\"sandbox_memory_mb\\\", defaults.memory_mb),\\n        allow_network=getattr(settings, \\\"sandbox_allow_network\\\", defaults.allow_network),\\n        allowed_domains=tuple(getattr(settings, \\\"sandbox_allowed_domains\\\", ()) or ()),\\n        allow_software_emulation=getattr(\\n            settings, \\\"sandbox_allow_software_emulation\\\", defaults.allow_software_emulation\\n        ),\\n    )\\n\\n\\ndef build_import_preamble(global_imports: str | list[str]) -> str:\\n    \\\"\\\"\\\"Translate the components' ``Global Imports`` field into import statements.\\n\\n    In-process execution imports these modules on the host and injects them\\n    into the exec globals; in sandbox mode the equivalent is a plain import\\n    preamble that runs inside the guest VM. A module missing from the guest\\n    image surfaces as an ImportError in the sandboxed stderr.\\n    \\\"\\\"\\\"\\n    if isinstance(global_imports, str):\\n        modules = [module.strip() for module in global_imports.split(\\\",\\\") if module.strip()]\\n    elif isinstance(global_imports, list):\\n        modules = [str(module).strip() for module in global_imports if str(module).strip()]\\n    else:\\n        msg = \\\"global_imports must be either a string or a list\\\"\\n        raise TypeError(msg)\\n    for module in modules:\\n        # Modules become import statements in generated code, so restrict to\\n        # dotted-identifier names to keep code injection out of the preamble.\\n        if not all(part.isidentifier() for part in module.split(\\\".\\\")):\\n            msg = f\\\"Invalid module name in Global Imports: {module!r}\\\"\\n            raise ValueError(msg)\\n    return \\\"\\\\n\\\".join(f\\\"import {module}\\\" for module in modules)\\n\\n\\ndef _compose_sandbox_code(preamble: str, code: str) -> str:\\n    \\\"\\\"\\\"Join the import preamble and user code without breaking future imports.\\n\\n    ``from __future__ import ...`` must be the first statement after an\\n    optional module docstring, so naively prepending the preamble would turn\\n    valid user code into a SyntaxError. Insert the preamble after any leading\\n    docstring/future-import block instead. If the user code does not parse,\\n    return the naive concatenation \u2014 the guest surfaces the same SyntaxError\\n    the user would get anyway.\\n    \\\"\\\"\\\"\\n    if not preamble:\\n        return code\\n    try:\\n        tree = ast.parse(code)\\n    except SyntaxError:\\n        return f\\\"{preamble}\\\\n{code}\\\"\\n    idx = 0\\n    body = tree.body\\n    if (\\n        body\\n        and isinstance(body[0], ast.Expr)\\n        and isinstance(body[0].value, ast.Constant)\\n        and isinstance(body[0].value.value, str)\\n    ):\\n        idx = 1\\n    while idx < len(body) and isinstance(body[idx], ast.ImportFrom) and body[idx].module == \\\"__future__\\\":\\n        idx += 1\\n    if idx == 0:\\n        return f\\\"{preamble}\\\\n{code}\\\"\\n    if idx >= len(body):\\n        # Only a docstring/future block \u2014 nothing runs after the preamble.\\n        return f\\\"{code}\\\\n{preamble}\\\"\\n    # Split at the exact (line, column) start of the first real statement, not\\n    # at a line boundary: semicolon-joined code like\\n    # ``from __future__ import annotations; print(math.pi)`` would otherwise\\n    # keep user statements on the hoisted line and run them before the\\n    # preamble's imports.\\n    first_tail = body[idx]\\n    # Line starts must use the tokenizer's newline semantics (\\\\n, \\\\r\\\\n, \\\\r) \u2014\\n    # NOT str.splitlines(), which also breaks on U+2028/U+2029 and friends\\n    # that Python source treats as ordinary characters inside strings; a\\n    # docstring containing U+2028 would otherwise shift every subsequent\\n    # offset and drop the preamble inside the docstring.\\n    line_start = 0\\n    for _ in range(first_tail.lineno - 1):\\n        match = _SOURCE_NEWLINE_RE.search(code, line_start)\\n        if match is None:  # pragma: no cover - AST linenos always fit the source\\n            break\\n        line_start = match.end()\\n    # ast col_offset counts UTF-8 BYTES, not characters \u2014 slicing the string\\n    # with it directly would split mid-identifier after any non-ASCII text\\n    # (e.g. an accented docstring). Convert via a byte-slice round-trip; AST\\n    # offsets always fall on character boundaries so the decode is safe.\\n    col_chars = len(code[line_start:].encode(\\\"utf-8\\\")[: first_tail.col_offset].decode(\\\"utf-8\\\"))\\n    offset = line_start + col_chars\\n    head, tail = code[:offset], code[offset:]\\n    # head ends mid-line in the semicolon-joined case; add the newline only\\n    # then (a trailing semicolon before a newline is valid Python).\\n    separator = \\\"\\\" if head.endswith(\\\"\\\\n\\\") else \\\"\\\\n\\\"\\n    return f\\\"{head}{separator}{preamble}\\\\n{tail}\\\"\\n\\n\\n@dataclass(frozen=True)\\nclass Capabilities:\\n    \\\"\\\"\\\"What a backend claims it can enforce.\\n\\n    The backend declares. The dispatcher decides (see\\n    ``_assert_backend_honours_policy``). A backend never gets to approve its\\n    own policy, so a third-party backend cannot grant itself an exemption from\\n    an operator's setting.\\n\\n    Describes what the backend CAN do, not what the current settings ask for.\\n    A backend that offers an explicit \\\"run without hardware isolation\\\" opt-out\\n    still reports ``hardware-virtualized`` here and enforces that opt-out\\n    itself, because the opt-out is the operator's decision rather than a limit\\n    of the backend.\\n\\n    Every field defaults to the value that grants nothing, so a backend that\\n    omits one is refused rather than trusted. ``isolation`` is the field that\\n    matters most: ``_assert_backend_honours_policy`` accepts only\\n    ``\\\"hardware-virtualized\\\"``, and defaulting to it would let a plugin that\\n    never names its isolation clear the strongest gate by saying nothing.\\n    \\\"\\\"\\\"\\n\\n    # Deliberately not \\\"hardware-virtualized\\\". See the note above.\\n    isolation: str = \\\"none\\\"\\n    supports_deny_all_egress: bool = False\\n    supports_domain_allowlist: bool = False\\n    # Longest single execution the backend accepts, or None for no cap.\\n    max_timeout_seconds: int | None = None\\n\\n\\n@runtime_checkable\\nclass SandboxBackend(Protocol):\\n    \\\"\\\"\\\"One way to run user code under isolation.\\n\\n    Implementations are process-wide singletons built lazily by the registry.\\n    ``run`` is called from arbitrary threads, so an implementation owns its own\\n    synchronization.\\n    \\\"\\\"\\\"\\n\\n    name: str\\n\\n    def capabilities(self) -> Capabilities:\\n        \\\"\\\"\\\"Declare what this backend enforces. Must not perform I/O.\\\"\\\"\\\"\\n        ...\\n\\n    def run(self, code: str, *, env: dict[str, str] | None = None) -> SandboxResult:\\n        \\\"\\\"\\\"Run ``code`` to completion and return its outcome.\\n\\n        Raises:\\n            SandboxUnavailableError: The backend is configured but unusable, or\\n                cannot honor the operator's policy. Fail closed.\\n            SandboxExecutionError: The infrastructure failed mid-run.\\n        \\\"\\\"\\\"\\n        ...\\n\\n    def shutdown(self) -> None:\\n        \\\"\\\"\\\"Release process-wide resources. Must be safe to call repeatedly.\\\"\\\"\\\"\\n        ...\\n\\n    def reset_after_fork(self) -> None:\\n        \\\"\\\"\\\"Rebuild synchronization state in a freshly forked child.\\n\\n        Called in the child's single-threaded post-fork window. Any mutex held\\n        by another thread at fork time is inherited locked with no owner, so it\\n        must be replaced rather than reused.\\n        \\\"\\\"\\\"\\n        ...\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/utils/sandbox/exec_sandbox.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"6606872f4ae936abab20520050dbaed14b3194e37e9798abce82f88e68464ef0\",\"content\":\"\\\"\\\"\\\"The ``exec-sandbox`` backend: one local QEMU microVM per execution.\\n\\nEvent-loop ownership: ``exec_sandbox.Scheduler`` is asyncio-based and\\nloop-bound, while component code may run on any thread/loop (and\\n``run_until_complete`` creates throwaway loops when one is already running).\\nA shared scheduler on a throwaway loop would break, so this module owns a\\nsingle long-lived daemon thread running a private event loop; the scheduler\\nlives on that loop for the life of the process and calls are submitted with\\n``asyncio.run_coroutine_threadsafe``. This also amortizes Scheduler startup\\n(asset verification, VM image download) across executions.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport asyncio\\nimport atexit\\nimport contextlib\\nimport os\\nimport subprocess\\nimport sys\\nimport threading\\nfrom pathlib import Path\\n\\nfrom lfx.log.logger import logger\\nfrom lfx.utils.sandbox.base import (\\n    Capabilities,\\n    SandboxExecutionError,\\n    SandboxResult,\\n    SandboxUnavailableError,\\n    _sandbox_settings,\\n)\\nfrom lfx.utils.sandbox.registry import register_sandbox_backend\\n\\nSANDBOX_BACKEND_EXEC_SANDBOX = \\\"exec-sandbox\\\"\\n\\n# Host-side grace added on top of the guest-enforced timeout when waiting for\\n# the loop-thread future. The guest timeout is authoritative (it surfaces as a\\n# graceful exit_code == -1 result); this margin exists only so a wedged\\n# scheduler cannot pin the component thread forever, and it must be generous\\n# enough that legitimate infrastructure work is never misclassified as a wedge:\\n# scheduling delay and result transport in the steady state, plus one-time\\n# Scheduler startup (VM image download ~75MB + warm-pool boot, or slow TCG\\n# boots on hosts without KVM/HVF) on the first execution.\\n_RUN_GRACE_SECONDS = 60\\n_STARTUP_GRACE_SECONDS = 300\\n\\n\\ndef _hardware_acceleration_available() -> bool:\\n    \\\"\\\"\\\"Shallow preflight: whether a hardware hypervisor looks present at all.\\n\\n    Fast fail before any loop/scheduler work when there is obviously no\\n    KVM/HVF. This is deliberately NOT the authoritative gate \u2014 exec-sandbox's\\n    own probe additionally verifies device permissions, KVM ioctls, and the\\n    QEMU binary's accelerator support, so the real decision is made on the\\n    sandbox loop via :func:`_assert_hardware_acceleration` right before the\\n    Scheduler is created.\\n    \\\"\\\"\\\"\\n    if sys.platform.startswith(\\\"linux\\\"):\\n        return Path(\\\"/dev/kvm\\\").exists()\\n    if sys.platform == \\\"darwin\\\":\\n        try:\\n            out = subprocess.run(\\n                [\\\"/usr/sbin/sysctl\\\", \\\"-n\\\", \\\"kern.hv_support\\\"],\\n                capture_output=True,\\n                text=True,\\n                timeout=5,\\n                check=False,\\n            )\\n        except (OSError, subprocess.TimeoutExpired):\\n            return False\\n        return out.stdout.strip() == \\\"1\\\"\\n    # exec-sandbox supports only Linux and macOS.\\n    return False\\n\\n\\ndef _emulation_forced_by_env() -> bool:\\n    \\\"\\\"\\\"True when exec-sandbox is told to force TCG regardless of hardware.\\n\\n    Upstream honors EXEC_SANDBOX_FORCE_EMULATION, which would silently select\\n    software emulation even on a KVM/HVF-capable host \u2014 so it must be treated\\n    exactly like a host without acceleration. The truthy set mirrors pydantic's\\n    bool coercion (upstream parses the env var with a pydantic ``bool`` field),\\n    so values like ``on`` or ``t`` cannot slip past this preflight while still\\n    forcing TCG upstream. This is only the fast preflight; the authoritative\\n    decision consumes upstream's own Settings in\\n    :func:`_assert_hardware_acceleration`.\\n    \\\"\\\"\\\"\\n    return os.environ.get(\\\"EXEC_SANDBOX_FORCE_EMULATION\\\", \\\"\\\").strip().lower() in {\\n        \\\"1\\\",\\n        \\\"true\\\",\\n        \\\"yes\\\",\\n        \\\"on\\\",\\n        \\\"y\\\",\\n        \\\"t\\\",\\n    }\\n\\n\\n_TCG_REFUSAL_MSG = (\\n    \\\"LANGFLOW_SANDBOX_BACKEND=exec-sandbox is configured but QEMU would run under \\\"\\n    \\\"TCG software emulation instead of a hardware hypervisor (KVM on Linux requires \\\"\\n    \\\"a usable /dev/kvm; HVF on macOS), either because acceleration is unavailable \\\"\\n    \\\"or EXEC_SANDBOX_FORCE_EMULATION is set. exec-sandbox does not support TCG as \\\"\\n    \\\"a security boundary \u2014 and sandbox mode disables the in-process Python defenses \\\"\\n    \\\"on the assumption of hardware isolation. Enable hardware virtualization (or \\\"\\n    \\\"pass /dev/kvm through to the container), or set \\\"\\n    \\\"LANGFLOW_SANDBOX_ALLOW_SOFTWARE_EMULATION=true only for trusted/development \\\"\\n    \\\"workloads. Refusing to run the code.\\\"\\n)\\n\\n\\nasync def _assert_hardware_acceleration() -> None:\\n    \\\"\\\"\\\"Authoritative TCG gate, evaluated where exec_sandbox is importable.\\n\\n    Reproduces upstream's own accelerator decision \u2014 ``detect_accel_type`` is\\n    exec-sandbox's documented single source of truth, fed with the\\n    ``force_emulation`` value parsed by exec-sandbox's *own* Settings (so\\n    every pydantic-truthy spelling of EXEC_SANDBOX_FORCE_EMULATION is honored\\n    identically) \u2014 and ALLOWLISTS the two hardware hypervisors: anything that\\n    is not exactly KVM or HVF is refused, so a future pre-1.0 exec-sandbox\\n    that renames TCG, adds another software accelerator, or changes the\\n    return shape fails closed instead of slipping past a TCG-only denylist.\\n\\n    Also FAILS CLOSED if the decision cannot be obtained: the pinned\\n    dependency range guarantees this API today, and guessing about the\\n    isolation boundary when it moves would be exactly the fail-open this gate\\n    exists to prevent.\\n    \\\"\\\"\\\"\\n    try:\\n        from exec_sandbox.settings import Settings as ExecSandboxSettings\\n        from exec_sandbox.system_probes import detect_accel_type\\n        from exec_sandbox.vm_types import AccelType\\n\\n        force_emulation = ExecSandboxSettings().force_emulation\\n        accel = await detect_accel_type(force_emulation=force_emulation)\\n    except Exception as e:\\n        logger.debug(\\\"Could not obtain exec-sandbox accelerator decision\\\", exc_info=True)\\n        msg = (\\n            \\\"LANGFLOW_SANDBOX_BACKEND=exec-sandbox is configured but Langflow could not \\\"\\n            \\\"determine which QEMU accelerator exec-sandbox would select \\\"\\n            f\\\"({type(e).__name__}: {e}). Refusing to run rather than risk TCG software \\\"\\n            \\\"emulation, which is not a supported security boundary. If this exec-sandbox \\\"\\n            \\\"version changed its probe API, this Langflow version does not support it; \\\"\\n            \\\"LANGFLOW_SANDBOX_ALLOW_SOFTWARE_EMULATION=true bypasses this gate for \\\"\\n            \\\"trusted/development workloads only.\\\"\\n        )\\n        raise SandboxUnavailableError(msg) from e\\n    if accel not in (AccelType.KVM, AccelType.HVF):\\n        msg = f\\\"{_TCG_REFUSAL_MSG} (exec-sandbox accelerator decision: {accel!r})\\\"\\n        raise SandboxUnavailableError(msg)\\n\\n\\nclass _ExecSandboxExecutor:\\n    \\\"\\\"\\\"Owns the private event-loop thread and the lazily-created Scheduler.\\\"\\\"\\\"\\n\\n    name = SANDBOX_BACKEND_EXEC_SANDBOX\\n\\n    @staticmethod\\n    def capabilities() -> Capabilities:\\n        \\\"\\\"\\\"exec-sandbox runs a QEMU guest with an in-guest DNS filter.\\n\\n        ``isolation`` reports what the backend provides, not what the current\\n        settings ask for: LANGFLOW_SANDBOX_ALLOW_SOFTWARE_EMULATION is an\\n        operator opt-out that :meth:`run` enforces itself, and reporting it\\n        here would make the dispatcher refuse a run the operator deliberately\\n        allowed.\\n        \\\"\\\"\\\"\\n        return Capabilities(\\n            isolation=\\\"hardware-virtualized\\\",\\n            supports_deny_all_egress=True,\\n            supports_domain_allowlist=True,\\n        )\\n\\n    def __init__(self) -> None:\\n        \\\"\\\"\\\"Initialize empty loop, thread, and scheduler state.\\\"\\\"\\\"\\n        self._loop: asyncio.AbstractEventLoop | None = None\\n        self._thread: threading.Thread | None = None\\n        self._scheduler = None\\n        self._scheduler_lock: asyncio.Lock | None = None\\n        self._lock = threading.Lock()\\n        self._atexit_registered = False\\n        # True only after a first execution has fully completed: _scheduler\\n        # becomes non-None before the first scheduler.run() finishes its\\n        # base-image download / VM boot, so _scheduler alone cannot decide\\n        # whether a caller still needs the startup grace margin.\\n        self._startup_complete = False\\n        # Scheduler lifecycle generation: incremented whenever the scheduler\\n        # is closed or the loop restarts. Lets a run that overlaps a shutdown\\n        # detect that it belongs to a previous scheduler and refrain from\\n        # marking the NEW generation's startup complete.\\n        self._generation = 0\\n\\n    def _ensure_loop_locked(self) -> asyncio.AbstractEventLoop:\\n        \\\"\\\"\\\"Create/return the loop. Caller MUST hold ``self._lock``.\\\"\\\"\\\"\\n        if self._loop is None or self._thread is None or not self._thread.is_alive():\\n            # A dead loop thread (first use, or a fork inheriting this\\n            # module-global) invalidates everything loop-affine: the\\n            # scheduler's VM transports and the asyncio lock lived on the\\n            # old loop, so drop them and start fresh rather than reuse\\n            # state bound to a loop that no longer runs.\\n            self._scheduler = None\\n            self._startup_complete = False\\n            self._generation += 1\\n            # Create the creation lock EAGERLY, together with the loop: it\\n            # must exist by the time run() releases self._lock, so a\\n            # subsequent shutdown() always finds it and queues the close\\n            # behind any submitted-but-not-yet-executed run instead of\\n            # returning early and leaving that run's scheduler open.\\n            # (asyncio.Lock binds to a loop only on first acquire, so\\n            # constructing it off-loop here is safe on Python 3.10+.)\\n            self._scheduler_lock = asyncio.Lock()\\n            loop = asyncio.new_event_loop()\\n            thread = threading.Thread(\\n                target=loop.run_forever,\\n                name=\\\"lfx-sandbox-loop\\\",\\n                daemon=True,\\n            )\\n            thread.start()\\n            self._loop = loop\\n            self._thread = thread\\n        return self._loop\\n\\n    def reset_after_fork(self) -> None:\\n        \\\"\\\"\\\"Rebuild synchronization state in a freshly forked child.\\n\\n        Called from an ``os.register_at_fork(after_in_child=...)`` hook, i.e.\\n        in the guaranteed single-threaded window right after fork() returns\\n        in the child, so replacing state without holding any lock is safe.\\n\\n        The mutex must be REPLACED, not merely relied upon: if another parent\\n        thread held ``self._lock`` at fork time, the child inherits it locked\\n        with no surviving owner and run() would block forever before ever\\n        reaching the dead-loop recovery in _ensure_loop_locked. Loop-affine\\n        state is cleared outright \u2014 threads do not survive fork, so the\\n        inherited loop/scheduler/asyncio-lock are all unusable husks.\\n        \\\"\\\"\\\"\\n        self._lock = threading.Lock()\\n        self._scheduler_lock = None\\n        self._scheduler = None\\n        self._loop = None\\n        self._thread = None\\n        self._startup_complete = False\\n        self._generation += 1\\n\\n    async def _ensure_scheduler(self, *, allow_software_emulation: bool):\\n        \\\"\\\"\\\"Create the exec-sandbox Scheduler on first use, and return it.\\n\\n        Args:\\n            allow_software_emulation: When False, the hardware-acceleration\\n                check runs before any VM resources are created.\\n\\n        Returns:\\n            The process-wide Scheduler instance.\\n        \\\"\\\"\\\"\\n        # Runs ON the sandbox loop, so scheduler state is loop-affine by\\n        # construction. exec_sandbox import errors are translated into the\\n        # fail-closed SandboxUnavailableError contract by run().\\n        #\\n        # The lazy lock creation is atomic (no await between check and assign\\n        # on the single loop thread); the asyncio.Lock then serializes the\\n        # awaited Scheduler startup so two concurrent first calls cannot each\\n        # create a scheduler and leak one VM pool.\\n        #\\n        # The warm pool is deliberately NOT configured: upstream pre-boots N\\n        # VMs for EVERY language (python/javascript/raw) at a fixed default\\n        # memory size, ignoring per-run memory_mb on warm hits, and network-\\n        # enabled runs bypass the pool entirely. Langflow only runs Python\\n        # with an operator-tunable memory limit, so the upstream pool contract\\n        # does not fit; revisit if exec-sandbox grows a per-language,\\n        # memory-keyed pool.\\n        if self._scheduler_lock is None:\\n            self._scheduler_lock = asyncio.Lock()\\n        async with self._scheduler_lock:\\n            if self._scheduler is None:\\n                # The authoritative TCG gate runs here \u2014 on the loop, with\\n                # exec_sandbox importable, before any VM resources exist.\\n                if not allow_software_emulation:\\n                    await _assert_hardware_acceleration()\\n                from exec_sandbox import Scheduler, SchedulerConfig\\n\\n                scheduler = Scheduler(SchedulerConfig())\\n                self._scheduler = await scheduler.__aenter__()\\n                if not self._atexit_registered:\\n                    atexit.register(self.shutdown)\\n                    self._atexit_registered = True\\n        return self._scheduler\\n\\n    async def _close_scheduler(self) -> None:\\n        \\\"\\\"\\\"Exit and CLEAR the scheduler under the creation lock.\\n\\n        Acquiring the creation lock makes this a BARRIER for in-flight\\n        creation: a shutdown that overlaps ``Scheduler.__aenter__`` waits for\\n        it and then closes the freshly created scheduler instead of returning\\n        early and leaving it running. Clearing ``_scheduler`` makes shutdown\\n        restartable (a later execution creates a fresh Scheduler rather than\\n        calling into an exited one).\\n\\n        Readiness/generation are NOT touched here: shutdown() transitions\\n        them synchronously under the thread mutex at submission time, because\\n        by the time this coroutine runs another run may already have captured\\n        its grace classification.\\n        \\\"\\\"\\\"\\n        if self._scheduler_lock is None:\\n            return\\n        async with self._scheduler_lock:\\n            if self._scheduler is None:\\n                return\\n            scheduler, self._scheduler = self._scheduler, None\\n            await scheduler.__aexit__(None, None, None)\\n\\n    def shutdown(self) -> None:\\n        \\\"\\\"\\\"Best-effort Scheduler teardown (atexit + app-shutdown hook).\\n\\n        The loop thread is a daemon, so without this the process would exit\\n        without ever running Scheduler.__aexit__ and guest VMs could outlive\\n        Langflow. atexit runs while daemon threads are still alive, so the\\n        coroutine can complete on the sandbox loop; a short timeout and\\n        blanket suppress keep a wedged VM from hanging process exit. Safe to\\n        call repeatedly and mid-process.\\n\\n        The lifecycle transition happens SYNCHRONOUSLY under ``self._lock``\\n        at submission time \u2014 readiness is cleared and the generation bumped\\n        before the mutex is released, NOT inside the queued close coroutine.\\n        A run accepted after this point therefore always classifies itself as\\n        a cold start (startup grace) even though the close has not executed\\n        yet, and an in-flight run of the closing generation can no longer\\n        re-mark readiness (its completion guard sees the bumped generation).\\n        The close coroutine itself only performs the actual __aexit__ behind\\n        the creation lock: with the eagerly created creation lock, a run\\n        accepted before the shutdown has its coroutine queued ahead of the\\n        close, which then closes whatever that run creates. Only the wait\\n        happens outside the mutex, so a slow close never blocks new\\n        submissions; if it outlives the wait timeout it keeps running on the\\n        loop and still closes as soon as in-flight creation completes.\\n        \\\"\\\"\\\"\\n        with self._lock:\\n            loop = self._loop\\n            if self._scheduler_lock is None or loop is None or loop.is_closed():\\n                return\\n            self._startup_complete = False\\n            self._generation += 1\\n            future = asyncio.run_coroutine_threadsafe(self._close_scheduler(), loop)\\n        with contextlib.suppress(Exception):\\n            future.result(timeout=10)\\n\\n    async def _run_on_loop(\\n        self,\\n        code: str,\\n        *,\\n        timeout_seconds: int,\\n        memory_mb: int,\\n        allow_network: bool,\\n        allowed_domains: tuple[str, ...],\\n        allow_software_emulation: bool,\\n        generation: int,\\n        env: dict[str, str] | None,\\n    ) -> SandboxResult:\\n        \\\"\\\"\\\"Run ``code`` on the sandbox loop and return its outcome.\\n\\n        Must run on the private event loop: the Scheduler and its VM\\n        transports are loop-affine.\\n        \\\"\\\"\\\"\\n        # ``generation`` is the lifecycle epoch captured at ACCEPTANCE time\\n        # (in run(), under the thread mutex). Capturing it here instead would\\n        # be too late: a shutdown that lands between acceptance and this\\n        # coroutine executing bumps the generation first, and a run of the\\n        # closing epoch would then adopt the new epoch and wrongly mark its\\n        # readiness below.\\n        scheduler = await self._ensure_scheduler(allow_software_emulation=allow_software_emulation)\\n        # NOTE: the keyword is env_vars (not env as the README suggests), and\\n        # timeouts do NOT raise \u2014 they surface as exit_code == -1. With\\n        # allow_network=True and no allowed_domains, exec-sandbox's DNS filter\\n        # defaults to package registries only (PyPI/files.pythonhosted.org);\\n        # broader egress requires an explicit domain list.\\n        result = await scheduler.run(\\n            code=code,\\n            language=\\\"python\\\",\\n            timeout_seconds=timeout_seconds,\\n            memory_mb=memory_mb,\\n            env_vars=env or {},\\n            allow_network=allow_network,\\n            allowed_domains=list(allowed_domains) if allowed_domains else None,\\n        )\\n        # Any completed run (even a non-zero guest exit) proves the base image\\n        # is downloaded and a VM booted; only now do later callers stop\\n        # needing the startup grace margin. Left False on exceptions so a\\n        # failed cold start keeps the generous margin for the next attempt,\\n        # and skipped when a shutdown was requested after this run was\\n        # accepted \u2014 its scheduler is (being) closed, so its completion says\\n        # nothing about the current epoch's readiness.\\n        #\\n        # The comparison and the write must be one atomic step under the same\\n        # mutex shutdown() uses for its transition: unlocked, a shutdown can\\n        # land between a successful comparison and the assignment, leaving\\n        # startup_complete=True with no scheduler \u2014 the next cold start would\\n        # then run under the steady-state margin and can time out. Holding\\n        # the thread mutex briefly on the loop thread is deadlock-free: no\\n        # mutex holder ever blocks on the loop while holding it.\\n        with self._lock:\\n            if self._generation == generation:\\n                self._startup_complete = True\\n        return SandboxResult(\\n            stdout=result.stdout,\\n            stderr=result.stderr,\\n            exit_code=result.exit_code,\\n            execution_time_ms=getattr(result, \\\"execution_time_ms\\\", None),\\n        )\\n\\n    def run(self, code: str, *, env: dict[str, str] | None = None) -> SandboxResult:\\n        \\\"\\\"\\\"Run ``code`` to completion in a fresh exec-sandbox VM.\\n\\n        Raises:\\n            SandboxUnavailableError: The 'exec-sandbox' package is missing,\\n                or the operator's policy cannot be honored.\\n            SandboxExecutionError: The infrastructure failed mid-run.\\n        \\\"\\\"\\\"\\n        settings = _sandbox_settings()\\n        try:\\n            import exec_sandbox  # noqa: F401\\n        except ImportError as e:\\n            msg = (\\n                \\\"LANGFLOW_SANDBOX_BACKEND=exec-sandbox is configured but the 'exec-sandbox' \\\"\\n                \\\"package is not installed. Install it with `pip install 'langflow[sandbox]'` \\\"\\n                \\\"(requires Python >= 3.12 and QEMU 8+ on the host), or set \\\"\\n                \\\"LANGFLOW_SANDBOX_BACKEND=none to run code in-process. Refusing to run the \\\"\\n                \\\"code outside the sandbox.\\\"\\n            )\\n            raise SandboxUnavailableError(msg) from e\\n\\n        if not settings.allow_software_emulation and (\\n            _emulation_forced_by_env() or not _hardware_acceleration_available()\\n        ):\\n            # Shallow fast-fail; the authoritative deep gate (exec-sandbox's\\n            # own probe: device permissions, KVM ioctls, QEMU accelerator\\n            # support) runs on the loop in _ensure_scheduler.\\n            raise SandboxUnavailableError(_TCG_REFUSAL_MSG)\\n\\n        # Loop acquisition, readiness capture, and submission form one\\n        # critical section under the executor's thread mutex, totally ordered\\n        # against shutdown() (which submits its close under the same mutex).\\n        # This closes two races: a shutdown can no longer slip between the\\n        # readiness read and the submission (stale steady-state grace for\\n        # what becomes a cold start), and a shutdown can no longer observe\\n        # partially initialized state for an already-accepted run \u2014 the loop\\n        # and its creation lock are created together, so an accepted run\\n        # always leaves something for the close to queue behind.\\n        #\\n        # The readiness flag is read here rather than _scheduler because the\\n        # scheduler becomes non-None before the first run finishes its\\n        # base-image download / VM boot; a second concurrent caller would\\n        # otherwise get the steady-state margin while startup work is still\\n        # in flight.\\n        with self._lock:\\n            loop = self._ensure_loop_locked()\\n            is_first_execution = not self._startup_complete\\n            future = asyncio.run_coroutine_threadsafe(\\n                self._run_on_loop(\\n                    code,\\n                    generation=self._generation,\\n                    timeout_seconds=settings.timeout_seconds,\\n                    memory_mb=settings.memory_mb,\\n                    allow_network=settings.allow_network,\\n                    allowed_domains=settings.allowed_domains,\\n                    allow_software_emulation=settings.allow_software_emulation,\\n                    env=env,\\n                ),\\n                loop,\\n            )\\n        # The VM enforces timeout_seconds internally (exit_code -1 on\\n        # timeout); the outer margin only guards against a wedged scheduler so\\n        # the component thread cannot hang forever. The first execution gets a\\n        # larger margin because Scheduler startup (image download, VM boot)\\n        # happens inside the same coroutine.\\n        grace = _STARTUP_GRACE_SECONDS if is_first_execution else _RUN_GRACE_SECONDS\\n        deadline = settings.timeout_seconds + grace\\n        try:\\n            return future.result(timeout=deadline)\\n        except SandboxExecutionError:\\n            raise\\n        except TimeoutError as e:\\n            future.cancel()\\n            msg = f\\\"Sandboxed execution did not complete within {deadline}s (scheduler unresponsive).\\\"\\n            raise SandboxExecutionError(msg) from e\\n        except Exception as e:\\n            # exec_sandbox raises its own exception hierarchy (SandboxError\\n            # subclasses) for VM/infrastructure failures; surface them under\\n            # this module's stable exception type so callers do not need to\\n            # import exec_sandbox to handle errors.\\n            logger.debug(\\\"Sandboxed execution failed\\\", exc_info=True)\\n            msg = f\\\"Sandboxed execution failed: {type(e).__name__}: {e}\\\"\\n            raise SandboxExecutionError(msg) from e\\n\\n\\n# Re-executing this module (importlib.reload, or a test that reimports it)\\n# must not raise. seal_builtins() has run by then, and re-registering a sealed\\n# built-in name is refused by design -- which is the correct refusal, just not\\n# a reason to break the import.\\nwith contextlib.suppress(ValueError):\\n    register_sandbox_backend(SANDBOX_BACKEND_EXEC_SANDBOX, _ExecSandboxExecutor)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/utils/sandbox/registry.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"fb7b0de549e6774e368ac4114e311c64a2ebfc48b38c18a6d773dcdac67b7238\",\"content\":\"\\\"\\\"\\\"Backend registry: the one place that maps a backend name to its implementation.\\n\\nBefore this registry the name ``exec-sandbox`` had to be spelled in two\\nindependent allowlists \u2014 the dispatch chain here and a second copy inside\\n``lfx.services.settings.groups.security.validate_sandbox_backend``. A backend\\nadded to one and missed in the other made Langflow raise at startup. The\\nregistry owns the list, so the two cannot drift.\\n\\nA backend registers itself at import. In-tree backends are imported by\\n``lfx.utils.sandbox``; an out-of-tree backend ships a package that declares an\\n``lfx.sandbox_backends`` entry point, which is the same mechanism the service\\nlayer uses (``lfx.services.manager._discover_from_entry_points``).\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport contextlib\\nimport os\\nimport threading\\nfrom typing import TYPE_CHECKING\\n\\nfrom lfx.log.logger import logger\\n\\nif TYPE_CHECKING:\\n    from collections.abc import Callable\\n    from importlib.metadata import EntryPoint\\n\\n    from lfx.utils.sandbox.base import SandboxBackend\\n\\n# The one name that never reaches a backend: it means \\\"no sandbox at all\\\".\\nSANDBOX_BACKEND_NONE = \\\"none\\\"\\n\\n_ENTRY_POINT_GROUP = \\\"lfx.sandbox_backends\\\"\\n\\n# Guards the registry dictionaries only. Never held while third-party code\\n# runs, so a factory or a plugin import can call back into this module.\\n_lock = threading.Lock()\\n# Held across the whole entry-point load, so a second thread waits for the\\n# load to FINISH rather than observing a half-populated registry. Reentrant:\\n# a plugin module that calls back into this module during its own import must\\n# not deadlock against the load that imported it.\\n_load_lock = threading.RLock()\\n_factories: dict[str, Callable[[], SandboxBackend]] = {}\\n_instances: dict[str, SandboxBackend] = {}\\n_entry_points_loaded = False\\n# Names owned by in-tree backends, frozen by seal_builtins(). A plugin can\\n# never take one of these over.\\n_builtin_names: frozenset[str] = frozenset()\\n\\n\\ndef register_sandbox_backend(name: str, factory: Callable[[], SandboxBackend]) -> None:\\n    \\\"\\\"\\\"Register ``factory`` under ``name``.\\n\\n    The factory is called lazily when the backend is first used, so registering\\n    a backend costs nothing until an operator selects it. Concurrent first\\n    resolutions may construct more than one candidate; the registry keeps one\\n    singleton and shuts the others down. A name may be registered only once:\\n    replacing a live backend would orphan its process-wide resources and could\\n    race an in-flight resolution against two different factories.\\n\\n    The name is stripped and lowercased. The settings validator normalizes\\n    ``sandbox_backend`` before comparing it against\\n    :func:`known_sandbox_backends`, so a name registered with an uppercase\\n    letter would be listed as available and yet never be selectable.\\n    \\\"\\\"\\\"\\n    name = name.strip().lower()\\n    if not name:\\n        msg = \\\"a sandbox backend name cannot be empty\\\"\\n        raise ValueError(msg)\\n    if name == SANDBOX_BACKEND_NONE:\\n        msg = f\\\"{SANDBOX_BACKEND_NONE!r} is reserved and cannot name a backend\\\"\\n        raise ValueError(msg)\\n    if not callable(factory):\\n        msg = f\\\"sandbox backend {name!r} must register a callable factory\\\"\\n        raise TypeError(msg)\\n    if name in _builtin_names:\\n        # Replacing a built-in would let anything that can run an import\\n        # substitute its own executor for exec-sandbox while the\\n        # operator's settings still name the backend they trusted.\\n        msg = f\\\"{name!r} is a built-in sandbox backend and cannot be replaced\\\"\\n        raise ValueError(msg)\\n    with _lock:\\n        if name in _factories:\\n            msg = f\\\"sandbox backend {name!r} is already registered\\\"\\n            raise ValueError(msg)\\n        _factories[name] = factory\\n\\n\\ndef known_sandbox_backends() -> tuple[str, ...]:\\n    \\\"\\\"\\\"Every accepted value of LANGFLOW_SANDBOX_BACKEND, including ``none``.\\n\\n    Read by the dispatcher and by the settings validator, so an operator can\\n    never be told a backend is unknown by one and accepted by the other.\\n    \\\"\\\"\\\"\\n    _load_entry_points()\\n    with _lock:\\n        return (SANDBOX_BACKEND_NONE, *sorted(_factories))\\n\\n\\ndef resolve_sandbox_backend(name: str) -> SandboxBackend:\\n    \\\"\\\"\\\"Return the singleton instance of the backend called ``name``.\\n\\n    Raises:\\n        KeyError: No backend is registered under that name. The caller turns\\n            this into the operator-facing message, because only the caller\\n            knows which setting supplied the name.\\n    \\\"\\\"\\\"\\n    name = name.lower()\\n    _load_entry_points()\\n    with _lock:\\n        instance = _instances.get(name)\\n        if instance is not None:\\n            return instance\\n        factory = _factories[name]\\n\\n    # Built outside the lock. A factory validates control-plane configuration\\n    # or probes hardware acceleration, and it may call back into this module;\\n    # `_lock` is not reentrant, so holding it here would deadlock the process\\n    # on the first such factory and would block `known_sandbox_backends()` --\\n    # which the settings validator calls at startup -- for the whole probe.\\n    built = factory()\\n\\n    with _lock:\\n        # Another thread may have finished first while we were building.\\n        # Whoever landed first wins, so the singleton stays a singleton.\\n        winner = _instances.setdefault(name, built)\\n\\n    if winner is not built:\\n        # The loser is unreachable: it is not in _instances, so\\n        # live_sandbox_backends() never returns it and shutdown_sandbox()\\n        # cannot reach it. A factory that acquired a loop thread or a client\\n        # pool would leak it for the process lifetime.\\n        with contextlib.suppress(Exception):\\n            built.shutdown()\\n    return winner\\n\\n\\ndef live_sandbox_backends() -> tuple[SandboxBackend, ...]:\\n    \\\"\\\"\\\"Every backend instance that was actually built.\\n\\n    Used by process-wide hooks (fork, shutdown) that must touch what exists\\n    without constructing anything that does not.\\n    \\\"\\\"\\\"\\n    with _lock:\\n        return tuple(_instances.values())\\n\\n\\ndef reset_registry_after_fork() -> None:\\n    \\\"\\\"\\\"Replace this module's mutexes in a freshly forked child.\\n\\n    A lock held by another thread at fork time is inherited LOCKED with no\\n    owner, and the child has no thread that can release it. Every reader here\\n    would then block forever, including the fork hook itself, which reads the\\n    registry before it touches anything else.\\n\\n    Only safe in the child's single-threaded post-fork window, which is the\\n    only place it is called from.\\n    \\\"\\\"\\\"\\n    global _lock, _load_lock  # noqa: PLW0603 - post-fork mutex replacement\\n    _lock = threading.Lock()\\n    _load_lock = threading.RLock()\\n\\n\\ndef seal_builtins() -> None:\\n    \\\"\\\"\\\"Mark everything registered so far as in-tree.\\n\\n    Called once, after the in-tree backends import themselves. A name recorded\\n    here can never be taken over afterwards, so an installed package cannot\\n    quietly become ``exec-sandbox``.\\n    \\\"\\\"\\\"\\n    global _builtin_names  # noqa: PLW0603 - module-level one-shot latch\\n    with _lock:\\n        _builtin_names = frozenset(_factories)\\n\\n\\ndef _plugin_allowlist() -> frozenset[str]:\\n    \\\"\\\"\\\"Entry-point names the operator has explicitly permitted.\\n\\n    Empty by default, which means no out-of-tree code is imported at all.\\n\\n    This is an environment variable rather than a settings field for two\\n    reasons. The settings validator calls\\n    :func:`known_sandbox_backends`, so reading settings from here would\\n    recurse. More importantly, trusting a package to enforce an isolation\\n    boundary is a deployment decision about what is installed on the host, not\\n    an application preference someone should be able to edit through the app.\\n    \\\"\\\"\\\"\\n    # Lowercased, because register_sandbox_backend lowercases too. Matching\\n    # verbatim on one side and normalizing on the other means an operator who\\n    # spells the case differently from the entry point gets a silent skip and\\n    # a startup failure reporting the backend as unknown.\\n    raw = os.environ.get(\\\"LANGFLOW_SANDBOX_BACKEND_PLUGINS\\\", \\\"\\\")\\n    return frozenset(name.strip().lower() for name in raw.split(\\\",\\\") if name.strip())\\n\\n\\ndef _load_entry_points() -> None:\\n    \\\"\\\"\\\"Load the out-of-tree backends the operator named, once per process.\\n\\n    Discovery is deliberately NOT automatic. ``entry_point.load()`` imports\\n    third-party code into the Langflow process, and this function runs on the\\n    path that decides whether user code is isolated -- including from the\\n    settings validator at startup. Importing every installed package that\\n    happens to declare the group would let a compromised or merely mistaken\\n    dependency execute here, before anything has chosen a backend, and the\\n    later policy gate cannot help: it only compares fields the backend reports\\n    about itself.\\n\\n    So capability declarations are configuration metadata, not evidence of\\n    enforcement, and the trust decision is the operator's:\\n    ``LANGFLOW_SANDBOX_BACKEND_PLUGINS`` names the entry points that may load.\\n    Anything unnamed is never imported. A name already used in-tree is refused\\n    rather than replaced.\\n\\n    A broken third-party package must not stop a correctly configured Langflow\\n    from starting, so a failure here is logged and the backend is simply\\n    absent. It cannot fail open: an absent backend makes the dispatcher refuse\\n    the run.\\n    \\\"\\\"\\\"\\n    global _entry_points_loaded  # noqa: PLW0603 - module-level one-shot latch\\n    # The latch is read AND set under a lock that stays held for the whole\\n    # load. Set it before importing a plugin so a same-thread callback into\\n    # known_sandbox_backends() sees the registry state collected so far rather\\n    # than recursively starting the entry-point load again. Other threads\\n    # cannot observe the early value: they remain blocked on _load_lock until\\n    # the load has finished.\\n    with _load_lock:\\n        if _entry_points_loaded:\\n            return\\n        _entry_points_loaded = True\\n        _load_entry_points_locked()\\n\\n\\ndef _load_entry_points_locked() -> None:\\n    \\\"\\\"\\\"The body of :func:`_load_entry_points`, run once with ``_load_lock`` held.\\\"\\\"\\\"\\n    allowed = _plugin_allowlist()\\n    if not allowed:\\n        return\\n\\n    from importlib.metadata import entry_points\\n\\n    try:\\n        discovered = entry_points(group=_ENTRY_POINT_GROUP)\\n    except Exception:  # noqa: BLE001 - a broken environment must not block startup\\n        logger.warning(\\\"Could not enumerate %s entry points\\\", _ENTRY_POINT_GROUP, exc_info=True)\\n        return\\n\\n    # Grouped by name BEFORE anything is loaded. Two installed distributions can\\n    # publish the same entry-point name, and the allowlist names a backend, not a\\n    # distribution -- so it cannot say which of the two the operator meant.\\n    # Loading either one would be a guess, and the guess is made by whatever order\\n    # importlib.metadata happens to return, which the operator cannot see or pin.\\n    # Worse, the loop would import BOTH and let the second overwrite the first, so\\n    # the code that ran an import is not even the code that ends up registered.\\n    # Refusing the name is the only answer that never runs unintended code.\\n    by_name: dict[str, list[EntryPoint]] = {}\\n    for entry_point in discovered:\\n        by_name.setdefault(entry_point.name.strip().lower(), []).append(entry_point)\\n\\n    for plugin_name, candidates in by_name.items():\\n        if plugin_name not in allowed:\\n            logger.debug(\\\"Ignoring sandbox backend %r: not listed in LANGFLOW_SANDBOX_BACKEND_PLUGINS\\\", plugin_name)\\n            continue\\n        if len(candidates) > 1:\\n            logger.warning(\\n                \\\"Refusing sandbox backend plugin %r: %d installed distributions provide that name (%s). \\\"\\n                \\\"Uninstall all but one, because the allowlist names a backend and cannot choose between them.\\\",\\n                plugin_name,\\n                len(candidates),\\n                \\\", \\\".join(sorted(_distribution_of(candidate) for candidate in candidates)),\\n            )\\n            continue\\n        entry_point = candidates[0]\\n        if plugin_name in _builtin_names:\\n            logger.warning(\\n                \\\"Refusing sandbox backend plugin %r: that name belongs to a built-in backend\\\", entry_point.name\\n            )\\n            continue\\n        try:\\n            factory = entry_point.load()\\n        except Exception:  # noqa: BLE001 - one bad plugin must not hide the others\\n            logger.warning(\\\"Could not load sandbox backend %r\\\", entry_point.name, exc_info=True)\\n            continue\\n        try:\\n            register_sandbox_backend(plugin_name, factory)\\n        except (TypeError, ValueError):\\n            # Malformed factory, reserved name, or duplicate name. The docstring promises a broken\\n            # plugin is absent rather than fatal, so this cannot propagate out\\n            # of the settings validator.\\n            logger.warning(\\\"Refusing sandbox backend plugin %r\\\", entry_point.name, exc_info=True)\\n            continue\\n        logger.info(\\\"Registered out-of-tree sandbox backend %r\\\", entry_point.name)\\n\\n\\ndef _distribution_of(entry_point: EntryPoint) -> str:\\n    \\\"\\\"\\\"Name the installed distribution an entry point came from, for a refusal message.\\n\\n    Best effort: ``EntryPoint.dist`` is populated by ``entry_points()`` but is\\n    documented as optional, and the operator still has to be told the name is\\n    contested even when we cannot say by whom.\\n    \\\"\\\"\\\"\\n    dist = getattr(entry_point, \\\"dist\\\", None)\\n    return getattr(dist, \\\"name\\\", None) or \\\"unknown distribution\\\"\\n\\n\\ndef get_sandbox_backend() -> str:\\n    \\\"\\\"\\\"Return the configured sandbox backend name (``none`` when unset).\\n\\n    ``get_settings_service()`` returns None when the settings stack failed to\\n    build, which is indistinguishable here from \\\"never configured\\\". Answering\\n    ``none`` in that case would send user code to in-process ``exec`` on a\\n    deployment that explicitly asked for a sandbox, so the environment is read\\n    directly as a fallback. A name that no backend claims then fails closed in\\n    :func:`run_code_in_sandbox` rather than running unsandboxed.\\n    \\\"\\\"\\\"\\n    try:\\n        from lfx.services.deps import get_settings_service\\n\\n        settings_service = get_settings_service()\\n    except ImportError:\\n        settings_service = None\\n    if settings_service is not None:\\n        backend = getattr(settings_service.settings, \\\"sandbox_backend\\\", None)\\n        if backend:\\n            return backend.lower()\\n    return os.environ.get(\\\"LANGFLOW_SANDBOX_BACKEND\\\", \\\"\\\").strip().lower() or SANDBOX_BACKEND_NONE\\n\\n\\ndef is_sandbox_enabled() -> bool:\\n    \\\"\\\"\\\"True when a non-default sandbox backend is configured.\\\"\\\"\\\"\\n    return get_sandbox_backend() != SANDBOX_BACKEND_NONE\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/utils/schemas.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"b1b8e4ec20cb66c11f87cd6ea34825fb2dcc516e001b6caa70234f528d10388d\",\"content\":\"import enum\\nfrom typing import Any\\nfrom uuid import UUID\\n\\nfrom langchain_core.messages import BaseMessage\\nfrom pydantic import BaseModel, field_validator, model_validator\\nfrom typing_extensions import TypedDict\\n\\nfrom .constants import MESSAGE_SENDER_AI, MESSAGE_SENDER_NAME_AI\\n\\n# File types moved from lfx.base.data.utils\\nTEXT_FILE_TYPES = [\\n    \\\"txt\\\",\\n    \\\"md\\\",\\n    \\\"mdx\\\",\\n    \\\"csv\\\",\\n    \\\"json\\\",\\n    \\\"yaml\\\",\\n    \\\"yml\\\",\\n    \\\"xml\\\",\\n    \\\"html\\\",\\n    \\\"htm\\\",\\n    \\\"pdf\\\",\\n    \\\"docx\\\",\\n    \\\"py\\\",\\n    \\\"sh\\\",\\n    \\\"sql\\\",\\n    \\\"js\\\",\\n    \\\"ts\\\",\\n    \\\"tsx\\\",\\n]\\nIMG_FILE_TYPES = [\\\"jpg\\\", \\\"jpeg\\\", \\\"png\\\", \\\"bmp\\\", \\\"image\\\"]\\n\\n\\nclass File(TypedDict):\\n    \\\"\\\"\\\"File schema.\\\"\\\"\\\"\\n\\n    path: str\\n    name: str\\n    type: str\\n\\n\\nclass ChatOutputResponse(BaseModel):\\n    \\\"\\\"\\\"Chat output response schema.\\\"\\\"\\\"\\n\\n    message: str | list[str | dict]\\n    sender: str | None = MESSAGE_SENDER_AI\\n    sender_name: str | None = MESSAGE_SENDER_NAME_AI\\n    session_id: str | None = None\\n    \\\"\\\"\\\"If set, must be a string. If a UUID type is provided,\\n    it will be converted to a string. No other types are accepted.\\\"\\\"\\\"\\n    stream_url: str | None = None\\n    component_id: str | None = None\\n    files: list[File] = []\\n    type: str\\n\\n    @field_validator(\\\"files\\\", mode=\\\"before\\\")\\n    @classmethod\\n    def validate_files(cls, files):\\n        \\\"\\\"\\\"Validate files.\\\"\\\"\\\"\\n        if not files:\\n            return files\\n\\n        for file in files:\\n            if not isinstance(file, dict):\\n                msg = \\\"Files must be a list of dictionaries.\\\"\\n                raise ValueError(msg)  # noqa: TRY004\\n\\n            if not all(key in file for key in [\\\"path\\\", \\\"name\\\", \\\"type\\\"]):\\n                # If any of the keys are missing, we should extract the\\n                # values from the file path\\n                path = file.get(\\\"path\\\")\\n                if not path:\\n                    msg = \\\"File path is required.\\\"\\n                    raise ValueError(msg)\\n\\n                name = file.get(\\\"name\\\")\\n                if not name:\\n                    name = path.split(\\\"/\\\")[-1]\\n                    file[\\\"name\\\"] = name\\n                type_ = file.get(\\\"type\\\")\\n                if not type_:\\n                    # get the file type from the path\\n                    extension = path.split(\\\".\\\")[-1]\\n                    file_types = set(TEXT_FILE_TYPES + IMG_FILE_TYPES)\\n                    if extension and extension in file_types:\\n                        type_ = extension\\n                    else:\\n                        for file_type in file_types:\\n                            if file_type in path:\\n                                type_ = file_type\\n                                break\\n                    if not type_:\\n                        msg = \\\"File type is required.\\\"\\n                        raise ValueError(msg)\\n                file[\\\"type\\\"] = type_\\n\\n        return files\\n\\n    @classmethod\\n    def from_message(\\n        cls,\\n        message: BaseMessage,\\n        sender: str | None = MESSAGE_SENDER_AI,\\n        sender_name: str | None = MESSAGE_SENDER_NAME_AI,\\n    ):\\n        \\\"\\\"\\\"Build chat output response from message.\\\"\\\"\\\"\\n        content = message.content\\n        return cls(message=content, sender=sender, sender_name=sender_name)\\n\\n    @model_validator(mode=\\\"after\\\")\\n    def validate_message(self):\\n        \\\"\\\"\\\"Validate message.\\\"\\\"\\\"\\n        # The idea here is ensure the \\\\n in message\\n        # is compliant with markdown if sender is machine\\n        # so, for example:\\n        # \\\\n\\\\n -> \\\\n\\\\n\\n        # \\\\n -> \\\\n\\\\n\\n\\n        if self.sender != MESSAGE_SENDER_AI:\\n            return self\\n\\n        # We need to make sure we don't duplicate \\\\n\\n        # in the message\\n        message = self.message.replace(\\\"\\\\n\\\\n\\\", \\\"\\\\n\\\")\\n        self.message = message.replace(\\\"\\\\n\\\", \\\"\\\\n\\\\n\\\")\\n        return self\\n\\n    @field_validator(\\\"session_id\\\", mode=\\\"before\\\")\\n    @classmethod\\n    def validate_and_coerce_session_id(cls, value: Any) -> str | None:\\n        \\\"\\\"\\\"Validate and coerce session id to a string if it is a UUID.\\n\\n        Must be a UUID, string, or None.\\n        If the session id is a UUID, it will be converted to a string.\\n        If the session id is a string or None, it will be returned as is.\\n        Otherwise, a ValueError will be raised.\\n        \\\"\\\"\\\"\\n        if value is None or isinstance(value, str):\\n            return value\\n        if isinstance(value, UUID):\\n            return str(value)\\n        msg = f\\\"The provided Session ID must be a UUID, string, or None. Got {value} of type {type(value)}.\\\"\\n        raise ValueError(msg)\\n\\n\\nclass DataOutputResponse(BaseModel):\\n    \\\"\\\"\\\"Data output response schema.\\\"\\\"\\\"\\n\\n    data: list[dict | None]\\n\\n\\nclass ContainsEnumMeta(enum.EnumMeta):\\n    def __contains__(cls, item) -> bool:\\n        try:\\n            cls(item)\\n        except ValueError:\\n            return False\\n        else:\\n            return True\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/utils/secrets.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"0368e298fe0d290463b6ecdf7a4494be730485d1733fef72fa50e7f07715410d\",\"content\":\"from __future__ import annotations\\n\\nfrom typing import Any, Protocol, TypeGuard\\n\\n\\nclass SecretValue(Protocol):\\n    def get_secret_value(self) -> Any: ...\\n\\n\\ndef is_secret_value(value: Any) -> TypeGuard[SecretValue]:\\n    return callable(getattr(value, \\\"get_secret_value\\\", None))\\n\\n\\ndef unwrap_secret_value(value: Any) -> Any:\\n    seen: set[int] = set()\\n    while is_secret_value(value) and id(value) not in seen:\\n        seen.add(id(value))\\n        value = value.get_secret_value()\\n    return value\\n\\n\\ndef secret_value_to_str(value: Any, *, strip: bool = False) -> str | None:\\n    value = unwrap_secret_value(value)\\n    if value is None:\\n        return None\\n    text = value if isinstance(value, str) else str(value)\\n    return text.strip() if strip else text\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/utils/ssrf_httpx.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"fda82e1c2015e06cdd29bff4298abfebdfdf4c166481e4cef7355d7a1d322359\",\"content\":\"\\\"\\\"\\\"SSRF-protected helpers for ``httpx`` call sites.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom typing import Any\\nfrom urllib.parse import urljoin\\n\\nimport httpx\\n\\nfrom lfx.utils.ssrf_protection import (\\n    SSRFProtectionError,\\n    is_connector_ssrf_validation_enabled,\\n    is_ssrf_protection_enabled,\\n    validate_and_resolve_connector_url,\\n    validate_and_resolve_url,\\n    validate_connector_url_for_ssrf,\\n    validate_url_for_ssrf,\\n)\\nfrom lfx.utils.ssrf_transport import (\\n    SSRFProtectedSyncTransport,\\n    SSRFProtectedTransport,\\n    create_ssrf_protected_client,\\n    create_ssrf_protected_sync_client,\\n)\\n\\n# HTTP redirect responses carrying a Location header (RFC 9110).\\nREDIRECT_STATUS_CODES = frozenset({301, 302, 303, 307, 308})\\nDEFAULT_MAX_REDIRECTS = 20\\n\\n\\ndef validate_url_for_ssrf_or_raise(url: str) -> None:\\n    \\\"\\\"\\\"Validate a connector URL and raise a UI-facing error when it is blocked.\\\"\\\"\\\"\\n    try:\\n        validate_connector_url_for_ssrf(url)\\n    except SSRFProtectionError as e:\\n        msg = f\\\"SSRF Protection: {e}\\\"\\n        raise ValueError(msg) from e\\n\\n\\ndef validate_strict_url_for_ssrf_or_raise(url: str) -> None:\\n    \\\"\\\"\\\"Validate a credential-bearing provider URL without the connector loopback exemption.\\\"\\\"\\\"\\n    try:\\n        if is_connector_ssrf_validation_enabled():\\n            validate_url_for_ssrf(url)\\n    except SSRFProtectionError as e:\\n        msg = f\\\"SSRF Protection: {e}\\\"\\n        raise ValueError(msg) from e\\n\\n\\ndef _validate_and_resolve_strict_url(url: str) -> tuple[str, list[str]]:\\n    \\\"\\\"\\\"Resolve a credential-bearing provider URL without the connector loopback exemption.\\\"\\\"\\\"\\n    if not is_connector_ssrf_validation_enabled():\\n        return url, []\\n    return validate_and_resolve_url(url)\\n\\n\\ndef _raise_if_following_redirects(request_kwargs: dict[str, Any]) -> None:\\n    if request_kwargs.get(\\\"follow_redirects\\\"):\\n        msg = \\\"SSRF-protected httpx helpers do not support automatic redirect following.\\\"\\n        raise SSRFProtectionError(msg)\\n\\n\\ndef _transport_host(url: str) -> str:\\n    \\\"\\\"\\\"Return the IDNA-normalized host httpx/httpcore uses for connections.\\\"\\\"\\\"\\n    return httpx.URL(url).raw_host.decode(\\\"ascii\\\")\\n\\n\\ndef _async_client_for_url(url: str, validated_ips: list[str]) -> httpx.AsyncClient:\\n    if is_ssrf_protection_enabled() and validated_ips:\\n        hostname = _transport_host(url)\\n        if hostname:\\n            return create_ssrf_protected_client(hostname=hostname, validated_ips=validated_ips)\\n    return httpx.AsyncClient()\\n\\n\\ndef _sync_client_for_url(url: str, validated_ips: list[str]) -> httpx.Client:\\n    if is_ssrf_protection_enabled() and validated_ips:\\n        hostname = _transport_host(url)\\n        if hostname:\\n            return create_ssrf_protected_sync_client(hostname=hostname, validated_ips=validated_ips)\\n    return httpx.Client()\\n\\n\\ndef _httpx_client_kwargs_for_validated_url(\\n    validated_url: str, validated_ips: list[str]\\n) -> tuple[dict[str, Any], dict[str, Any]]:\\n    \\\"\\\"\\\"Build sync and async client kwargs for an already validated URL.\\\"\\\"\\\"\\n    if not is_ssrf_protection_enabled():\\n        return {}, {}\\n\\n    sync_kwargs: dict[str, Any] = {\\\"follow_redirects\\\": False}\\n    async_kwargs: dict[str, Any] = {\\\"follow_redirects\\\": False}\\n\\n    hostname = _transport_host(validated_url)\\n    if hostname and validated_ips:\\n        ip_list = list(validated_ips)\\n        sync_kwargs[\\\"transport\\\"] = SSRFProtectedSyncTransport(pinned_ips={hostname: ip_list})\\n        async_kwargs[\\\"transport\\\"] = SSRFProtectedTransport(pinned_ips={hostname: ip_list})\\n\\n    return sync_kwargs, async_kwargs\\n\\n\\ndef ssrf_protected_httpx_client_kwargs_for_url(url: str) -> tuple[dict[str, Any], dict[str, Any]]:\\n    \\\"\\\"\\\"Return sync/async httpx kwargs that enforce connector SSRF protection for SDK clients.\\\"\\\"\\\"\\n    try:\\n        validated_url, validated_ips = validate_and_resolve_connector_url(url)\\n    except SSRFProtectionError as e:\\n        msg = f\\\"SSRF Protection: {e}\\\"\\n        raise ValueError(msg) from e\\n    return _httpx_client_kwargs_for_validated_url(validated_url, validated_ips)\\n\\n\\ndef ssrf_protected_strict_httpx_client_kwargs_for_url(url: str) -> tuple[dict[str, Any], dict[str, Any]]:\\n    \\\"\\\"\\\"Return pinned client kwargs while denying provider loopback unless explicitly allowlisted.\\\"\\\"\\\"\\n    try:\\n        validated_url, validated_ips = _validate_and_resolve_strict_url(url)\\n    except SSRFProtectionError as e:\\n        msg = f\\\"SSRF Protection: {e}\\\"\\n        raise ValueError(msg) from e\\n    return _httpx_client_kwargs_for_validated_url(validated_url, validated_ips)\\n\\n\\ndef _openai_clients_from_kwargs(\\n    sync_kwargs: dict[str, Any], async_kwargs: dict[str, Any]\\n) -> dict[str, httpx.Client | httpx.AsyncClient]:\\n    \\\"\\\"\\\"Build OpenAI-compatible sync and async clients from validated kwargs.\\\"\\\"\\\"\\n    if not sync_kwargs and not async_kwargs:\\n        return {}\\n    return {\\n        \\\"http_client\\\": httpx.Client(**sync_kwargs),\\n        \\\"http_async_client\\\": httpx.AsyncClient(**async_kwargs),\\n    }\\n\\n\\ndef ssrf_protected_openai_clients_for_url(url: str) -> dict[str, httpx.Client | httpx.AsyncClient]:\\n    \\\"\\\"\\\"Return pinned sync and async clients for OpenAI-compatible LangChain components.\\\"\\\"\\\"\\n    return _openai_clients_from_kwargs(*ssrf_protected_httpx_client_kwargs_for_url(url))\\n\\n\\ndef ssrf_protected_strict_openai_clients_for_url(url: str) -> dict[str, httpx.Client | httpx.AsyncClient]:\\n    \\\"\\\"\\\"Return pinned clients while denying provider loopback unless explicitly allowlisted.\\\"\\\"\\\"\\n    return _openai_clients_from_kwargs(*ssrf_protected_strict_httpx_client_kwargs_for_url(url))\\n\\n\\nasync def ssrf_safe_async_get(url: str, **request_kwargs: Any) -> httpx.Response:\\n    \\\"\\\"\\\"Perform an async GET with connector SSRF validation and DNS pinning.\\\"\\\"\\\"\\n    _raise_if_following_redirects(request_kwargs)\\n    validated_url, validated_ips = validate_and_resolve_connector_url(url)\\n    async with _async_client_for_url(validated_url, validated_ips) as client:\\n        return await client.get(url=validated_url, **request_kwargs)\\n\\n\\nasync def ssrf_safe_async_post(url: str, **request_kwargs: Any) -> httpx.Response:\\n    \\\"\\\"\\\"Perform an async POST with connector SSRF validation and DNS pinning.\\\"\\\"\\\"\\n    _raise_if_following_redirects(request_kwargs)\\n    validated_url, validated_ips = validate_and_resolve_connector_url(url)\\n    async with _async_client_for_url(validated_url, validated_ips) as client:\\n        return await client.post(url=validated_url, **request_kwargs)\\n\\n\\ndef _same_origin(first_url: str, second_url: str) -> bool:\\n    first = httpx.URL(first_url)\\n    second = httpx.URL(second_url)\\n    return (first.scheme, first.raw_host, first.port) == (second.scheme, second.raw_host, second.port)\\n\\n\\ndef _is_safe_https_upgrade(previous_url: str, next_url: str) -> bool:\\n    \\\"\\\"\\\"Match httpx's authorization-preserving HTTP-to-HTTPS redirect exception.\\\"\\\"\\\"\\n    previous = httpx.URL(previous_url)\\n    next_ = httpx.URL(next_url)\\n    return (\\n        previous.scheme == \\\"http\\\"\\n        and previous.raw_host == next_.raw_host\\n        and previous.port is None\\n        and next_.scheme == \\\"https\\\"\\n        and next_.port is None\\n    )\\n\\n\\ndef _headers_for_redirect(headers: Any, previous_url: str, next_url: str) -> httpx.Headers | None:\\n    if headers is None:\\n        return None\\n\\n    redirect_headers = httpx.Headers(headers)\\n    if _same_origin(previous_url, next_url):\\n        return redirect_headers\\n\\n    # Match httpx's safe HTTP-to-HTTPS authorization exception, while never\\n    # replaying caller-supplied cookies or proxy credentials across origins.\\n    if not _is_safe_https_upgrade(previous_url, next_url):\\n        redirect_headers.pop(\\\"Authorization\\\", None)\\n    redirect_headers.pop(\\\"Cookie\\\", None)\\n    redirect_headers.pop(\\\"Proxy-Authorization\\\", None)\\n    return redirect_headers\\n\\n\\ndef _request_kwargs_for_redirect(request_kwargs: dict[str, Any], previous_url: str, next_url: str) -> dict[str, Any]:\\n    if _same_origin(previous_url, next_url):\\n        return request_kwargs\\n\\n    redirect_kwargs = request_kwargs.copy()\\n    redirect_kwargs.pop(\\\"cookies\\\", None)\\n    if not _is_safe_https_upgrade(previous_url, next_url):\\n        redirect_kwargs.pop(\\\"auth\\\", None)\\n    return redirect_kwargs\\n\\n\\ndef ssrf_safe_httpx_get(\\n    url: str,\\n    *,\\n    follow_redirects: bool = False,\\n    max_redirects: int = DEFAULT_MAX_REDIRECTS,\\n    **request_kwargs: Any,\\n) -> httpx.Response:\\n    \\\"\\\"\\\"Perform a synchronous GET with connector SSRF validation and DNS pinning.\\n\\n    When redirects are requested, they are followed manually so each target is\\n    independently validated and connected through a transport pinned to the IPs\\n    returned by that validation. Credentials are not forwarded across origins,\\n    except authorization on a same-host, standard-port HTTP-to-HTTPS upgrade.\\n    \\\"\\\"\\\"\\n    current_url = url\\n    supplied_headers = request_kwargs.pop(\\\"headers\\\", None)\\n    current_headers = httpx.Headers(supplied_headers) if supplied_headers is not None else None\\n    current_params = request_kwargs.pop(\\\"params\\\", None)\\n    current_request_kwargs = request_kwargs\\n\\n    for _ in range(max_redirects + 1):\\n        validated_url, validated_ips = validate_and_resolve_connector_url(current_url)\\n        with _sync_client_for_url(validated_url, validated_ips) as client:\\n            response = client.get(\\n                url=validated_url,\\n                headers=current_headers,\\n                params=current_params,\\n                follow_redirects=False,\\n                **current_request_kwargs,\\n            )\\n\\n        location = response.headers.get(\\\"location\\\")\\n        if not follow_redirects or response.status_code not in REDIRECT_STATUS_CODES or not location:\\n            return response\\n\\n        next_url = urljoin(validated_url, location)\\n        current_headers = _headers_for_redirect(current_headers, validated_url, next_url)\\n        current_request_kwargs = _request_kwargs_for_redirect(current_request_kwargs, validated_url, next_url)\\n        current_url = next_url\\n        # Redirect locations carry their own query string; initial params apply once.\\n        current_params = None\\n\\n    msg = f\\\"Exceeded the maximum of {max_redirects} redirects while requesting {url}\\\"\\n    raise SSRFProtectionError(msg)\\n\\n\\ndef ssrf_safe_httpx_get_bounded(\\n    url: str,\\n    *,\\n    max_bytes: int,\\n    follow_redirects: bool = False,\\n    max_redirects: int = DEFAULT_MAX_REDIRECTS,\\n    **request_kwargs: Any,\\n) -> bytes:\\n    \\\"\\\"\\\"GET with connector SSRF validation, refusing a body larger than ``max_bytes``.\\n\\n    :func:`ssrf_safe_httpx_get` buffers the whole response before a caller can measure it, so\\n    a size check on the returned content has already paid the memory cost. This streams\\n    instead and abandons the transfer as soon as the cap is passed, so a hostile endpoint\\n    cannot exhaust memory by answering an allowed request with an unbounded body.\\n\\n    Redirects are validated per hop exactly as in :func:`ssrf_safe_httpx_get`; only the final\\n    response is streamed.\\n\\n    Raises:\\n        SSRFProtectionError: if a hop fails validation or the redirect budget is exhausted.\\n        ValueError: if the body exceeds ``max_bytes``.\\n    \\\"\\\"\\\"\\n    current_url = url\\n    supplied_headers = request_kwargs.pop(\\\"headers\\\", None)\\n    current_headers = httpx.Headers(supplied_headers) if supplied_headers is not None else None\\n    current_params = request_kwargs.pop(\\\"params\\\", None)\\n    current_request_kwargs = request_kwargs\\n\\n    for _ in range(max_redirects + 1):\\n        validated_url, validated_ips = validate_and_resolve_connector_url(current_url)\\n        with (\\n            _sync_client_for_url(validated_url, validated_ips) as client,\\n            client.stream(\\n                \\\"GET\\\",\\n                url=validated_url,\\n                headers=current_headers,\\n                params=current_params,\\n                follow_redirects=False,\\n                **current_request_kwargs,\\n            ) as response,\\n        ):\\n            location = response.headers.get(\\\"location\\\")\\n            is_redirect = response.status_code in REDIRECT_STATUS_CODES and bool(location)\\n            if not follow_redirects or not is_redirect:\\n                response.raise_for_status()\\n                chunks: list[bytes] = []\\n                total = 0\\n                for chunk in response.iter_bytes():\\n                    total += len(chunk)\\n                    if total > max_bytes:\\n                        msg = f\\\"Response from {url} exceeds the maximum size of {max_bytes} bytes\\\"\\n                        raise ValueError(msg)\\n                    chunks.append(chunk)\\n                return b\\\"\\\".join(chunks)\\n\\n        next_url = urljoin(validated_url, location)\\n        current_headers = _headers_for_redirect(current_headers, validated_url, next_url)\\n        current_request_kwargs = _request_kwargs_for_redirect(current_request_kwargs, validated_url, next_url)\\n        current_url = next_url\\n        # Redirect locations carry their own query string; initial params apply once.\\n        current_params = None\\n\\n    msg = f\\\"Exceeded the maximum of {max_redirects} redirects while requesting {url}\\\"\\n    raise SSRFProtectionError(msg)\\n\\n\\ndef ssrf_safe_httpx_post(url: str, **request_kwargs: Any) -> httpx.Response:\\n    \\\"\\\"\\\"Perform a synchronous POST with connector SSRF validation and DNS pinning.\\\"\\\"\\\"\\n    _raise_if_following_redirects(request_kwargs)\\n    validated_url, validated_ips = validate_and_resolve_connector_url(url)\\n    with _sync_client_for_url(validated_url, validated_ips) as client:\\n        return client.post(url=validated_url, **request_kwargs)\\n\\n\\ndef ssrf_safe_strict_httpx_post(url: str, **request_kwargs: Any) -> httpx.Response:\\n    \\\"\\\"\\\"POST to a credential-bearing provider URL with strict validation and DNS pinning.\\\"\\\"\\\"\\n    _raise_if_following_redirects(request_kwargs)\\n    validated_url, validated_ips = _validate_and_resolve_strict_url(url)\\n    with _sync_client_for_url(validated_url, validated_ips) as client:\\n        return client.post(url=validated_url, **request_kwargs)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/utils/ssrf_protection.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"03680e1449208b14768999fd97060b06c7b9cb9d73de0beeb7ac4701ae9357c2\",\"content\":\"\\\"\\\"\\\"SSRF (Server-Side Request Forgery) protection utilities.\\n\\nThis module provides validation to prevent SSRF attacks by blocking requests to:\\n- Private IP ranges (RFC 1918)\\n- Loopback addresses\\n- Cloud metadata endpoints (169.254.169.254)\\n- Other internal/special-use addresses\\n\\nIMPORTANT: HTTP Redirects\\n    According to OWASP SSRF Prevention Cheat Sheet, HTTP redirects should be DISABLED\\n    to prevent bypass attacks where a public URL redirects to internal resources.\\n    The API Request component has (as of v1.7.0) follow_redirects=False by default.\\n    See: https://cheatsheetseries.owasp.org/cheatsheets/Server_Side_Request_Forgery_Prevention_Cheat_Sheet.html\\n\\nConfiguration:\\n    LANGFLOW_SSRF_PROTECTION_ENABLED: Enable/disable SSRF protection (default: true)\\n    LANGFLOW_SSRF_ALLOWED_HOSTS: Comma-separated list of allowed hosts/CIDR ranges\\n        Examples: \\\"192.168.1.0/24,internal-api.company.local,10.0.0.5\\\"\\n\\\"\\\"\\\"\\n\\nimport functools\\nimport ipaddress\\nimport re\\nimport socket\\nfrom urllib.parse import parse_qsl, urlparse\\n\\nfrom lfx.logging import logger\\nfrom lfx.services.deps import get_settings_service\\nfrom lfx.utils.file_path_security import is_local_file_access_restricted\\n\\n\\nclass SSRFProtectionError(ValueError):\\n    \\\"\\\"\\\"Raised when a URL is blocked due to SSRF protection.\\\"\\\"\\\"\\n\\n\\n@functools.cache\\ndef get_blocked_ip_ranges() -> list[ipaddress.IPv4Network | ipaddress.IPv6Network]:\\n    \\\"\\\"\\\"Get the list of blocked IP ranges, initializing lazily on first access.\\n\\n    This lazy loading avoids the startup cost of creating all ip_network objects\\n    at module import time.\\n\\n    Returns:\\n        list: List of blocked IPv4 and IPv6 network ranges.\\n    \\\"\\\"\\\"\\n    return [\\n        # IPv4 ranges\\n        ipaddress.ip_network(\\\"0.0.0.0/8\\\"),  # Current network (only valid as source)\\n        ipaddress.ip_network(\\\"10.0.0.0/8\\\"),  # Private network (RFC 1918)\\n        ipaddress.ip_network(\\\"100.64.0.0/10\\\"),  # Carrier-grade NAT (RFC 6598)\\n        ipaddress.ip_network(\\\"127.0.0.0/8\\\"),  # Loopback\\n        ipaddress.ip_network(\\\"169.254.0.0/16\\\"),  # Link-local / AWS metadata\\n        ipaddress.ip_network(\\\"172.16.0.0/12\\\"),  # Private network (RFC 1918)\\n        ipaddress.ip_network(\\\"192.0.0.0/24\\\"),  # IETF Protocol Assignments\\n        ipaddress.ip_network(\\\"192.0.2.0/24\\\"),  # Documentation (TEST-NET-1)\\n        ipaddress.ip_network(\\\"192.168.0.0/16\\\"),  # Private network (RFC 1918)\\n        ipaddress.ip_network(\\\"198.18.0.0/15\\\"),  # Benchmarking\\n        ipaddress.ip_network(\\\"198.51.100.0/24\\\"),  # Documentation (TEST-NET-2)\\n        ipaddress.ip_network(\\\"203.0.113.0/24\\\"),  # Documentation (TEST-NET-3)\\n        ipaddress.ip_network(\\\"224.0.0.0/4\\\"),  # Multicast\\n        ipaddress.ip_network(\\\"240.0.0.0/4\\\"),  # Reserved\\n        ipaddress.ip_network(\\\"255.255.255.255/32\\\"),  # Broadcast\\n        # IPv6 ranges\\n        ipaddress.ip_network(\\\"::1/128\\\"),  # Loopback\\n        ipaddress.ip_network(\\\"::/128\\\"),  # Unspecified address\\n        ipaddress.ip_network(\\\"::ffff:0:0/96\\\"),  # IPv4-mapped IPv6 addresses\\n        ipaddress.ip_network(\\\"100::/64\\\"),  # Discard prefix\\n        ipaddress.ip_network(\\\"2001::/23\\\"),  # IETF Protocol Assignments\\n        ipaddress.ip_network(\\\"2001:db8::/32\\\"),  # Documentation\\n        ipaddress.ip_network(\\\"fc00::/7\\\"),  # Unique local addresses (ULA)\\n        ipaddress.ip_network(\\\"fe80::/10\\\"),  # Link-local\\n        ipaddress.ip_network(\\\"ff00::/8\\\"),  # Multicast\\n    ]\\n\\n\\ndef is_ssrf_protection_enabled() -> bool:\\n    \\\"\\\"\\\"Check if SSRF protection is enabled in settings.\\n\\n    Returns:\\n        bool: True if SSRF protection is enabled, False otherwise.\\n    \\\"\\\"\\\"\\n    # Read directly from environment variable to support test mocking with patch.dict()\\n    # This ensures tests can override the protection state without settings service caching issues\\n    import os\\n\\n    env_value = os.getenv(\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\")\\n    if env_value is not None:\\n        # Environment variable is set - use it (supports test mocking)\\n        return env_value.lower() in (\\\"true\\\", \\\"1\\\", \\\"yes\\\", \\\"on\\\")\\n\\n    # Fall back to settings service for non-test scenarios\\n    return get_settings_service().settings.ssrf_protection_enabled\\n\\n\\ndef get_allowed_hosts() -> list[str]:\\n    \\\"\\\"\\\"Get list of allowed hosts and/or CIDR ranges for SSRF protection.\\n\\n    Returns:\\n        list[str]: Stripped hostnames or CIDR blocks from settings, or empty list if unset.\\n    \\\"\\\"\\\"\\n    # Read directly from environment variable to support test mocking with patch.dict()\\n    # This ensures tests can override the allowlist without settings service caching issues\\n    import os\\n\\n    env_value = os.getenv(\\\"LANGFLOW_SSRF_ALLOWED_HOSTS\\\", \\\"\\\")\\n    if env_value:\\n        # Parse comma-separated list from environment variable\\n        return [host.strip() for host in env_value.split(\\\",\\\") if host.strip()]\\n\\n    # Fall back to settings service for non-test scenarios\\n    settings_service = get_settings_service()\\n    if settings_service:\\n        allowed_hosts = settings_service.settings.ssrf_allowed_hosts\\n        if allowed_hosts:\\n            return [host.strip() for host in allowed_hosts if host and host.strip()]\\n\\n    return []\\n\\n\\ndef is_host_allowed(hostname: str, ip: str | None = None) -> bool:\\n    \\\"\\\"\\\"Check if a hostname or IP is in the allowed hosts list.\\n\\n    Args:\\n        hostname: Hostname to check\\n        ip: Optional IP address to check\\n\\n    Returns:\\n        bool: True if hostname or IP is in the allowed list, False otherwise.\\n    \\\"\\\"\\\"\\n    allowed_hosts = get_allowed_hosts()\\n    if not allowed_hosts:\\n        return False\\n\\n    # Check hostname match\\n    if hostname in allowed_hosts:\\n        return True\\n\\n    # Check if hostname matches any wildcard patterns\\n    for allowed in allowed_hosts:\\n        if allowed.startswith(\\\"*.\\\"):\\n            # Wildcard domain matching\\n            domain_suffix = allowed[1:]  # Remove the *\\n            if hostname.endswith(domain_suffix) or hostname == domain_suffix[1:]:\\n                return True\\n\\n    # Check IP-based matching if IP is provided\\n    if ip:\\n        try:\\n            ip_obj = ipaddress.ip_address(ip)\\n\\n            # Check exact IP match\\n            if ip in allowed_hosts:\\n                return True\\n\\n            # Check CIDR range match\\n            for allowed in allowed_hosts:\\n                try:\\n                    # Try to parse as CIDR network\\n                    if \\\"/\\\" in allowed:\\n                        network = ipaddress.ip_network(allowed, strict=False)\\n                        if ip_obj in network:\\n                            return True\\n                except (ValueError, ipaddress.AddressValueError):\\n                    # Not a valid CIDR, skip\\n                    continue\\n\\n        except (ValueError, ipaddress.AddressValueError):\\n            # Invalid IP, skip IP-based checks\\n            pass\\n\\n    return False\\n\\n\\n# Transition prefixes that embed an IPv4 target. Their embedded IPv4 is re-checked against the\\n# blocklist (below) rather than blocking the whole prefix, which would cut off legitimate public\\n# egress on IPv6-only / DNS64 networks (where public IPv4 services are reached via 64:ff9b::/96).\\n_SIXTO4_PREFIX = ipaddress.ip_network(\\\"2002::/16\\\")\\n_NAT64_WELL_KNOWN_PREFIX = ipaddress.ip_network(\\\"64:ff9b::/96\\\")\\n\\n\\ndef _embedded_ipv4(ip_obj: ipaddress.IPv6Address) -> ipaddress.IPv4Address | None:\\n    \\\"\\\"\\\"Return the IPv4 embedded in a 6to4 or well-known NAT64 address, else None.\\n\\n    6to4 (RFC 3056) carries the IPv4 in bytes 2-5 (``2002:AABB:CCDD::/48`` -> ``AA.BB.CC.DD``); the\\n    NAT64 well-known ``64:ff9b::/96`` (RFC 6052) carries it in the low 32 bits. Local-use NAT64\\n    (``64:ff9b:1::/48``, RFC 8215) uses a deployment-chosen prefix length, so its embedded IPv4\\n    can't be located reliably and isn't decoded here.\\n    \\\"\\\"\\\"\\n    if ip_obj in _SIXTO4_PREFIX:\\n        return ipaddress.IPv4Address(ip_obj.packed[2:6])\\n    if ip_obj in _NAT64_WELL_KNOWN_PREFIX:\\n        return ipaddress.IPv4Address(ip_obj.packed[12:16])\\n    return None\\n\\n\\ndef is_ip_blocked(ip: str | ipaddress.IPv4Address | ipaddress.IPv6Address) -> bool:\\n    \\\"\\\"\\\"Check if an IP address is in a blocked range.\\n\\n    Args:\\n        ip: IP address to check (string or ipaddress object)\\n\\n    Returns:\\n        bool: True if IP is in a blocked range, False otherwise.\\n    \\\"\\\"\\\"\\n    try:\\n        ip_obj = ipaddress.ip_address(ip) if isinstance(ip, str) else ip\\n    except (ValueError, ipaddress.AddressValueError):\\n        # If we can't parse the IP, treat it as blocked for safety\\n        return True\\n\\n    # Check against all blocked ranges\\n    if any(ip_obj in blocked_range for blocked_range in get_blocked_ip_ranges()):\\n        return True\\n\\n    # A 6to4 / NAT64 address is only as safe as the IPv4 it encodes: re-check the embedded IPv4\\n    # so a transition prefix can't reach a blocked target, while a public IPv4 target (the\\n    # legitimate NAT64/6to4 case) still passes.\\n    if isinstance(ip_obj, ipaddress.IPv6Address):\\n        embedded = _embedded_ipv4(ip_obj)\\n        if embedded is not None:\\n            return is_ip_blocked(embedded)\\n\\n    return False\\n\\n\\ndef resolve_hostname(hostname: str) -> list[str]:\\n    \\\"\\\"\\\"Resolve a hostname to its IP addresses.\\n\\n    Args:\\n        hostname: Hostname to resolve\\n\\n    Returns:\\n        list[str]: List of resolved IP addresses\\n\\n    Raises:\\n        SSRFProtectionError: If hostname cannot be resolved\\n    \\\"\\\"\\\"\\n    try:\\n        # Get address info for both IPv4 and IPv6\\n        addr_info = socket.getaddrinfo(hostname, None)\\n\\n        # Extract unique IP addresses\\n        ips = []\\n        for info in addr_info:\\n            ip = info[4][0]\\n            # Remove IPv6 zone ID if present (e.g., \\\"fe80::1%eth0\\\" -> \\\"fe80::1\\\")\\n            if \\\"%\\\" in ip:\\n                ip = ip.split(\\\"%\\\")[0]\\n            if ip not in ips:\\n                ips.append(ip)\\n\\n        if not ips:\\n            msg = f\\\"Unable to resolve hostname: {hostname}\\\"\\n            raise SSRFProtectionError(msg)\\n    except socket.gaierror as e:\\n        msg = f\\\"DNS resolution failed for {hostname}: {e}\\\"\\n        raise SSRFProtectionError(msg) from e\\n    except Exception as e:\\n        msg = f\\\"Error resolving hostname {hostname}: {e}\\\"\\n        raise SSRFProtectionError(msg) from e\\n\\n    return ips\\n\\n\\ndef _validate_url_scheme(scheme: str) -> None:\\n    \\\"\\\"\\\"Validate that URL scheme is http or https.\\n\\n    Args:\\n        scheme: URL scheme to validate\\n\\n    Raises:\\n        SSRFProtectionError: If scheme is invalid\\n    \\\"\\\"\\\"\\n    if scheme not in (\\\"http\\\", \\\"https\\\"):\\n        msg = f\\\"Invalid URL scheme '{scheme}'. Only http and https are allowed.\\\"\\n        raise SSRFProtectionError(msg)\\n\\n\\ndef _validate_hostname_exists(hostname: str | None) -> str:\\n    \\\"\\\"\\\"Validate that hostname exists in the URL.\\n\\n    Args:\\n        hostname: Hostname to validate (may be None)\\n\\n    Returns:\\n        str: The validated hostname\\n\\n    Raises:\\n        SSRFProtectionError: If hostname is missing\\n    \\\"\\\"\\\"\\n    if not hostname:\\n        msg = \\\"URL must contain a valid hostname\\\"\\n        raise SSRFProtectionError(msg)\\n    return hostname\\n\\n\\ndef _validate_direct_ip_address(hostname: str) -> bool:\\n    \\\"\\\"\\\"Validate a direct IP address in the URL.\\n\\n    Args:\\n        hostname: Hostname that may be an IP address\\n\\n    Returns:\\n        bool: True if hostname is a direct IP and validation passed,\\n              False if hostname is not an IP (caller should continue with DNS resolution)\\n\\n    Raises:\\n        SSRFProtectionError: If IP is blocked\\n    \\\"\\\"\\\"\\n    try:\\n        ip_obj = ipaddress.ip_address(hostname)\\n    except ValueError:\\n        # Not an IP address, it's a hostname - caller should continue with DNS resolution\\n        return False\\n\\n    # It's a direct IP address\\n    # Check if IP is in allowlist\\n    if is_host_allowed(hostname, str(ip_obj)):\\n        logger.debug(\\\"IP address %s is in allowlist, bypassing SSRF checks\\\", hostname)\\n        return True\\n\\n    if is_ip_blocked(ip_obj):\\n        msg = (\\n            f\\\"Access to IP address {hostname} is blocked by SSRF protection. \\\"\\n            \\\"To allow this IP, add it to LANGFLOW_SSRF_ALLOWED_HOSTS environment variable.\\\"\\n        )\\n        raise SSRFProtectionError(msg)\\n\\n    # Direct IP is allowed (public IP)\\n    return True\\n\\n\\ndef _validate_hostname_resolution(hostname: str) -> None:\\n    \\\"\\\"\\\"Resolve hostname and validate resolved IPs are not blocked.\\n\\n    Args:\\n        hostname: Hostname to resolve and validate\\n\\n    Raises:\\n        SSRFProtectionError: If resolved IPs are blocked\\n    \\\"\\\"\\\"\\n    # Resolve hostname to IP addresses\\n    try:\\n        resolved_ips = resolve_hostname(hostname)\\n    except SSRFProtectionError:\\n        # Re-raise SSRF errors as-is\\n        raise\\n    except Exception as e:\\n        msg = f\\\"Failed to resolve hostname {hostname}: {e}\\\"\\n        raise SSRFProtectionError(msg) from e\\n\\n    # Check if any resolved IP is blocked\\n    blocked_ips = []\\n    for ip in resolved_ips:\\n        # Check if this specific IP is in the allowlist\\n        if is_host_allowed(hostname, ip):\\n            logger.debug(\\\"Resolved IP %s for hostname %s is in allowlist, bypassing SSRF checks\\\", ip, hostname)\\n            return\\n\\n        if is_ip_blocked(ip):\\n            blocked_ips.append(ip)\\n\\n    if blocked_ips:\\n        msg = (\\n            f\\\"Hostname {hostname} resolves to blocked IP address(es): {', '.join(blocked_ips)}. \\\"\\n            \\\"To allow this hostname, add it to LANGFLOW_SSRF_ALLOWED_HOSTS environment variable.\\\"\\n        )\\n        raise SSRFProtectionError(msg)\\n\\n\\ndef _validate_raw_url_authority(url: str) -> None:\\n    \\\"\\\"\\\"Reject authority forms that urllib.parse and HTTP clients interpret differently.\\\"\\\"\\\"\\n    # Requests/urllib3 treats a backslash in the authority as a path separator,\\n    # while urllib.parse can treat the suffix as the hostname. Reject only the\\n    # ambiguous authority form; Requests safely quotes backslashes after it.\\n    raw_authority = re.split(r\\\"[/#?]\\\", url.partition(\\\"://\\\")[2], maxsplit=1)[0]\\n    if \\\"\\\\\\\\\\\" in raw_authority:\\n        msg = \\\"URL contains a backslash, which is not permitted\\\"\\n        raise SSRFProtectionError(msg)\\n\\n\\ndef validate_url_for_ssrf(url: str, *, warn_only: bool = False) -> None:\\n    \\\"\\\"\\\"Validate a URL to prevent SSRF attacks.\\n\\n    This function performs the following checks:\\n    1. Validates the URL scheme (only http/https allowed)\\n    2. Validates hostname exists\\n    3. Checks if hostname/IP is in allowlist\\n    4. If direct IP: validates it's not in blocked ranges\\n    5. If hostname: resolves to IPs and validates they're not in blocked ranges\\n\\n    Args:\\n        url: URL to validate\\n        warn_only: If True, only log warnings instead of raising errors (default: False)\\n\\n    Raises:\\n        SSRFProtectionError: If the URL is blocked due to SSRF protection (only if warn_only=False)\\n        ValueError: If the URL is malformed\\n    \\\"\\\"\\\"\\n    # Skip validation if SSRF protection is disabled\\n    if not is_ssrf_protection_enabled():\\n        return\\n\\n    # Parse URL\\n    try:\\n        parsed = urlparse(url)\\n    except Exception as e:\\n        msg = f\\\"Invalid URL format: {e}\\\"\\n        raise ValueError(msg) from e\\n\\n    try:\\n        _validate_raw_url_authority(url)\\n\\n        # Validate scheme (raises SSRFProtectionError for any non-http/https scheme)\\n        _validate_url_scheme(parsed.scheme)\\n\\n        # Validate hostname exists\\n        hostname = _validate_hostname_exists(parsed.hostname)\\n\\n        # Check if hostname/IP is in allowlist (early return if allowed)\\n        if is_host_allowed(hostname):\\n            logger.debug(\\\"Hostname %s is in allowlist, bypassing SSRF checks\\\", hostname)\\n            return\\n\\n        # Validate direct IP address or resolve hostname\\n        is_direct_ip = _validate_direct_ip_address(hostname)\\n        if is_direct_ip:\\n            # Direct IP was handled (allowed or exception raised)\\n            return\\n\\n        # Not a direct IP, resolve hostname and validate\\n        _validate_hostname_resolution(hostname)\\n    except SSRFProtectionError as e:\\n        if warn_only:\\n            logger.warning(\\\"SSRF Protection Warning: %s [URL: %s]\\\", str(e), url)\\n            logger.warning(\\n                \\\"This request will be blocked when SSRF protection is enforced in the next major version. \\\"\\n                \\\"Please review your API Request components.\\\"\\n            )\\n            return\\n        raise\\n\\n\\ndef is_connector_ssrf_validation_enabled() -> bool:\\n    \\\"\\\"\\\"Whether SSRF validation is enabled for tenant-controlled CONNECTOR host/URL components.\\n\\n    Separate gate from the global ``ssrf_protection_enabled``. Defaults to True so connector\\n    components (vector stores, SQL DBs, Glean/AstraDB-CQL tools, model-provider discovery) follow\\n    the same internal-host policy unless an operator explicitly disables it.\\n    \\\"\\\"\\\"\\n    import os\\n\\n    env_value = os.getenv(\\\"LANGFLOW_CONNECTOR_SSRF_VALIDATION_ENABLED\\\")\\n    if env_value is not None:\\n        return env_value.lower() in (\\\"true\\\", \\\"1\\\", \\\"yes\\\", \\\"on\\\")\\n    try:\\n        return bool(get_settings_service().settings.connector_ssrf_validation_enabled)\\n    except Exception:  # noqa: BLE001 - settings may be unavailable; default to enabled\\n        logger.warning(\\n            \\\"Could not read connector_ssrf_validation_enabled setting; treating connector SSRF \\\"\\n            \\\"validation as ENABLED (fail-closed to default). Connector URLs will be validated.\\\"\\n        )\\n        return True\\n\\n\\ndef is_connector_loopback_allowed() -> bool:\\n    \\\"\\\"\\\"Whether a literal loopback host is allowed for ordinary CONNECTOR URLs.\\n\\n    Connector and model-provider components routinely target a *local* service \u2014 Ollama and\\n    LM Studio default to ``http://localhost:11434`` / ``http://localhost:1234`` and local vector\\n    stores bind to loopback \u2014 so loopback is allowed by default (True). Cloud-metadata and\\n    RFC1918 ranges are blocked regardless. A multi-tenant deployer, where a tenant pointing a\\n    connector at the *server's* loopback is an SSRF vector, sets this to False to block loopback\\n    too. Defaults to True (lenient single-tenant default) if settings are unavailable.\\n    \\\"\\\"\\\"\\n    import os\\n\\n    env_value = os.getenv(\\\"LANGFLOW_CONNECTOR_SSRF_ALLOW_LOOPBACK\\\")\\n    if env_value is not None:\\n        return env_value.lower() in (\\\"true\\\", \\\"1\\\", \\\"yes\\\", \\\"on\\\")\\n    try:\\n        return bool(get_settings_service().settings.connector_ssrf_allow_loopback)\\n    except Exception:  # noqa: BLE001 - settings may be unavailable; default to allowed (single-tenant default)\\n        return True\\n\\n\\ndef _is_loopback_host(hostname: str) -> bool:\\n    \\\"\\\"\\\"True if ``hostname`` is a literal loopback reference (``localhost`` or a loopback IP).\\n\\n    Only literal forms are matched (``localhost``, ``127.0.0.0/8``, ``::1``). A hostname that\\n    merely *resolves* to loopback is intentionally NOT matched, so it still flows through the full\\n    SSRF check \u2014 defeating a DNS-rebinding trick that points a public-looking host at loopback.\\n    \\\"\\\"\\\"\\n    if hostname.lower() == \\\"localhost\\\":\\n        return True\\n    try:\\n        return ipaddress.ip_address(hostname).is_loopback\\n    except ValueError:\\n        return False\\n\\n\\ndef _connector_url_has_loopback_exemption(url: str) -> bool:\\n    \\\"\\\"\\\"Validate connector URL shape and return whether its literal host is exempt.\\\"\\\"\\\"\\n    if not is_ssrf_protection_enabled():\\n        return False\\n\\n    _validate_raw_url_authority(url)\\n    parsed = urlparse(url)\\n    if parsed.scheme not in (\\\"http\\\", \\\"https\\\") or not parsed.hostname:\\n        msg = (\\n            f\\\"Connector URL must be an http(s) URL with a host for SSRF validation; got {url!r}. \\\"\\n            \\\"Use an explicit scheme (e.g. 'http://host:port'); to reach an internal host, also add \\\"\\n            \\\"it to LANGFLOW_SSRF_ALLOWED_HOSTS (allowlisting alone does not permit a scheme-less host).\\\"\\n        )\\n        raise SSRFProtectionError(msg)\\n\\n    return is_connector_loopback_allowed() and _is_loopback_host(parsed.hostname)\\n\\n\\ndef validate_connector_url_for_ssrf(url: str) -> None:\\n    \\\"\\\"\\\"SSRF-validate a tenant-controlled connector URL unless connector validation is disabled.\\n\\n    Defers to :func:`validate_url_for_ssrf`, which still respects ``ssrf_protection_enabled`` and\\n    the allowlist, for the actual host policy. Operators can set\\n    ``connector_ssrf_validation_enabled=false`` to preserve legacy localhost/private-network\\n    connector behavior.\\n\\n    DNS-rebinding residual: unlike the API Request component (which uses\\n    :func:`validate_and_resolve_url` to pin the validated IP), connectors hand the URL to a\\n    third-party client (chromadb, pymilvus, qdrant-client, SQLAlchemy, the ollama client, ...)\\n    that re-resolves DNS at connect time and exposes no hook to dial a pre-resolved IP without\\n    breaking TLS SNI / cert validation. So this guard is validate-then-connect and a\\n    TOCTOU/DNS-rebinding attacker with a fast-flipping record could still slip an internal IP\\n    past it. The high-value targets (cloud metadata, RFC1918 literals) are literal IPs with no\\n    DNS to rebind and are blocked identically here.\\n\\n    Raises:\\n        SSRFProtectionError: If connector validation is enabled and the host is blocked, or the\\n            URL is not an http(s) URL with a host (the only shape this guard can validate).\\n    \\\"\\\"\\\"\\n    if not is_connector_ssrf_validation_enabled():\\n        return\\n    # Connectors commonly target a local service (Ollama / LM Studio default to localhost,\\n    # local vector stores bind to loopback). Allow a literal loopback host by default; a\\n    # multi-tenant deployer sets connector_ssrf_allow_loopback=false to block it too. Only a\\n    # literal loopback reference is exempted \u2014 a hostname that resolves to loopback still goes\\n    # through the full check below, so DNS-rebinding cannot abuse this.\\n    if _connector_url_has_loopback_exemption(url):\\n        return\\n    validate_url_for_ssrf(url)\\n\\n\\ndef validate_and_resolve_connector_url(url: str) -> tuple[str, list[str]]:\\n    \\\"\\\"\\\"Validate a connector URL and return IPs for DNS-pinned HTTP clients.\\n\\n    This applies the same connector policy as :func:`validate_connector_url_for_ssrf`, including\\n    the literal-loopback exemption, while retaining DNS pinning for non-exempt hosts used by HTTP\\n    connector clients.\\n\\n    Args:\\n        url: Connector URL to validate.\\n\\n    Returns:\\n        The original URL and validated IP addresses. The IP list is empty when connector\\n        validation is disabled, global SSRF protection is disabled, the host is allowlisted, or\\n        the literal-loopback exemption applies.\\n\\n    Raises:\\n        SSRFProtectionError: If connector validation is enabled and the URL is blocked or malformed.\\n        ValueError: If the URL format is invalid.\\n    \\\"\\\"\\\"\\n    if not is_connector_ssrf_validation_enabled() or _connector_url_has_loopback_exemption(url):\\n        return url, []\\n    return validate_and_resolve_url(url)\\n\\n\\n# SQLAlchemy dialects that read/write the local filesystem instead of connecting over the\\n# network. A multi-tenant deployer must never let a tenant-supplied DB URL open these\\n# (e.g. sqlite:////etc/passwd, or ATTACH to read/write arbitrary server files).\\n_LOCAL_FILE_DB_DIALECTS = frozenset({\\\"sqlite\\\", \\\"duckdb\\\", \\\"access\\\", \\\"shell\\\"})\\n\\n# SQLAlchemy merges URL query parameters into DBAPI connection arguments after\\n# parsing the authority. These keys can replace the validated network target or\\n# select a local transport, so tenant-controlled URLs must not supply them.\\n_DATABASE_CONNECTION_TARGET_QUERY_KEYS = frozenset(\\n    {\\n        \\\"addr\\\",\\n        \\\"address\\\",\\n        \\\"data source\\\",\\n        \\\"dsn\\\",\\n        \\\"failover_partner\\\",\\n        \\\"filedsn\\\",\\n        \\\"host\\\",\\n        \\\"hostaddr\\\",\\n        \\\"network address\\\",\\n        \\\"odbc_connect\\\",\\n        \\\"port\\\",\\n        \\\"server\\\",\\n        \\\"unix_socket\\\",\\n    }\\n)\\n\\n_DATABASE_LOCAL_FILE_QUERY_KEYS = frozenset(\\n    {\\n        \\\"clientcertificate\\\",\\n        \\\"clientkey\\\",\\n        \\\"dsn\\\",\\n        \\\"filedsn\\\",\\n        \\\"odbc_connect\\\",\\n        \\\"querylogfile\\\",\\n        \\\"savefile\\\",\\n        \\\"servercertificate\\\",\\n        \\\"statslogfile\\\",\\n    }\\n)\\n\\n# ODBC drivers accept extensible connection-string attributes. Once either SSRF\\n# or local-file policy is active, pass through only documented non-target,\\n# non-file options; unknown attributes may be aliases defined by another driver.\\n_SAFE_ODBC_QUERY_KEYS = frozenset(\\n    {\\n        \\\"ansi\\\",\\n        \\\"ansinpw\\\",\\n        \\\"app\\\",\\n        \\\"application name\\\",\\n        \\\"applicationintent\\\",\\n        \\\"authentication\\\",\\n        \\\"autocommit\\\",\\n        \\\"autotranslate\\\",\\n        \\\"charset\\\",\\n        \\\"clientcertificate\\\",\\n        \\\"columnencryption\\\",\\n        \\\"concatnullyieldsnull\\\",\\n        \\\"connectretrycount\\\",\\n        \\\"connectretryinterval\\\",\\n        \\\"database\\\",\\n        \\\"description\\\",\\n        \\\"driver\\\",\\n        \\\"encrypt\\\",\\n        \\\"failoverpartnerspn\\\",\\n        \\\"getdataextensions\\\",\\n        \\\"hostnameincertificate\\\",\\n        \\\"ipaddresspreference\\\",\\n        \\\"keepalive\\\",\\n        \\\"keepaliveinterval\\\",\\n        \\\"keystoreauthentication\\\",\\n        \\\"keystoreprincipalid\\\",\\n        \\\"keystoresecret\\\",\\n        \\\"language\\\",\\n        \\\"longasmax\\\",\\n        \\\"mars_connection\\\",\\n        \\\"multisubnetfailover\\\",\\n        \\\"net\\\",\\n        \\\"network\\\",\\n        \\\"odbc_autotranslate\\\",\\n        \\\"pwd\\\",\\n        \\\"querylog_on\\\",\\n        \\\"querylogtime\\\",\\n        \\\"quotedid\\\",\\n        \\\"readonly\\\",\\n        \\\"regional\\\",\\n        \\\"replication\\\",\\n        \\\"retryexec\\\",\\n        \\\"serverspn\\\",\\n        \\\"sslmode\\\",\\n        \\\"statslog_on\\\",\\n        \\\"timeout\\\",\\n        \\\"transparentnetworkipresolution\\\",\\n        \\\"trusted_connection\\\",\\n        \\\"trustservercertificate\\\",\\n        \\\"uid\\\",\\n        \\\"unicode_results\\\",\\n        \\\"usefmtonly\\\",\\n        \\\"user\\\",\\n        \\\"wsid\\\",\\n    }\\n)\\n\\n\\ndef validate_database_url_for_ssrf(url: str, *, validate_network_host: bool = True) -> None:\\n    \\\"\\\"\\\"Validate a SQLAlchemy database URL against SSRF and local-file access.\\n\\n    Unlike :func:`validate_url_for_ssrf` (which only guards http/https and returns early for\\n    other schemes), this guards arbitrary DB URIs on two axes, each with its own toggle:\\n\\n    * Network dialects (postgresql, mysql, ...) must resolve to a host that is not an\\n      internal/blocked IP \u2014 guarded by SSRF protection (``LANGFLOW_SSRF_PROTECTION_ENABLED``,\\n      default on), so a tenant cannot reach the control-plane DB or other internal services.\\n    * Local-file-backed dialects (sqlite, duckdb, ...) read/write the server filesystem and\\n      are blocked only when ``LANGFLOW_RESTRICT_LOCAL_FILE_ACCESS`` is on (default off), so\\n      single-tenant sqlite usage keeps working while multi-tenant deployments can disable it.\\n\\n    Args:\\n        url: The SQLAlchemy database URL to validate.\\n        validate_network_host: When False, the network-host SSRF check is skipped (the local-file\\n            dialect restriction still applies). Used by the connector-gated wrapper so the\\n            host SSRF check is opt-in.\\n\\n    Raises:\\n        SSRFProtectionError: If the URL targets a blocked IP, or a local-file dialect while\\n            local file access is restricted.\\n        ValueError: If the URL is malformed.\\n    \\\"\\\"\\\"\\n    ssrf_on = is_ssrf_protection_enabled() and validate_network_host\\n    file_restricted = is_local_file_access_restricted()\\n    if not ssrf_on and not file_restricted:\\n        return\\n\\n    try:\\n        parsed = urlparse(url)\\n    except Exception as e:\\n        msg = f\\\"Invalid database URL format: {e}\\\"\\n        raise ValueError(msg) from e\\n\\n    # SQLAlchemy schemes look like \\\"postgresql+psycopg2\\\"; separate dialect and driver.\\n    dialect, _separator, driver = (parsed.scheme or \\\"\\\").lower().partition(\\\"+\\\")\\n    if dialect in _LOCAL_FILE_DB_DIALECTS:\\n        if file_restricted:\\n            msg = (\\n                f\\\"Database dialect '{dialect}' accesses the local filesystem and is not permitted \\\"\\n                \\\"(LANGFLOW_RESTRICT_LOCAL_FILE_ACCESS=true). Use a network database (e.g. postgresql, mysql).\\\"\\n            )\\n            raise SSRFProtectionError(msg)\\n        # Not restricted: local-file DBs are allowed (single-tenant default).\\n        return\\n\\n    query_items = parse_qsl(parsed.query, keep_blank_values=True)\\n    query_keys = {key.casefold() for key, _value in query_items}\\n\\n    # SQLAlchemy's ODBC connector serializes arbitrary query keys directly into\\n    # the connection string, and ODBC drivers may define their own aliases.\\n    is_odbc = \\\"odbc\\\" in driver or dialect.endswith(\\\"odbc\\\") or (dialect == \\\"mssql\\\" and not driver)\\n\\n    local_file_options = sorted(\\n        {\\n            key.casefold()\\n            for key, value in query_items\\n            if key.casefold() in _DATABASE_LOCAL_FILE_QUERY_KEYS\\n            and (key.casefold() != \\\"clientcertificate\\\" or value.casefold().startswith(\\\"file:\\\"))\\n        }\\n    )\\n    if file_restricted and local_file_options:\\n        keys = \\\", \\\".join(local_file_options)\\n        msg = f\\\"Database URL query key(s) {keys} can access the local filesystem and are not permitted.\\\"\\n        raise SSRFProtectionError(msg)\\n\\n    if ssrf_on:\\n        hostname = parsed.hostname\\n        if not hostname:\\n            # A network dialect with no host cannot be validated -> fail closed.\\n            msg = \\\"Database URL must contain a network host.\\\"\\n            raise SSRFProtectionError(msg)\\n\\n        target_overrides = sorted(query_keys & _DATABASE_CONNECTION_TARGET_QUERY_KEYS)\\n        if target_overrides:\\n            keys = \\\", \\\".join(target_overrides)\\n            msg = f\\\"Database URL query key(s) {keys} cannot override the validated connection target.\\\"\\n            raise SSRFProtectionError(msg)\\n\\n    if is_odbc and (ssrf_on or file_restricted):\\n        allowed_odbc_keys = set(_SAFE_ODBC_QUERY_KEYS)\\n        if not ssrf_on:\\n            allowed_odbc_keys.update(_DATABASE_CONNECTION_TARGET_QUERY_KEYS)\\n        if not file_restricted:\\n            allowed_odbc_keys.update(_DATABASE_LOCAL_FILE_QUERY_KEYS)\\n        unsupported_keys = query_keys - allowed_odbc_keys\\n        if unsupported_keys:\\n            msg = \\\"Database URL contains an unsupported ODBC query key.\\\"\\n            raise SSRFProtectionError(msg)\\n\\n    # Network dialect: host SSRF validation only applies when SSRF protection is enabled.\\n    if not ssrf_on:\\n        return\\n\\n    # Reuse the same allowlist + blocked-range checks as HTTP SSRF validation.\\n    if _validate_direct_ip_address(hostname):\\n        return\\n    _validate_hostname_resolution(hostname)\\n\\n\\ndef validate_connector_database_url_for_ssrf(url: str) -> None:\\n    \\\"\\\"\\\"DB-URL validation for connector components (e.g. the SQL Database components).\\n\\n    The network-host SSRF check follows ``connector_ssrf_validation_enabled`` (default on). The\\n    local-file dialect restriction still honors ``LANGFLOW_RESTRICT_LOCAL_FILE_ACCESS`` regardless,\\n    since that is a separate control.\\n\\n    Raises:\\n        SSRFProtectionError: If connector validation is on and the host is blocked, or a local-file\\n            dialect is used while local file access is restricted.\\n        ValueError: If the URL is malformed.\\n    \\\"\\\"\\\"\\n    validate_database_url_for_ssrf(url, validate_network_host=is_connector_ssrf_validation_enabled())\\n\\n\\n# Git remote-helper transport syntax (``ext::``, ``fd::``, bare ``::address``). The ``ext``\\n# helper runs an arbitrary shell command, so this whole syntax is treated as hostile.\\n_GIT_REMOTE_HELPER_RE = re.compile(r\\\"^[A-Za-z0-9+.\\\\-]*::\\\")\\n\\n# Real network transports git understands. Anything else (file, ext, fd, ...) is rejected.\\n_ALLOWED_GIT_SCHEMES = frozenset({\\\"http\\\", \\\"https\\\", \\\"git\\\", \\\"ssh\\\", \\\"git+ssh\\\", \\\"git+http\\\", \\\"git+https\\\"})\\n\\n\\ndef validate_git_repository_url(url: str) -> None:\\n    \\\"\\\"\\\"Validate a Git repository URL before it is handed to ``git clone``.\\n\\n    ``git``/GitPython accept far more than network URLs, and the repository URL is fully\\n    tenant-controlled in a multi-tenant deployment:\\n\\n    * ``ext::sh -c '<cmd>'`` (and any ``<helper>::`` remote-helper transport) executes an\\n      arbitrary command on the server => RCE.\\n    * a leading ``-`` is parsed by git as an option => argument injection.\\n    * ``file://`` and bare local paths clone a repository off the server filesystem =>\\n      arbitrary local file disclosure.\\n\\n    The first two are always blocked (no legitimate use, direct RCE/injection). Local-file\\n    clones are blocked when SSRF protection (default on) or local-file restriction is enabled,\\n    so single-tenant local-repo workflows keep working only when both are off. Network\\n    transports have their host validated against the SSRF blocked ranges.\\n\\n    Raises:\\n        SSRFProtectionError: If the URL uses a dangerous transport or targets a blocked host.\\n        ValueError: If the URL is empty or malformed.\\n    \\\"\\\"\\\"\\n    if not isinstance(url, str) or not url.strip():\\n        msg = \\\"Git repository URL must be a non-empty string.\\\"\\n        raise ValueError(msg)\\n    url = url.strip()\\n\\n    # Always-blocked: remote-helper transports (RCE) and git option injection. These are\\n    # rejected regardless of SSRF/file-access toggles because they have no legitimate use.\\n    if url.startswith(\\\"-\\\"):\\n        msg = \\\"Git repository URL may not start with '-' (git option injection).\\\"\\n        raise SSRFProtectionError(msg)\\n    if _GIT_REMOTE_HELPER_RE.match(url):\\n        msg = \\\"Git remote-helper transports (e.g. 'ext::', 'fd::') are not permitted.\\\"\\n        raise SSRFProtectionError(msg)\\n\\n    parsed = urlparse(url)\\n    scheme = (parsed.scheme or \\\"\\\").lower()\\n\\n    # Scheme allowlist is ALWAYS enforced (independent of the SSRF/file toggles): non-network\\n    # schemes such as ``ext://`` invoke the git-remote-<scheme> helper (RCE) and ``gopher://``\\n    # etc. are dangerous transports, not a network-policy choice. ``file`` is handled just below.\\n    if scheme and scheme != \\\"file\\\" and scheme not in _ALLOWED_GIT_SCHEMES:\\n        msg = f\\\"Git URL scheme '{scheme}' is not permitted.\\\"\\n        raise SSRFProtectionError(msg)\\n\\n    # Local-filesystem clones (file:// or a bare path) read arbitrary server files.\\n    pre_colon = url.split(\\\":\\\", 1)[0]\\n    is_local_path = scheme == \\\"file\\\" or (scheme == \\\"\\\" and (\\\"/\\\" in pre_colon or url.startswith((\\\"/\\\", \\\".\\\", \\\"~\\\"))))\\n    if is_local_path:\\n        if is_ssrf_protection_enabled() or is_local_file_access_restricted():\\n            msg = \\\"Cloning local-filesystem Git repositories is not permitted.\\\"\\n            raise SSRFProtectionError(msg)\\n        return\\n\\n    # Network transports: host SSRF validation only applies when SSRF protection is enabled.\\n    if not is_ssrf_protection_enabled():\\n        return\\n\\n    # scp-like syntax (git@host:path) has no scheme; the host is before the first ':'.\\n    hostname = (url.split(\\\"@\\\", 1)[-1].split(\\\":\\\", 1)[0] or None) if scheme == \\\"\\\" else parsed.hostname\\n\\n    if not hostname:\\n        msg = \\\"Git repository URL must contain a network host.\\\"\\n        raise SSRFProtectionError(msg)\\n\\n    if _validate_direct_ip_address(hostname):\\n        return\\n    _validate_hostname_resolution(hostname)\\n\\n\\ndef validate_and_resolve_url(url: str) -> tuple[str, list[str]]:\\n    \\\"\\\"\\\"Validate URL for SSRF and return validated IP addresses for DNS pinning.\\n\\n    This function is the core of DNS pinning-based SSRF protection. It performs\\n    comprehensive validation and returns the validated IP addresses that should\\n    be used for the actual HTTP request, preventing DNS rebinding attacks.\\n\\n    DNS Rebinding Attack Prevention:\\n        Without DNS pinning, an attacker can exploit the time gap between validation\\n        and the actual HTTP request:\\n        1. Validation: DNS returns public IP (8.8.8.8) \u2192 passes security check\\n        2. [Attacker changes DNS with TTL=0]\\n        3. HTTP request: DNS returns internal IP (127.0.0.1) \u2192 bypasses protection\\n\\n        With DNS pinning (this function):\\n        1. Validation: DNS returns public IP (8.8.8.8) \u2192 passes security check\\n        2. Function returns: (url, ['8.8.8.8']) \u2192 IP is pinned\\n        3. HTTP request: Uses pinned IP directly \u2192 no new DNS lookup \u2192 secure\\n\\n    Args:\\n        url: URL to validate (e.g., \\\"http://example.com/api\\\")\\n\\n    Returns:\\n        Tuple of (original_url, list_of_validated_ips):\\n        - original_url: The input URL unchanged\\n        - list_of_validated_ips: List of validated IP addresses to use for DNS pinning\\n          Returns empty list if:\\n          - SSRF protection is disabled\\n          - Host is in the allowlist (e.g., localhost for Ollama)\\n          (a non-http/https scheme raises SSRFProtectionError rather than returning)\\n\\n    Raises:\\n        SSRFProtectionError: If URL is blocked by SSRF protection\\n        ValueError: If URL format is invalid\\n\\n    Example:\\n        >>> # Public domain - returns validated IPs for pinning\\n        >>> url, ips = validate_and_resolve_url(\\\"http://example.com\\\")\\n        >>> print(ips)  # ['93.184.216.34']\\n\\n        >>> # Localhost (if in allowlist) - returns empty list (no pinning needed)\\n        >>> url, ips = validate_and_resolve_url(\\\"http://localhost:8080\\\")\\n        >>> print(ips)  # []\\n\\n        >>> # Private IP - raises SSRFProtectionError\\n        >>> url, ips = validate_and_resolve_url(\\\"http://192.168.1.1\\\")\\n        # Raises: SSRFProtectionError(\\\"Access to IP address 192.168.1.1 is blocked...\\\")\\n    \\\"\\\"\\\"\\n    # ============================================================================\\n    # Step 1: Check if SSRF protection is enabled\\n    # ============================================================================\\n    if not is_ssrf_protection_enabled():\\n        # Protection is disabled - return empty list (no DNS pinning)\\n        return url, []\\n\\n    # ============================================================================\\n    # Step 2: Parse and validate URL format\\n    # ============================================================================\\n    try:\\n        parsed = urlparse(url)\\n    except Exception as e:\\n        msg = f\\\"Invalid URL format: {e}\\\"\\n        raise ValueError(msg) from e\\n\\n    try:\\n        _validate_raw_url_authority(url)\\n\\n        # ============================================================================\\n        # Step 3: Validate URL scheme (raises SSRFProtectionError for any non-http/https scheme)\\n        # ============================================================================\\n        _validate_url_scheme(parsed.scheme)\\n\\n        # ============================================================================\\n        # Step 4: Extract and validate hostname\\n        # ============================================================================\\n        hostname = _validate_hostname_exists(parsed.hostname)\\n\\n        # ============================================================================\\n        # Step 5: Check allowlist (early return for trusted hosts)\\n        # ============================================================================\\n        # Allowlisted hosts bypass all SSRF checks and DNS pinning\\n        # This is used for legitimate internal services like Ollama (localhost)\\n        if is_host_allowed(hostname):\\n            logger.debug(f\\\"Hostname {hostname} is in allowlist, bypassing SSRF checks and DNS pinning\\\")\\n            return url, []\\n\\n        # ============================================================================\\n        # Step 6: Handle direct IP addresses\\n        # ============================================================================\\n        # Check if the hostname is already an IP address (no DNS resolution needed)\\n        try:\\n            ip_obj = ipaddress.ip_address(hostname)\\n\\n            # Check if this specific IP is in the allowlist\\n            if is_host_allowed(hostname, str(ip_obj)):\\n                logger.debug(f\\\"IP {hostname} is in allowlist\\\")\\n                return url, []\\n\\n            # Check if IP is in blocked ranges (private IPs, localhost, etc.)\\n            if is_ip_blocked(ip_obj):\\n                msg = (\\n                    f\\\"Access to IP address {hostname} is blocked by SSRF protection. \\\"\\n                    \\\"To allow this IP, add it to LANGFLOW_SSRF_ALLOWED_HOSTS environment variable.\\\"\\n                )\\n                raise SSRFProtectionError(msg)\\n            # Direct IP is public and allowed - return it for DNS pinning\\n            # (Even though it's already an IP, we return it for consistency)\\n            logger.debug(f\\\"Direct IP {hostname} validated, will use for DNS pinning\\\")\\n            return url, [hostname]  # noqa: TRY300\\n\\n        except ValueError:\\n            # Not an IP address, it's a hostname - continue to DNS resolution\\n            pass\\n\\n        # ============================================================================\\n        # Step 7: Resolve hostname to IP addresses\\n        # ============================================================================\\n        # This is the critical step for DNS pinning - we resolve DNS here during\\n        # validation, and the returned IPs will be used for the actual HTTP request\\n        resolved_ips = resolve_hostname(hostname)\\n        blocked_ips = []\\n\\n        # ============================================================================\\n        # Step 8: Validate all resolved IPs\\n        # ============================================================================\\n        # Security: We must check ALL resolved IPs before making any decisions.\\n        # A hostname might resolve to multiple IPs (e.g., [8.8.8.8, 192.168.1.1]).\\n        # If we return early on the first allowlisted IP, we skip validation of\\n        # remaining IPs, which could include blocked/internal addresses.\\n        #\\n        # Strategy:\\n        # 1. Collect all allowlisted IPs and all blocked IPs\\n        # 2. If ANY IP is blocked \u2192 block the entire hostname (security first)\\n        # 3. If some IPs are allowlisted but others are not \u2192 use only allowlisted IPs for pinning\\n        # 4. If all IPs are public (none blocked, none allowlisted) \u2192 use all for pinning\\n        allowed_ips = []\\n        for ip in resolved_ips:\\n            # Check if this resolved IP is in the allowlist\\n            if is_host_allowed(hostname, ip):\\n                allowed_ips.append(ip)\\n            # Check if IP is in blocked ranges\\n            elif is_ip_blocked(ip):\\n                blocked_ips.append(ip)\\n\\n        # ============================================================================\\n        # Step 9: Block if any resolved IPs are private/internal\\n        # ============================================================================\\n        # Security: If ANY resolved IP is blocked, we block the entire hostname.\\n        # This prevents attacks where a hostname resolves to both safe and unsafe IPs.\\n        if blocked_ips:\\n            msg = (\\n                f\\\"Hostname {hostname} resolves to blocked IP address(es): {', '.join(blocked_ips)}. \\\"\\n                \\\"To allow this hostname, add it to LANGFLOW_SSRF_ALLOWED_HOSTS environment variable.\\\"\\n            )\\n            raise SSRFProtectionError(msg)\\n\\n        # ============================================================================\\n        # Step 9b: Handle partially allowlisted IPs\\n        # ============================================================================\\n        # If some (but not all) IPs are allowlisted, use only the allowlisted ones for pinning\\n        if allowed_ips:\\n            logger.debug(\\n                f\\\"Hostname {hostname} has {len(allowed_ips)} allowlisted IP(s) out of {len(resolved_ips)} total. \\\"\\n                f\\\"Using allowlisted IPs for DNS pinning: {allowed_ips}\\\"\\n            )\\n            return url, allowed_ips\\n        # ============================================================================\\n        # Step 10: Return validated IPs for DNS pinning\\n        # ============================================================================\\n        # All IPs are public and safe - return them for DNS pinning\\n        # The HTTP client will use these IPs directly, preventing DNS rebinding\\n        logger.debug(f\\\"Hostname {hostname} validated, resolved to {resolved_ips}, will use for DNS pinning\\\")\\n        return url, resolved_ips  # noqa: TRY300\\n\\n    except SSRFProtectionError:\\n        # Re-raise SSRF errors as-is\\n        raise\\n    except Exception as e:\\n        # Wrap unexpected errors in SSRFProtectionError\\n        msg = f\\\"Error validating URL: {e}\\\"\\n        raise SSRFProtectionError(msg) from e\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/utils/ssrf_requests.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"d40422b32a2fc47047287fa2a6540c6aa01ed0f03d6fda3f815d4619761daa7c\",\"content\":\"\\\"\\\"\\\"SSRF-protected helpers for the synchronous ``requests`` library.\\n\\nThe httpx-based components (``api_request``, ``url``) route user-controlled URLs\\nthrough SSRF validation. Components built on the synchronous ``requests`` library\\nneed the same protection. This module provides a drop-in ``requests.get`` wrapper\\nthat validates the initial URL and re-validates every redirect hop, so a public URL\\ncannot reach internal services either directly or by redirecting to them.\\n\\n``requests.get`` follows redirects by default, so validating only the initial URL is\\ninsufficient: a public URL could redirect to ``http://169.254.169.254/`` (cloud\\nmetadata), loopback, or an RFC1918 address. ``ssrf_safe_get`` disables automatic\\nredirects and re-applies :func:`validate_url_for_ssrf` to each ``Location`` before\\nfollowing it. All validation is a no-op when SSRF protection is disabled, so behavior\\nis unchanged for operators who have not enabled it.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom urllib.parse import urljoin, urlparse\\n\\nimport requests\\n\\nfrom lfx.utils.ssrf_protection import SSRFProtectionError, validate_url_for_ssrf\\n\\n# HTTP status codes that represent a redirect carrying a Location header (RFC 9110).\\nREDIRECT_STATUS_CODES = frozenset({301, 302, 303, 307, 308})\\n\\n# Maximum number of redirects to follow before failing (matches requests' default).\\nDEFAULT_MAX_REDIRECTS = 30\\n\\n# Credential-bearing headers that must not be forwarded to a different host on a\\n# redirect. ``requests`` strips these in ``Session.rebuild_auth``/``rebuild_proxies``\\n# when it follows redirects itself; because we follow redirects manually with\\n# ``allow_redirects=False`` we must reproduce that protection. Compared lowercase.\\nSENSITIVE_REDIRECT_HEADERS = frozenset({\\\"authorization\\\", \\\"cookie\\\", \\\"proxy-authorization\\\"})\\n\\n\\ndef ssrf_safe_get(\\n    url: str,\\n    *,\\n    timeout: float | tuple[float, float],\\n    headers: dict | None = None,\\n    params: dict | None = None,\\n    max_redirects: int = DEFAULT_MAX_REDIRECTS,\\n) -> requests.Response:\\n    \\\"\\\"\\\"Perform a GET request with SSRF validation on the initial URL and every redirect hop.\\n\\n    Automatic redirect following is disabled and handled manually so that each redirect\\n    target is re-validated against the SSRF denylist (private/loopback/link-local ranges,\\n    cloud metadata endpoints, non-http(s) schemes) before a connection is made.\\n\\n    Args:\\n        url: The URL to fetch.\\n        timeout: Timeout passed to ``requests.get`` (seconds, or a (connect, read) tuple).\\n        headers: Optional request headers, forwarded on every hop. Credential-bearing\\n            headers (Authorization, Cookie, Proxy-Authorization) are dropped when a\\n            redirect crosses to a different host, so they are not leaked to an unrelated\\n            origin. The caller's dict is never mutated.\\n        params: Optional query parameters for the initial request only (redirect targets\\n            carry their own query string in the ``Location`` header).\\n        max_redirects: Maximum number of redirects to follow before raising.\\n\\n    Returns:\\n        requests.Response: The final response after following any validated redirects.\\n\\n    Raises:\\n        SSRFProtectionError: If the initial URL or any redirect target is blocked by SSRF\\n            protection, or if the redirect limit is exceeded.\\n        requests.RequestException: For underlying network/HTTP errors (propagated).\\n    \\\"\\\"\\\"\\n    current_url = url\\n    current_params = params\\n    current_headers = headers\\n\\n    for _ in range(max_redirects + 1):\\n        # Validate scheme, resolve the host, and check it against the SSRF denylist.\\n        # No-op when SSRF protection is disabled.\\n        validate_url_for_ssrf(current_url, warn_only=False)\\n\\n        response = requests.get(\\n            current_url,\\n            timeout=timeout,\\n            headers=current_headers,\\n            params=current_params,\\n            # Never let requests auto-follow redirects; each hop is validated above.\\n            allow_redirects=False,\\n        )\\n\\n        location = response.headers.get(\\\"Location\\\")\\n        if response.status_code in REDIRECT_STATUS_CODES and location:\\n            # Resolve relative redirects against the current URL. The redirect target\\n            # carries its own query string, so the initial params are not reused.\\n            previous_url = current_url\\n            current_url = urljoin(current_url, location)\\n            current_params = None\\n            # Drop credential-bearing headers when the redirect crosses to a different\\n            # host, so caller-supplied Authorization/Cookie/Proxy-Authorization are not\\n            # leaked to an unrelated origin. Build a new dict; never mutate the caller's.\\n            if current_headers and urlparse(previous_url).hostname != urlparse(current_url).hostname:\\n                current_headers = {\\n                    name: value\\n                    for name, value in current_headers.items()\\n                    if name.lower() not in SENSITIVE_REDIRECT_HEADERS\\n                }\\n            continue\\n\\n        return response\\n\\n    msg = f\\\"Exceeded the maximum of {max_redirects} redirects while requesting {url}\\\"\\n    raise SSRFProtectionError(msg)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/utils/ssrf_transport.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"47f20355250f0929090e64fb03852138fa26027761b25487d00e32c9286c785d\",\"content\":\"\\\"\\\"\\\"Custom httpx transport with DNS pinning for SSRF protection.\\n\\nThis module provides a custom httpx transport that pins DNS resolution to validated\\nIP addresses, preventing DNS rebinding attacks that could bypass SSRF protection.\\n\\nThe implementation uses a custom AsyncNetworkBackend to intercept TCP connections\\nand connect to the pinned IP address while preserving the original hostname for\\nTLS SNI (Server Name Indication) and certificate verification.\\n\\\"\\\"\\\"\\n\\nimport ssl\\nfrom collections.abc import Iterable\\n\\nimport httpcore\\nimport httpx\\nfrom httpx import URL, Proxy\\nfrom httpx._config import create_ssl_context\\n\\nfrom lfx.logging import logger\\n\\n\\nclass DNSPinningNetworkBackend(httpcore.AsyncNetworkBackend):\\n    \\\"\\\"\\\"Network backend that pins DNS resolution to validated IP addresses.\\n\\n    This backend intercepts TCP connection attempts and redirects them to pinned\\n    IP addresses while preserving the original hostname for TLS SNI and certificate\\n    verification. This prevents DNS rebinding attacks without breaking HTTPS.\\n\\n    How it works:\\n    1. When httpcore tries to connect to a hostname, we intercept the connect_tcp() call\\n    2. If the hostname has a pinned IP, we connect to that IP instead\\n    3. The original hostname is preserved for TLS handshake (SNI) and cert verification\\n    4. This prevents DNS rebinding while maintaining full HTTPS compatibility\\n    \\\"\\\"\\\"\\n\\n    def __init__(self, pinned_ips: dict[str, list[str]], backend: httpcore.AsyncNetworkBackend | None = None):\\n        \\\"\\\"\\\"Initialize the DNS pinning backend.\\n\\n        Args:\\n            pinned_ips: Dictionary mapping hostnames to list of validated IP addresses\\n            backend: Underlying network backend (defaults to AnyIOBackend for asyncio)\\n        \\\"\\\"\\\"\\n        self.pinned_ips = pinned_ips\\n        # Use httpcore's default async backend (AnyIOBackend) if none provided\\n        # This is the public API recommended in httpcore documentation\\n        if backend is None:\\n            backend = httpcore.AnyIOBackend()\\n        self._backend = backend\\n        logger.debug(f\\\"Created DNS pinning network backend with pinned IPs: {pinned_ips}\\\")\\n\\n    async def connect_tcp(\\n        self,\\n        host: str,\\n        port: int,\\n        timeout: float | None = None,\\n        local_address: str | None = None,\\n        socket_options: Iterable[httpcore.SOCKET_OPTION] | None = None,\\n    ) -> httpcore.AsyncNetworkStream:\\n        \\\"\\\"\\\"Connect to TCP socket, using pinned IP if available.\\n\\n        This method intercepts connection attempts and redirects to pinned IPs\\n        while preserving the original hostname for TLS.\\n\\n        Args:\\n            host: Hostname to connect to (may be replaced with pinned IP)\\n            port: Port number\\n            timeout: Connection timeout\\n            local_address: Local address to bind to\\n            socket_options: Socket options\\n\\n        Returns:\\n            Network stream for the connection\\n        \\\"\\\"\\\"\\n        # Check if this hostname has pinned IPs\\n        if host in self.pinned_ips:\\n            pinned_ips = self.pinned_ips[host]\\n\\n            # Security: If host is in pinned_ips but list is empty, fail rather than bypass\\n            if not pinned_ips:\\n                msg = f\\\"DNS pinning: Host {host} is marked for pinning but has no pinned IPs\\\"\\n                logger.error(msg)\\n                raise RuntimeError(msg)\\n\\n            logger.debug(f\\\"DNS pinning: Connecting to pinned IPs {pinned_ips} for hostname {host}\\\")\\n\\n            # Try each pinned IP in order (supports dual-stack and load balancing)\\n            # The TLS layer will still use the original hostname for SNI and cert verification\\n            last_error = None\\n            for pinned_ip in pinned_ips:\\n                try:\\n                    logger.debug(f\\\"DNS pinning: Attempting connection to {pinned_ip}\\\")\\n                    return await self._backend.connect_tcp(\\n                        host=pinned_ip,\\n                        port=port,\\n                        timeout=timeout,\\n                        local_address=local_address,\\n                        socket_options=socket_options,\\n                    )\\n                except (OSError, TimeoutError) as e:\\n                    last_error = e\\n                    logger.debug(f\\\"DNS pinning: Failed to connect to {pinned_ip}: {e}\\\")\\n                    continue\\n\\n            # All pinned IPs failed, raise the last error\\n            # This should never be None since we checked for empty list above\\n            if last_error is None:\\n                msg = f\\\"DNS pinning: All pinned IPs failed for {host} but no error was captured\\\"\\n                raise RuntimeError(msg)\\n            raise last_error\\n\\n        # No pinned IP, use normal connection\\n        return await self._backend.connect_tcp(\\n            host=host,\\n            port=port,\\n            timeout=timeout,\\n            local_address=local_address,\\n            socket_options=socket_options,\\n        )\\n\\n    async def connect_unix_socket(\\n        self,\\n        path: str,\\n        timeout: float | None = None,\\n        socket_options: Iterable[httpcore.SOCKET_OPTION] | None = None,\\n    ) -> httpcore.AsyncNetworkStream:\\n        \\\"\\\"\\\"Connect to Unix socket (pass through to underlying backend).\\\"\\\"\\\"\\n        return await self._backend.connect_unix_socket(\\n            path=path,\\n            timeout=timeout,\\n            socket_options=socket_options,\\n        )\\n\\n    async def sleep(self, seconds: float) -> None:\\n        \\\"\\\"\\\"Sleep for specified duration (pass through to underlying backend).\\\"\\\"\\\"\\n        await self._backend.sleep(seconds)\\n\\n\\nclass DNSPinningSyncNetworkBackend(httpcore.NetworkBackend):\\n    \\\"\\\"\\\"Synchronous network backend that pins DNS resolution to validated IP addresses.\\\"\\\"\\\"\\n\\n    def __init__(self, pinned_ips: dict[str, list[str]], backend: httpcore.NetworkBackend | None = None):\\n        self.pinned_ips = pinned_ips\\n        if backend is None:\\n            backend = httpcore.SyncBackend()\\n        self._backend = backend\\n        logger.debug(f\\\"Created sync DNS pinning network backend with pinned IPs: {pinned_ips}\\\")\\n\\n    def connect_tcp(\\n        self,\\n        host: str,\\n        port: int,\\n        timeout: float | None = None,\\n        local_address: str | None = None,\\n        socket_options: Iterable[httpcore.SOCKET_OPTION] | None = None,\\n    ) -> httpcore.NetworkStream:\\n        \\\"\\\"\\\"Connect to TCP socket, using pinned IPs for hosts that were validated.\\\"\\\"\\\"\\n        if host in self.pinned_ips:\\n            pinned_ips = self.pinned_ips[host]\\n\\n            if not pinned_ips:\\n                msg = f\\\"DNS pinning: Host {host} is marked for pinning but has no pinned IPs\\\"\\n                logger.error(msg)\\n                raise RuntimeError(msg)\\n\\n            logger.debug(f\\\"DNS pinning: Connecting to pinned IPs {pinned_ips} for hostname {host}\\\")\\n\\n            last_error = None\\n            for pinned_ip in pinned_ips:\\n                try:\\n                    logger.debug(f\\\"DNS pinning: Attempting connection to {pinned_ip}\\\")\\n                    return self._backend.connect_tcp(\\n                        host=pinned_ip,\\n                        port=port,\\n                        timeout=timeout,\\n                        local_address=local_address,\\n                        socket_options=socket_options,\\n                    )\\n                except (OSError, TimeoutError) as e:\\n                    last_error = e\\n                    logger.debug(f\\\"DNS pinning: Failed to connect to {pinned_ip}: {e}\\\")\\n                    continue\\n\\n            if last_error is None:\\n                msg = f\\\"DNS pinning: All pinned IPs failed for {host} but no error was captured\\\"\\n                raise RuntimeError(msg)\\n            raise last_error\\n\\n        return self._backend.connect_tcp(\\n            host=host,\\n            port=port,\\n            timeout=timeout,\\n            local_address=local_address,\\n            socket_options=socket_options,\\n        )\\n\\n    def connect_unix_socket(\\n        self,\\n        path: str,\\n        timeout: float | None = None,\\n        socket_options: Iterable[httpcore.SOCKET_OPTION] | None = None,\\n    ) -> httpcore.NetworkStream:\\n        \\\"\\\"\\\"Connect to Unix socket (pass through to underlying backend).\\\"\\\"\\\"\\n        return self._backend.connect_unix_socket(\\n            path=path,\\n            timeout=timeout,\\n            socket_options=socket_options,\\n        )\\n\\n    def sleep(self, seconds: float) -> None:\\n        \\\"\\\"\\\"Sleep for specified duration (pass through to underlying backend).\\\"\\\"\\\"\\n        self._backend.sleep(seconds)\\n\\n\\nclass SSRFProtectedTransport(httpx.AsyncHTTPTransport):\\n    \\\"\\\"\\\"HTTP transport that pins DNS resolution to validated IPs.\\n\\n    This transport prevents DNS rebinding attacks by using a custom network backend\\n    that connects to pinned IP addresses while preserving the original hostname for\\n    TLS SNI and certificate verification.\\n\\n    Unlike the naive approach of rewriting URLs (which breaks HTTPS), this implementation\\n    works at the network layer to ensure both security and compatibility.\\n\\n    Example:\\n        >>> pinned_ips = {\\\"example.com\\\": \\\"93.184.216.34\\\"}\\n        >>> transport = SSRFProtectedTransport(pinned_ips=pinned_ips)\\n        >>> async with httpx.AsyncClient(transport=transport) as client:\\n        ...     # Request to example.com will connect to 93.184.216.34\\n        ...     # But TLS will still verify against example.com certificate\\n        ...     response = await client.get(\\\"https://example.com/path\\\")\\n    \\\"\\\"\\\"\\n\\n    def __init__(\\n        self,\\n        pinned_ips: dict[str, list[str]],\\n        verify: bool | str | ssl.SSLContext = True,  # noqa: FBT001, FBT002\\n        cert: tuple[str, str] | tuple[str, str, str] | str | None = None,\\n        trust_env: bool = True,  # noqa: FBT001, FBT002\\n        http1: bool = True,  # noqa: FBT001, FBT002\\n        http2: bool = False,  # noqa: FBT001, FBT002\\n        limits: httpx.Limits = httpx.Limits(),  # noqa: B008\\n        proxy: httpx._types.ProxyTypes | None = None,\\n        uds: str | None = None,\\n        local_address: str | None = None,\\n        retries: int = 0,\\n        socket_options: Iterable[httpcore.SOCKET_OPTION] | None = None,\\n    ):\\n        \\\"\\\"\\\"Initialize transport with pinned DNS mappings.\\n\\n        Args:\\n            pinned_ips: Dictionary mapping hostnames to list of validated IP addresses.\\n                       Example: {\\\"example.com\\\": [\\\"93.184.216.34\\\", \\\"2606:2800:220:1:248:1893:25c8:1946\\\"]}\\n            verify: SSL verification settings\\n            cert: Client certificate\\n            trust_env: Whether to trust environment variables for proxy config\\n            http1: Enable HTTP/1.1\\n            http2: Enable HTTP/2\\n            limits: Connection pool limits\\n            proxy: Proxy configuration\\n            uds: Unix domain socket path\\n            local_address: Local address to bind to\\n            retries: Number of retries\\n            socket_options: Socket options\\n        \\\"\\\"\\\"\\n        # Create custom network backend with DNS pinning\\n        network_backend = DNSPinningNetworkBackend(pinned_ips=pinned_ips)\\n\\n        # Create SSL context (same as parent class)\\n        ssl_context = create_ssl_context(verify=verify, cert=cert, trust_env=trust_env)\\n\\n        # Handle proxy (same as parent class)\\n        if proxy is not None:\\n            proxy = Proxy(url=proxy) if isinstance(proxy, (str, URL)) else proxy\\n\\n        # Create pool with our custom network backend\\n        # We replicate the parent's logic but add network_backend parameter\\n        if proxy is None:\\n            self._pool = httpcore.AsyncConnectionPool(\\n                ssl_context=ssl_context,\\n                max_connections=limits.max_connections,\\n                max_keepalive_connections=limits.max_keepalive_connections,\\n                keepalive_expiry=limits.keepalive_expiry,\\n                http1=http1,\\n                http2=http2,\\n                uds=uds,\\n                local_address=local_address,\\n                retries=retries,\\n                socket_options=socket_options,\\n                network_backend=network_backend,  # Our custom backend!\\n            )\\n        else:\\n            # For proxy scenarios, we'd need to handle HTTPProxy/SOCKSProxy\\n            # For now, raise an error as DNS pinning with proxies needs special handling\\n            msg = \\\"DNS pinning with proxies is not currently supported\\\"\\n            raise NotImplementedError(msg)\\n\\n        self.pinned_ips = pinned_ips\\n        logger.debug(f\\\"Created SSRF protected transport with pinned IPs: {pinned_ips}\\\")\\n\\n\\nclass SSRFProtectedSyncTransport(httpx.HTTPTransport):\\n    \\\"\\\"\\\"Synchronous HTTP transport that pins DNS resolution to validated IPs.\\\"\\\"\\\"\\n\\n    def __init__(\\n        self,\\n        pinned_ips: dict[str, list[str]],\\n        verify: bool | str | ssl.SSLContext = True,  # noqa: FBT001, FBT002\\n        cert: tuple[str, str] | tuple[str, str, str] | str | None = None,\\n        trust_env: bool = True,  # noqa: FBT001, FBT002\\n        http1: bool = True,  # noqa: FBT001, FBT002\\n        http2: bool = False,  # noqa: FBT001, FBT002\\n        limits: httpx.Limits = httpx.Limits(),  # noqa: B008\\n        proxy: httpx._types.ProxyTypes | None = None,\\n        uds: str | None = None,\\n        local_address: str | None = None,\\n        retries: int = 0,\\n        socket_options: Iterable[httpcore.SOCKET_OPTION] | None = None,\\n    ):\\n        network_backend = DNSPinningSyncNetworkBackend(pinned_ips=pinned_ips)\\n        ssl_context = create_ssl_context(verify=verify, cert=cert, trust_env=trust_env)\\n\\n        if proxy is not None:\\n            proxy = Proxy(url=proxy) if isinstance(proxy, (str, URL)) else proxy\\n\\n        if proxy is None:\\n            self._pool = httpcore.ConnectionPool(\\n                ssl_context=ssl_context,\\n                max_connections=limits.max_connections,\\n                max_keepalive_connections=limits.max_keepalive_connections,\\n                keepalive_expiry=limits.keepalive_expiry,\\n                http1=http1,\\n                http2=http2,\\n                uds=uds,\\n                local_address=local_address,\\n                retries=retries,\\n                socket_options=socket_options,\\n                network_backend=network_backend,\\n            )\\n        else:\\n            msg = \\\"DNS pinning with proxies is not currently supported\\\"\\n            raise NotImplementedError(msg)\\n\\n        self.pinned_ips = pinned_ips\\n        logger.debug(f\\\"Created synchronous SSRF protected transport with pinned IPs: {pinned_ips}\\\")\\n\\n\\ndef create_ssrf_protected_client(\\n    hostname: str, validated_ips: list[str] | tuple[str, ...], **client_kwargs\\n) -> httpx.AsyncClient:\\n    \\\"\\\"\\\"Create an httpx client with DNS pinning for SSRF protection.\\n\\n    Args:\\n        hostname: The hostname to pin\\n        validated_ips: List of validated IP addresses to use for this hostname.\\n                      IPs will be tried in order for dual-stack/load-balanced hosts.\\n        **client_kwargs: Additional arguments for AsyncClient (e.g., timeout, headers)\\n\\n    Returns:\\n        Configured AsyncClient with DNS pinning\\n    \\\"\\\"\\\"\\n    # Convert to list if tuple\\n    ip_list = list(validated_ips) if isinstance(validated_ips, tuple) else validated_ips\\n    transport = SSRFProtectedTransport(pinned_ips={hostname: ip_list})\\n    return httpx.AsyncClient(transport=transport, **client_kwargs)\\n\\n\\ndef create_ssrf_protected_sync_client(\\n    hostname: str, validated_ips: list[str] | tuple[str, ...], **client_kwargs\\n) -> httpx.Client:\\n    \\\"\\\"\\\"Create a synchronous httpx client with DNS pinning for SSRF protection.\\\"\\\"\\\"\\n    ip_list = list(validated_ips) if isinstance(validated_ips, tuple) else validated_ips\\n    transport = SSRFProtectedSyncTransport(pinned_ips={hostname: ip_list})\\n    return httpx.Client(transport=transport, **client_kwargs)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/utils/url_redaction.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"f1923a254ef1c9fda4e4d7e24ce4256000785587bfa902dccb11833a6d0697d1\",\"content\":\"\\\"\\\"\\\"Strip credentials out of URLs before they reach anyone reading a message.\\n\\nA URL is a common carrier for a secret \u2014 userinfo and query strings both routinely hold\\none \u2014 and the places a URL ends up (error messages, tracebacks, log aggregators, support\\ntickets) are exactly the places a secret must not. The reduction is deliberate rather than\\nclever: keep enough to identify the target, drop everything that can authenticate to it.\\n\\\"\\\"\\\"\\n\\nimport re\\nfrom urllib.parse import urlparse\\n\\nURL_IN_TEXT_PATTERN = re.compile(r\\\"[a-zA-Z][a-zA-Z0-9+.\\\\-]*://[^\\\\s'\\\\\\\"<>]+\\\")\\n\\n\\ndef sanitize_url_for_display(url: str) -> str:\\n    \\\"\\\"\\\"Reduce a URL to scheme, host, port and path.\\n\\n    The port has to survive: a target named without it is the wrong target whenever the\\n    plane runs on anything but 80/443.\\n    \\\"\\\"\\\"\\n    try:\\n        parsed = urlparse(url)\\n    except ValueError:\\n        return url\\n    if not parsed.scheme or not parsed.hostname:\\n        return url\\n    host = f\\\"{parsed.hostname}:{parsed.port}\\\" if parsed.port else parsed.hostname\\n    return f\\\"{parsed.scheme}://{host}{parsed.path}\\\"\\n\\n\\ndef redact_urls_in_text(text: str) -> str:\\n    \\\"\\\"\\\"Sanitize every URL embedded in text we did not compose.\\n\\n    Formatting our own targets safely is not enough. ``raise_for_status`` builds a message\\n    containing the full request URL, so a 401 arrives carrying the credential it just\\n    rejected, and that message is reproduced verbatim inside any traceback that crosses it.\\n    \\\"\\\"\\\"\\n    return URL_IN_TEXT_PATTERN.sub(lambda match: sanitize_url_for_display(match.group(0)), text)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/utils/util.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"5b0f39c1baf5faf8e1da95d5b664eaa1456be8c5c05bc4bb783c7f62ce87a44f\",\"content\":\"import difflib\\nimport importlib\\nimport inspect\\nimport json\\nimport os\\nimport re\\nimport socket\\nimport struct\\nfrom functools import wraps\\nfrom pathlib import Path\\nfrom typing import Any\\n\\nfrom docstring_parser import parse\\n\\nfrom lfx.log.logger import logger\\nfrom lfx.schema.data import Data\\nfrom lfx.services.deps import get_settings_service\\nfrom lfx.template.frontend_node.constants import FORCE_SHOW_FIELDS\\nfrom lfx.utils import constants\\n\\n\\ndef detect_container_environment() -> str | None:\\n    \\\"\\\"\\\"Detect if running in a container and return the appropriate container type.\\n\\n    Returns:\\n        'docker' if running in Docker, 'podman' if running in Podman, None otherwise.\\n    \\\"\\\"\\\"\\n    # Check for .dockerenv file (Docker)\\n    if Path(\\\"/.dockerenv\\\").exists():\\n        return \\\"docker\\\"\\n\\n    # Check cgroup for container indicators\\n    try:\\n        with Path(\\\"/proc/self/cgroup\\\").open() as f:\\n            content = f.read()\\n            if \\\"docker\\\" in content:\\n                return \\\"docker\\\"\\n            if \\\"podman\\\" in content:\\n                return \\\"podman\\\"\\n    except (FileNotFoundError, PermissionError):\\n        pass\\n\\n    # Check environment variables (lowercase 'container' is the standard for Podman)\\n    if os.getenv(\\\"container\\\") == \\\"podman\\\":  # noqa: SIM112\\n        return \\\"podman\\\"\\n\\n    return None\\n\\n\\ndef get_container_host() -> str | None:\\n    \\\"\\\"\\\"Get the hostname to access host services from within a container.\\n\\n    Tries multiple methods to find the correct hostname:\\n    1. host.containers.internal (Podman) or host.docker.internal (Docker)\\n    2. Gateway IP from routing table (fallback for Linux)\\n\\n    Returns:\\n        The hostname or IP to use, or None if not in a container.\\n    \\\"\\\"\\\"\\n    # Check if we're in a container first\\n    container_type = detect_container_environment()\\n    if not container_type:\\n        return None\\n\\n    # Try container-specific hostnames first based on detected type\\n    if container_type == \\\"podman\\\":\\n        # Podman: try host.containers.internal first\\n        try:\\n            socket.getaddrinfo(\\\"host.containers.internal\\\", None)\\n        except socket.gaierror:\\n            pass\\n        else:\\n            return \\\"host.containers.internal\\\"\\n\\n        # Fallback to host.docker.internal (for Podman Desktop on macOS)\\n        try:\\n            socket.getaddrinfo(\\\"host.docker.internal\\\", None)\\n        except socket.gaierror:\\n            pass\\n        else:\\n            return \\\"host.docker.internal\\\"\\n    else:\\n        # Docker: try host.docker.internal first\\n        try:\\n            socket.getaddrinfo(\\\"host.docker.internal\\\", None)\\n        except socket.gaierror:\\n            pass\\n        else:\\n            return \\\"host.docker.internal\\\"\\n\\n        # Fallback to host.containers.internal (unlikely but possible)\\n        try:\\n            socket.getaddrinfo(\\\"host.containers.internal\\\", None)\\n        except socket.gaierror:\\n            pass\\n        else:\\n            return \\\"host.containers.internal\\\"\\n\\n    # Fallback: try to get gateway IP from routing table (Linux containers)\\n    try:\\n        with Path(\\\"/proc/net/route\\\").open() as f:\\n            # Skip header\\n            next(f)\\n            for line in f:\\n                fields = line.strip().split()\\n                min_field_count = 3  # Minimum fields needed: interface, destination, gateway\\n                if len(fields) >= min_field_count and fields[1] == \\\"00000000\\\":  # Default route\\n                    # Gateway is in hex format (little-endian)\\n                    gateway_hex = fields[2]\\n                    # Convert little-endian hex to dotted IPv4\\n                    gw_int = int(gateway_hex, 16)\\n                    return socket.inet_ntoa(struct.pack(\\\"<L\\\", gw_int))\\n    except (FileNotFoundError, PermissionError, IndexError, ValueError):\\n        pass\\n\\n    return None\\n\\n\\ndef transform_localhost_url(url: str | None) -> str | None:\\n    \\\"\\\"\\\"Transform localhost URLs to container-accessible hosts when running in a container.\\n\\n    Automatically detects if running inside a container and finds the appropriate host\\n    address to replace localhost/127.0.0.1. Tries in order:\\n    - host.docker.internal (if resolvable)\\n    - host.containers.internal (if resolvable)\\n    - Gateway IP from routing table (fallback)\\n\\n    Args:\\n        url: The original URL, can be None or empty string\\n\\n    Returns:\\n        Transformed URL with container-accessible host if applicable, otherwise the original URL.\\n        Returns None if url is None, empty string if url is empty string.\\n\\n    Example:\\n        >>> transform_localhost_url(\\\"http://localhost:5001\\\")\\n        # Returns \\\"http://host.docker.internal:5001\\\" if running in Docker and hostname resolves\\n        # Returns \\\"http://172.17.0.1:5001\\\" if running in Docker on Linux (gateway IP fallback)\\n        # Returns \\\"http://localhost:5001\\\" if not in a container\\n        >>> transform_localhost_url(None)\\n        # Returns None\\n        >>> transform_localhost_url(\\\"\\\")\\n        # Returns \\\"\\\"\\n    \\\"\\\"\\\"\\n    # Guard against None and empty string to prevent TypeError\\n    if not url:\\n        return url\\n\\n    container_host = get_container_host()\\n\\n    if not container_host:\\n        return url\\n\\n    # Replace localhost and 127.0.0.1 with the container host\\n    localhost_patterns = [\\\"localhost\\\", \\\"127.0.0.1\\\"]\\n\\n    for pattern in localhost_patterns:\\n        if pattern in url:\\n            return url.replace(pattern, container_host)\\n\\n    return url\\n\\n\\ndef unescape_string(s: str):\\n    # Replace escaped new line characters with actual new line characters\\n    return s.replace(\\\"\\\\\\\\n\\\", \\\"\\\\n\\\")\\n\\n\\ndef remove_ansi_escape_codes(text):\\n    return re.sub(r\\\"\\\\x1b\\\\[[0-9;]*[a-zA-Z]\\\", \\\"\\\", text)\\n\\n\\ndef build_template_from_function(name: str, type_to_loader_dict: dict, *, add_function: bool = False):\\n    classes = [item.__annotations__[\\\"return\\\"].__name__ for item in type_to_loader_dict.values()]\\n\\n    # Raise error if name is not in chains\\n    if name not in classes:\\n        msg = f\\\"{name} not found\\\"\\n        raise ValueError(msg)\\n\\n    for _type, v in type_to_loader_dict.items():\\n        if v.__annotations__[\\\"return\\\"].__name__ == name:\\n            class_ = v.__annotations__[\\\"return\\\"]\\n\\n            # Get the docstring\\n            docs = parse(class_.__doc__)\\n\\n            variables = {\\\"_type\\\": _type}\\n            for class_field_items, value in class_.model_fields.items():\\n                if class_field_items == \\\"callback_manager\\\":\\n                    continue\\n                variables[class_field_items] = {}\\n                for name_, value_ in value.__repr_args__():\\n                    if name_ == \\\"default_factory\\\":\\n                        try:\\n                            variables[class_field_items][\\\"default\\\"] = get_default_factory(\\n                                module=class_.__base__.__module__, function=value_\\n                            )\\n                        except Exception:  # noqa: BLE001\\n                            logger.debug(f\\\"Error getting default factory for {value_}\\\", exc_info=True)\\n                            variables[class_field_items][\\\"default\\\"] = None\\n                    elif name_ != \\\"name\\\":\\n                        variables[class_field_items][name_] = value_\\n\\n                variables[class_field_items][\\\"placeholder\\\"] = docs.params.get(class_field_items, \\\"\\\")\\n            # Adding function to base classes to allow\\n            # the output to be a function\\n            base_classes = get_base_classes(class_)\\n            if add_function:\\n                base_classes.append(\\\"Callable\\\")\\n\\n            return {\\n                \\\"template\\\": format_dict(variables, name),\\n                \\\"description\\\": docs.short_description or \\\"\\\",\\n                \\\"base_classes\\\": base_classes,\\n            }\\n    return None\\n\\n\\ndef build_template_from_method(\\n    class_name: str,\\n    method_name: str,\\n    type_to_cls_dict: dict,\\n    *,\\n    add_function: bool = False,\\n):\\n    classes = [item.__name__ for item in type_to_cls_dict.values()]\\n\\n    # Raise error if class_name is not in classes\\n    if class_name not in classes:\\n        msg = f\\\"{class_name} not found.\\\"\\n        raise ValueError(msg)\\n\\n    for _type, v in type_to_cls_dict.items():\\n        if v.__name__ == class_name:\\n            class_ = v\\n\\n            # Check if the method exists in this class\\n            if not hasattr(class_, method_name):\\n                msg = f\\\"Method {method_name} not found in class {class_name}\\\"\\n                raise ValueError(msg)\\n\\n            # Get the method\\n            method = getattr(class_, method_name)\\n\\n            # Get the docstring\\n            docs = parse(method.__doc__)\\n\\n            # Get the signature of the method\\n            sig = inspect.signature(method)\\n\\n            # Get the parameters of the method\\n            params = sig.parameters\\n\\n            # Initialize the variables dictionary with method parameters\\n            variables = {\\n                \\\"_type\\\": _type,\\n                **{\\n                    name: {\\n                        \\\"default\\\": (param.default if param.default != param.empty else None),\\n                        \\\"type\\\": (param.annotation if param.annotation != param.empty else None),\\n                        \\\"required\\\": param.default == param.empty,\\n                    }\\n                    for name, param in params.items()\\n                    if name not in {\\\"self\\\", \\\"kwargs\\\", \\\"args\\\"}\\n                },\\n            }\\n\\n            base_classes = get_base_classes(class_)\\n\\n            # Adding function to base classes to allow the output to be a function\\n            if add_function:\\n                base_classes.append(\\\"Callable\\\")\\n\\n            return {\\n                \\\"template\\\": format_dict(variables, class_name),\\n                \\\"description\\\": docs.short_description or \\\"\\\",\\n                \\\"base_classes\\\": base_classes,\\n            }\\n    return None\\n\\n\\ndef get_base_classes(cls):\\n    \\\"\\\"\\\"Get the base classes of a class.\\n\\n    These are used to determine the output of the nodes.\\n    \\\"\\\"\\\"\\n    if hasattr(cls, \\\"__bases__\\\") and cls.__bases__:\\n        bases = cls.__bases__\\n        result = []\\n        for base in bases:\\n            if any(_type in base.__module__ for _type in [\\\"pydantic\\\", \\\"abc\\\"]):\\n                continue\\n            result.append(base.__name__)\\n            base_classes = get_base_classes(base)\\n            # check if the base_classes are in the result\\n            # if not, add them\\n            for base_class in base_classes:\\n                if base_class not in result:\\n                    result.append(base_class)\\n    else:\\n        result = [cls.__name__]\\n    if not result:\\n        result = [cls.__name__]\\n    return list({*result, cls.__name__})\\n\\n\\ndef get_default_factory(module: str, function: str):\\n    pattern = r\\\"<function (\\\\w+)>\\\"\\n\\n    if match := re.search(pattern, function):\\n        import warnings\\n\\n        with warnings.catch_warnings():\\n            warnings.filterwarnings(\\n                \\\"ignore\\\", message=\\\"Support for class-based `config` is deprecated\\\", category=DeprecationWarning\\n            )\\n            warnings.filterwarnings(\\\"ignore\\\", message=\\\"Valid config keys have changed in V2\\\", category=UserWarning)\\n            imported_module = importlib.import_module(module)\\n            return getattr(imported_module, match[1])()\\n    return None\\n\\n\\ndef update_verbose(d: dict, *, new_value: bool) -> dict:\\n    \\\"\\\"\\\"Recursively updates the value of the 'verbose' key in a dictionary.\\n\\n    Args:\\n        d: the dictionary to update\\n        new_value: the new value to set\\n\\n    Returns:\\n        The updated dictionary.\\n    \\\"\\\"\\\"\\n    for k, v in d.items():\\n        if isinstance(v, dict):\\n            update_verbose(v, new_value=new_value)\\n        elif k == \\\"verbose\\\":\\n            d[k] = new_value\\n    return d\\n\\n\\ndef sync_to_async(func):\\n    \\\"\\\"\\\"Decorator to convert a sync function to an async function.\\\"\\\"\\\"\\n\\n    @wraps(func)\\n    async def async_wrapper(*args, **kwargs):\\n        return func(*args, **kwargs)\\n\\n    return async_wrapper\\n\\n\\ndef format_dict(dictionary: dict[str, Any], class_name: str | None = None) -> dict[str, Any]:\\n    \\\"\\\"\\\"Formats a dictionary by removing certain keys and modifying the values of other keys.\\n\\n    Returns:\\n        A new dictionary with the desired modifications applied.\\n    \\\"\\\"\\\"\\n    for key, value in dictionary.items():\\n        if key == \\\"_type\\\":\\n            continue\\n\\n        type_: str | type = get_type(value)\\n\\n        if \\\"BaseModel\\\" in str(type_):\\n            continue\\n\\n        type_ = remove_optional_wrapper(type_)\\n        type_ = check_list_type(type_, value)\\n        type_ = replace_mapping_with_dict(type_)\\n        type_ = get_type_from_union_literal(type_)\\n\\n        value[\\\"type\\\"] = get_formatted_type(key, type_)\\n        value[\\\"show\\\"] = should_show_field(value, key)\\n        value[\\\"password\\\"] = is_password_field(key)\\n        value[\\\"multiline\\\"] = is_multiline_field(key)\\n\\n        if key == \\\"dict_\\\":\\n            set_dict_file_attributes(value)\\n\\n        replace_default_value_with_actual(value)\\n\\n        if key == \\\"headers\\\":\\n            set_headers_value(value)\\n\\n        add_options_to_field(value, class_name, key)\\n\\n    return dictionary\\n\\n\\n# \\\"Union[Literal['f-string'], Literal['jinja2']]\\\" -> \\\"str\\\"\\ndef get_type_from_union_literal(union_literal: str) -> str:\\n    # if types are literal strings\\n    # the type is a string\\n    if \\\"Literal\\\" in union_literal:\\n        return \\\"str\\\"\\n    return union_literal\\n\\n\\ndef get_type(value: Any) -> str | type:\\n    \\\"\\\"\\\"Retrieves the type value from the dictionary.\\n\\n    Returns:\\n        The type value.\\n    \\\"\\\"\\\"\\n    # get \\\"type\\\" or \\\"annotation\\\" from the value\\n    type_ = value.get(\\\"type\\\") or value.get(\\\"annotation\\\")\\n\\n    return type_ if isinstance(type_, str) else type_.__name__\\n\\n\\ndef remove_optional_wrapper(type_: str | type) -> str:\\n    \\\"\\\"\\\"Removes the 'Optional' wrapper from the type string.\\n\\n    Returns:\\n        The type string with the 'Optional' wrapper removed.\\n    \\\"\\\"\\\"\\n    if isinstance(type_, type):\\n        type_ = str(type_)\\n    if \\\"Optional\\\" in type_:\\n        type_ = type_.replace(\\\"Optional[\\\", \\\"\\\")[:-1]\\n\\n    return type_\\n\\n\\ndef check_list_type(type_: str, value: dict[str, Any]) -> str:\\n    \\\"\\\"\\\"Checks if the type is a list type and modifies the value accordingly.\\n\\n    Returns:\\n        The modified type string.\\n    \\\"\\\"\\\"\\n    if any(list_type in type_ for list_type in [\\\"List\\\", \\\"Sequence\\\", \\\"Set\\\"]):\\n        type_ = type_.replace(\\\"List[\\\", \\\"\\\").replace(\\\"Sequence[\\\", \\\"\\\").replace(\\\"Set[\\\", \\\"\\\")[:-1]\\n        value[\\\"list\\\"] = True\\n    else:\\n        value[\\\"list\\\"] = False\\n\\n    return type_\\n\\n\\ndef replace_mapping_with_dict(type_: str) -> str:\\n    \\\"\\\"\\\"Replaces 'Mapping' with 'dict' in the type string.\\n\\n    Returns:\\n        The modified type string.\\n    \\\"\\\"\\\"\\n    if \\\"Mapping\\\" in type_:\\n        type_ = type_.replace(\\\"Mapping\\\", \\\"dict\\\")\\n\\n    return type_\\n\\n\\ndef get_formatted_type(key: str, type_: str) -> str:\\n    \\\"\\\"\\\"Formats the type value based on the given key.\\n\\n    Returns:\\n        The formatted type value.\\n    \\\"\\\"\\\"\\n    if key == \\\"allowed_tools\\\":\\n        return \\\"Tool\\\"\\n\\n    if key == \\\"max_value_length\\\":\\n        return \\\"int\\\"\\n\\n    return type_\\n\\n\\ndef should_show_field(value: dict[str, Any], key: str) -> bool:\\n    \\\"\\\"\\\"Determines if the field should be shown or not.\\n\\n    Returns:\\n        True if the field should be shown, False otherwise.\\n    \\\"\\\"\\\"\\n    return (\\n        (value[\\\"required\\\"] and key != \\\"input_variables\\\")\\n        or key in FORCE_SHOW_FIELDS\\n        or any(text in key.lower() for text in [\\\"password\\\", \\\"token\\\", \\\"api\\\", \\\"key\\\"])\\n    )\\n\\n\\ndef is_password_field(key: str) -> bool:\\n    \\\"\\\"\\\"Determines if the field is a password field.\\n\\n    Returns:\\n        True if the field is a password field, False otherwise.\\n    \\\"\\\"\\\"\\n    return any(text in key.lower() for text";
